# --- Activity > Go: reach a building without the city map ------------------------------------------------------------
ACT_GO_BTN = (270, 750)                     # green Go button on an Activity task card
MORE_BTN = (488, 648)                       # the round "..." button in the right column (fallback; normally 110 px above the word Alliance)


def find_more_btn(shot):
    """The round '...' button: three orange dots in a row, ~17 px apart, in the right-hand column. -> (x, y) or None."""
    try:
        x0, y0 = 430, 420                                # below the event icons (their badges have orange dots too)
        hsv = cv2.cvtColor(shot[y0:880, x0:540], cv2.COLOR_BGR2HSV)
        m = cv2.inRange(hsv, (10, 120, 180), (30, 255, 255))
        n, _, st, cen = cv2.connectedComponentsWithStats(m)
        b = sorted((float(c[0]) + x0, float(c[1]) + y0) for c, a in zip(cen[1:], st[1:, 4]) if 40 <= a <= 100)
        for i, (ax, ay) in enumerate(b):
            row = [p for p in b if abs(p[1] - ay) <= 4 and 0 <= p[0] - ax <= 45]
            xs = sorted(p[0] for p in row)
            if len(xs) == 3 and all(12 <= xs[k + 1] - xs[k] <= 22 for k in range(2)):
                return int(xs[1]), int(ay)
    except Exception:
        pass
    return None


def open_more_menu(dev, cfg, stop, log):
    """City screen: open the '...' (More) menu. -> screenshot with 'Activity' in it, or None."""
    shot = dev.screenshot()
    mb = find_more_btn(shot)
    ab = None if mb else find_text(shot, ["Alliance"], region=(400, 200, 140, 740), cutoff=0.7)
    spots = ([mb] if mb else []) + ([(int(ab[0]) - 7, int(ab[1]) - 110)] if ab else []) + [MORE_BTN]
    for x, y in spots:
        dev.tap(x, y)
        for _ in range(4):                               # the menu can take a moment to open (animations, lag)
            _nap(stop, 0.9, 1.2)
            shot = dev.screenshot()
            if rd_seen(shot, ["Activity"], region=(0, 100, 540, 800)):
                return shot
        rd_snap(shot, "ago_more_miss")
        if view_of(shot, cfg) != "city":                 # something else opened: close it; on the bare city Back would ask to quit
            dev.back()
            _nap(stop, 0.8, 1.0)
        cancel_quit_dialog(dev, dev.screenshot(), lambda *_: None)
        _nap(stop, 0.5, 0.7)
    return None


def activity_go(dev, cfg, log, stop, tile, probe=False, route=False):
    was = getattr(dev, "_guard_busy", False)
    dev._guard_busy = True                               # the pop-up closer would shut the tile's Go card (seen 23 Oct)
    try:
        return _activity_go(dev, cfg, log, stop, tile, probe, route)
    finally:
        dev._guard_busy = was


def _activity_go(dev, cfg, log, stop, tile, probe=False, route=False):
    """More > Activity > tap the daily's tile > Go. The game moves the camera to the building (any culture, any city
    layout). probe=True saves a picture at every step (debug/duty_ago_*.png) and logs what is read. -> True when Go was pressed."""
    shot = open_more_menu(dev, cfg, stop, log)
    if shot is None:
        raise RuntimeError("the '...' menu with Activity did not open")
    rd_snap(shot, "ago_1_more")
    if not rd_tap(dev, stop, ["Activity"], region=(0, 100, 540, 800), wait=(1.6, 2.0), shot=shot):
        raise RuntimeError("no Activity in the '...' menu")
    key = max(tile.split(), key=len)                     # the game cuts tile labels ("eet Champion", "rade Carriage"): match the main word
    words = [tile, key] + ([key.rstrip("s")] if key.endswith("s") else [])
    hit = None
    tpl = "act_" + re.sub(r"[^a-z]+", "_", tile.lower()).strip("_")    # the tile's picture (labels are cut and hard to read)
    saw_chest = False
    for i in range(8):                                   # 3 tiles a row, the grid scrolls
        shot = dev.screenshot()
        rd_snap(shot, "ago_2_activity" if i == 0 else f"ago_scroll_{i}")
        if not saw_chest and has_template("act_done_chest") and find(shot, "act_done_chest", 0.85, (0, 260, 540, 700)):
            saw_chest = True
        if has_template(tpl):
            h = find(shot, tpl, 0.85, (0, 260, 540, 700))
            if h and 330 <= h[1] <= 885:                 # the whole picture on screen (a 76 px picture centred lower is cut off)
                hit = (h[0], h[1] - 45)                  # tapped 45 px lower below = the picture's centre
        if not hit:
            t = rd_find(shot, words, region=(0, 260, 540, 700), cutoff=0.75)
            hit = t if t and t[1] <= 760 else None
        if hit or stop.is_set():
            break
        dev.swipe(270, 820, 270, 520, 600)
        _nap(stop, 1.0, 1.2)
    if not hit:
        rd_snap(dev.screenshot(), "ago_2_notile")
        if not route and saw_chest:                       # a completed daily's tile turns into a reward chest (its picture is gone)
            log(f"[+]   {tile}: its tile is not on the Activity page but reward chests are - complete today")
            dev.back()
            _nap(stop, 0.8, 1.0)
            return "complete"
        raise RuntimeError(f"no '{tile}' tile on the Activity page")
    dev.tap(int(hit[0]), min(int(hit[1]) + 45, 900))      # the tile picture under its label
    _nap(stop, 1.4, 1.8)
    shot = dev.screenshot()
    rd_snap(shot, "ago_3_tile")
    if probe:
        log("[i]   Activity tile opened: " + " | ".join(t for t, _ in rd_lines(shot, (0, 200, 540, 700)))[:300])
    prog = re.search(r"progress[^0-9]*(\d+)\s*/\s*(\d+)", " ".join(t for t, _ in rd_lines(shot, (40, 380, 460, 200))).lower())
    if prog:
        log(f"[i]   {tile}: progress {prog.group(1)}/{prog.group(2)}")
        if not route and int(prog.group(1)) >= int(prog.group(2)) > 0:
            log(f"[+]   {tile}: already complete today")
            dev.back()
            _nap(stop, 0.8, 1.0)
            return "complete"
    go = rd_find(shot, ["Go"], region=(100, 680, 340, 140), cutoff=0.8)
    if go:
        dev.tap(int(go[0]), int(go[1]))
    elif prog or rd_seen(shot, ["Current Progress", "Complete all"], region=(40, 380, 460, 300)):
        dev.tap(*ACT_GO_BTN)                             # the card is open: its green Go button's fixed spot
    else:
        raise RuntimeError(f"no Go button on the '{tile}' card")
    _nap(stop, 2.5, 3.0)
    shot = dev.screenshot()
    rd_snap(shot, "ago_4_after_go")
    if probe:
        _nap(stop, 1.5, 2.0)
        later = dev.screenshot()
        rd_snap(later, "ago_5_later")
        name = ring_building_name(later)
        log(f"[i]   After Go: view {view_of(later, cfg)}, building label {name[0] if name else 'none'}; "
            + " | ".join(t for t, _ in rd_lines(later, (0, 100, 540, 760)))[:300])
    return True



_RING_OK = {}                                                       # serial -> (building, time) of the last confirmed ring
RING_OWN_ITEMS = {"tavern": ("recruit", "wheel", "fortune")}        # words only this building's ring menu carries
RING_OWN_ITEMS_TEXT = {"tavern": ["Wheel of Fortune", "Wheel of"]}


def open_building_here(dev, cfg, log, stop, bname, spots=None, how="the Activity route", trust=False):
    """The building is on screen (after Go: in the middle): tap it and check its ring menu carries the right name.
    A building reached this way is remembered by its picture (learn_building) for the days its tile is gone.
    -> True when that building's ring menu is open."""
    import difflib
    want = bname.lower()
    before = dev.screenshot()
    for x, y in (spots or [(300, 460), (270, 490), (330, 430), (270, 420)]):
        if stop.is_set():
            return False
        dev.tap(x, y)
        _nap(stop, 1.2, 1.5)
        shot = dev.screenshot()
        ring = find_detail_icon(shot)                      # picture check first (fast); text reads only when it is not there
        if not ring and want == "keep" and ch_on_page(shot):   # the champion's heart can open the Champion page itself
            return True
        if trust and ring and spots and (x, y) == tuple(spots[0]):   # owner 28 Oct: the building's own picture matched (>= 0.85) and its ring
            log(f"[i]   {bname} reached by {how} ({x},{y}) - ring open, picture trusted")   # opened at that spot: no name read
            _RING_OK[getattr(dev, "serial", "")] = (bname, time.time())
            return True
        if not ring:
            # Kiravik 27 Oct 19:02: a 'Congratulations! 25 Stamina' reward window sat over the Tavern and took all 7
            # taps. A window in the way -> close it, then tap this spot once more.
            if view_of(shot, cfg) != "city" or rd_seen(shot, ["Congratulations", "Claim", "Confirm", "OK"], region=(60, 300, 420, 400)):
                log(f"[i]   {bname}: a window is in the way at ({x},{y}) - closing it and tapping again")
                clear_popups(dev, cfg, log, stop, rounds=2)
                y = min(820, y + 50)                       # the game floats reward icons (chest, quest) ABOVE a building:
                dev.tap(x, y)                              # the tap hit that icon - the building's body sits below it
                _nap(stop, 1.2, 1.5)
                shot = dev.screenshot()
            if not find_detail_icon(shot):
                continue
        nm = (ring_building_name(shot) or ("",))[0].lower()
        own = RING_OWN_ITEMS.get(want)                     # Rob 27 Oct 19:57: the Tavern ring was open but its name read
        by_item = own and (any(k in nm for k in own) or    # as a ring item ('recruit', 'great') -> rejected 7 times
                           rd_seen(shot, RING_OWN_ITEMS_TEXT.get(want, []), region=(0, 100, 540, 760)))
        if by_item or want in nm or any(difflib.SequenceMatcher(None, want, w).ratio() >= 0.8 for w in re.findall(r"[a-z ]+", nm)):
            log(f"[i]   {bname} reached by {how} ({x},{y})")
            _RING_OK[getattr(dev, "serial", "")] = (bname, time.time())
            learn_building(dev, before, bname, x, y)
            return True
        log(f"[i]   after Go the menu at ({x},{y}) is '{nm or '?'}', not {bname}")
        close_ring(dev, stop, (x, y + 60))
    rd_snap(dev.screenshot(), "ago_6_nobuilding")
    log(f"[i]   {bname}: tapped {len(spots or [])} spot(s) at the expected place - no building menu opened")
    return False


# --- learned building pictures: Activity Go teaches the bot where a building is (per instance, any city style) ----------
LEARN_DIR = USER / "city_learn"




def _pinned(dev, bname):
    """Does this building have a place on the instance's keyframe map (learned at an earlier open)?"""
    try:
        if json.loads(_learn_path(dev, bname).with_suffix(".json").read_text(encoding="utf-8")).get("map"):
            return True
    except Exception:
        pass
    return culture_pin(dev, bname) is not None


def _learn_path(dev, bname):
    return LEARN_DIR / re.sub(r"[^\w.-]+", "_", str(getattr(dev, "serial", "default"))) / (re.sub(r"[^a-z]+", "_", bname.lower()).strip("_") + ".png")


def learn_building(dev, shot, bname, x, y):
    """Save the building's own picture (around the spot that opened it, a little below so bubbles above it are left out)."""
    try:
        x0, y0 = max(0, x - 70), max(0, y - 45)
        crop = shot[y0:y0 + 130, x0:x0 + 140]
        if crop.shape[0] < 100 or crop.shape[1] < 100:
            return
        p = _learn_path(dev, bname)
        p.parent.mkdir(parents=True, exist_ok=True)
        meta = {}
        try:                                               # keep the map place learned earlier (and the last picture)
            meta = json.loads(p.with_suffix(".json").read_text(encoding="utf-8"))
            if p.exists():
                p.replace(p.with_name(p.stem + "_prev.png"))
        except Exception:
            meta = {}
        cv2.imwrite(str(p), crop)
        meta.update({"dx": x - x0, "dy": y - y0, "at": time.strftime("%Y-%m-%d %H:%M"),
                     "named": time.strftime("%Y-%m-%d %H:%M")})   # owner 28 Oct: only saved after its menu NAME was checked
        try:                                               # PIN the building on the keyframe map: every successful open on the city
            cmap = city_map(dev) if not meta.get("map") else None   # pinned already (a pin never moves): skip the slow locate
            if cmap is not None:                           # next visit is locate -> a few measured drags -> tap (owner 24 Oct: the
                loc = cmap.locate(shot)                    # Activity tile is a teacher, the map is the way)
                if loc and not meta.get("map"):            # owner spec 28 Oct: a pin, once set, never moves (only Map city again)
                    meta["map"] = [round(loc[0] + x), round(loc[1] + y)]
                    meta["by"] = "bot"
        except Exception:
            pass
        (p.with_suffix(".json")).write_text(json.dumps(meta), encoding="utf-8")
    except Exception:
        pass


PIN_FIRST_SCORE = 0.80     # owner 28 Oct: a picture match this strong is PINNED at once, the tap only confirms it


def pin_from_picture(dev, bname, mapx, mapy, score):
    """Owner 28 Oct 09:36: 'bot should pin first and then tap' - pin a movable building straight from a strong picture
    match. by='picture' (shown as found; the owner reports wrong ones and fixes them in Fix pins). An existing pin never
    moves. Not 'named': an unconfirmed pin never adds its picture to the database. -> True when pinned now."""
    try:
        p = _learn_path(dev, bname)
        js = p.with_suffix(".json")
        meta = json.loads(js.read_text(encoding="utf-8")) if js.exists() else {"dx": 0, "dy": 0}
        if meta.get("map"):
            return False
        meta["map"] = [round(mapx), round(mapy)]
        meta["by"] = "picture"
        meta["pic_score"] = round(float(score), 2)
        meta["pinned"] = time.strftime("%Y-%m-%d %H:%M")
        js.parent.mkdir(parents=True, exist_ok=True)
        js.write_text(json.dumps(meta), encoding="utf-8")
        return True
    except Exception as _e:
        quiet_err("pin_from_picture", _e)
        return False


def _learn_match(shot, tpl):
    """Best match of a learned picture on the city view, at a few sizes. -> (score, (x, y) top-left on screen, size)"""
    best = (0.0, None, 1.0)
    for f in (1.0, 1.2, 1.4, 1.6, 1.8, 2.0, 0.8, 0.7, 0.6):   # the city may be zoomed in or out compared with the learning time
        t = tpl if f == 1.0 else cv2.resize(tpl, None, fx=f, fy=f, interpolation=cv2.INTER_LINEAR)
        if t.shape[0] >= 760 or t.shape[1] >= 460:
            continue
        r = cv2.matchTemplate(shot[90:860, 0:470], t, cv2.TM_CCOEFF_NORMED)
        _, v, _, l = cv2.minMaxLoc(r)
        if v > best[0]:
            best = (v, (l[0], l[1] + 90), f)
        if v >= 0.85:
            break
    return best


def find_learned_building(dev, cfg, log, stop, bname):
    """Go to the building's PIN on this city's map and open it there (owner spec 28 Oct: positions never change - upgrades
    and skins only change the look - so the pin is the way; no searching the city). -> True when its ring menu is open."""
    p = _learn_path(dev, bname)
    pin = culture_pin(dev, bname)
    meta, tpl = {}, None
    try:
        meta = json.loads(p.with_suffix(".json").read_text(encoding="utf-8"))
    except Exception:
        meta = {}
    if p.exists():
        tpl = cv2.imread(str(p))
    if not meta.get("map"):
        if pin is None:
            log(f"[i]   {bname}: not pinned on this city")
            return False
        meta = dict(meta, map=pin)
    meta.setdefault("dx", 0)
    meta.setdefault("dy", 0)
    return bool(find_on_map(dev, cfg, log, stop, bname, tpl, meta, p))


# --- the instance's own city map (owner 23 Oct): a KEYFRAME map - every kept view is stored with its map place; after that
#     any city screenshot tells where the camera is, and a building is reached in a few measured drags ----------------------
#     Places are solved from ALL pairwise picture links at once (least squares), never from the finger: the stitched map.png
#     drifted and doubled the wall when views were placed by the drags (Kiravik 23 Oct, 60 views); the same 60 views solved
#     this way give one consistent map (56 placed, 4 countryside views dropped, residual < 2 px, locate 56/56 at < 1 px).
_CITY_MAPS = {}                                            # serial -> CityMap (features + index computed once)
KF_MIN_PTS = 60                                            # agreeing feature points for a link / a locate
KF_MIN_NCC = 0.5                                           # pixel correlation of the overlap: kills links between non-overlapping views
                                                           # made by the static HUD pixels inside CITY_VIEW (a confident 0,0 shift)
KF_MAP_MINUTES = 45                                        # hard cap only; the walk ends by itself when every view is explored


def _map_dir(dev):
    return LEARN_DIR / re.sub(r"[^\w.-]+", "_", str(getattr(dev, "serial", "default")))


def _kf_gray(img):
    x, y, w, h = CITY_VIEW
    return cv2.cvtColor(img[y:y + h, x:x + w], cv2.COLOR_BGR2GRAY)


def _kf_feats(gray):
    if _ORB[0] is None:
        _ORB[0] = cv2.ORB_create(2500)
    return _ORB[0].detectAndCompute(gray, None)


def _kf_consensus(d, min_pts=KF_MIN_PTS, step=300):
    """The shift most of the match vectors `d` agree on (within 6 px). -> (dx, dy, n) or None."""
    if len(d) < min_pts:
        return None
    best_n, best = 0, None
    for i in range(0, len(d), max(1, len(d) // step)):
        n = int(np.sum(np.all(np.abs(d - d[i]) < 6, axis=1)))
        if n > best_n:
            best_n, best = n, d[i]
    if best_n < min_pts:
        return None
    inl = d[np.all(np.abs(d - best) < 6, axis=1)]
    return float(inl[:, 0].mean()), float(inl[:, 1].mean()), best_n


def _kf_ncc(ga, gb, dx, dy):
    """Pixel correlation of the overlap when the content of `ga` sits (dx, dy) further in `gb`. 0 = no / tiny overlap."""
    dx, dy = int(round(dx)), int(round(dy))
    h, w = ga.shape
    ow, oh = w - abs(dx), h - abs(dy)
    if ow < 60 or oh < 60 or ow * oh < 30000:
        return 0.0
    a = ga[max(0, -dy):max(0, -dy) + oh, max(0, -dx):max(0, -dx) + ow].astype(np.float32)
    b = gb[max(0, dy):max(0, dy) + oh, max(0, dx):max(0, dx) + ow].astype(np.float32)
    a -= a.mean()
    b -= b.mean()
    den = float(np.sqrt((a * a).sum() * (b * b).sum()))
    return float((a * b).sum() / den) if den > 0 else 0.0


def _kf_link(fa, fb, ga, gb):
    """Picture link between two views: content of a found (dx, dy) further in b. -> (dx, dy, points) or None."""
    (ka, da), (kb, db) = fa, fb
    if da is None or db is None or len(ka) < 30 or len(kb) < 30:
        return None
    m = cv2.BFMatcher(cv2.NORM_HAMMING, crossCheck=True).match(da, db)
    if len(m) < 30:
        return None
    d = np.float32([kb[q.trainIdx].pt for q in m]) - np.float32([ka[q.queryIdx].pt for q in m])
    s = _kf_consensus(d)
    if not s or abs(s[0]) >= ga.shape[1] * 0.95 or abs(s[1]) >= ga.shape[0] * 0.95:
        return None
    if _kf_ncc(ga, gb, s[0], s[1]) < KF_MIN_NCC:
        return None
    return s


def _kf_links_all(views, w, h, min_pts=KF_MIN_PTS):
    """All picture links between the views at once: ONE feature index over every view, one search per view, consensus
    per other view, winner checked by the pixels (the way locate() works). -> [(i, j, dx, dy, points)] with i < j.
    The pairwise BFMatcher took 583 s for 48 views (Kiravik 24 Oct 04:55); this is the same search locate() does in
    about 1 s per view."""
    descs, labels, pts = [], [], []
    for n, (g, (k, d)) in enumerate(views):
        if d is None or len(k) < 30:
            continue
        descs.append(d)
        labels.append(np.full(len(k), n))
        pts.append(np.float32([q.pt for q in k]))
    if len(descs) < 2:
        return []
    labels = np.concatenate(labels)
    allpts = np.vstack(pts)
    index = cv2.FlannBasedMatcher(dict(algorithm=6, table_number=6, key_size=12, multi_probe_level=1), dict(checks=50))
    index.add([np.vstack(descs)])
    index.train()
    edges = []
    for i, (gi, (ki, di)) in enumerate(views):
        if di is None or len(ki) < 30:
            continue
        pi = np.float32([q.pt for q in ki])
        ms = index.knnMatch(di, k=4)
        qi = np.array([m.queryIdx for mm in ms for m in mm], dtype=np.int64)
        ti = np.array([m.trainIdx for mm in ms for m in mm], dtype=np.int64)
        if len(qi) < min_pts:
            continue
        lab = labels[ti]
        for j in np.unique(lab):
            j = int(j)
            if j <= i:                                     # each pair once (i < j); never a view with itself
                continue
            sel = lab == j
            if sel.sum() < min_pts:
                continue
            s = _kf_consensus(allpts[ti[sel]] - pi[qi[sel]], min_pts)   # content of i found (dx, dy) further in j
            if not s or abs(s[0]) >= w * 0.95 or abs(s[1]) >= h * 0.95:
                continue
            if _kf_ncc(gi, views[j][0], s[0], s[1]) < KF_MIN_NCC:
                continue
            edges.append((i, j, s[0], s[1], s[2]))
    return edges


def _kf_solve(n, edges):
    """Camera places from pairwise links (edge i->j with shift (dx, dy) means place_j = place_i - (dx, dy)). Weighted least
    squares with view 0 fixed; links whose residual is over 6 px (repeating art) are dropped and it is solved again;
    views left without a link to the main group are dropped. -> (kept view indices, xs, ys)."""
    kept = list(range(n))
    E = list(edges)

    def groups(k, es):
        parent = {v: v for v in k}

        def f(a):
            while parent[a] != a:
                parent[a] = parent[parent[a]]
                a = parent[a]
            return a
        for i, j, *_ in es:
            parent[f(i)] = f(j)
        g = {}
        for v in k:
            g.setdefault(f(v), []).append(v)
        return sorted(g.values(), key=len, reverse=True)

    def solve(k, es):
        idx = {v: q for q, v in enumerate(k)}
        A, bx, by, ws = [], [], [], []
        for i, j, dx, dy, w in es:
            r = np.zeros(len(k))
            r[idx[j]] = 1
            r[idx[i]] = -1
            A.append(r)
            bx.append(-dx)
            by.append(-dy)
            ws.append(np.sqrt(w))
        r = np.zeros(len(k))
        r[0] = 1
        A.append(r)
        bx.append(0.0)
        by.append(0.0)
        ws.append(100.0)
        A = np.array(A) * np.array(ws)[:, None]
        px = np.linalg.lstsq(A, np.array(bx) * ws, rcond=None)[0]
        py = np.linalg.lstsq(A, np.array(by) * ws, rcond=None)[0]
        return idx, px, py

    for _ in range(8):
        kept = groups(kept, E)[0] if E else kept[:1]
        E = [e for e in E if e[0] in kept and e[1] in kept]
        if not E:
            break
        idx, px, py = solve(kept, E)
        res = np.array([max(abs(px[idx[j]] - px[idx[i]] + dx), abs(py[idx[j]] - py[idx[i]] + dy)) for i, j, dx, dy, w in E])
        if res.max() <= 6:
            break
        worst = set(np.argsort(-res)[:max(1, int((res > 6).sum() * 0.3))].tolist())
        E = [e for q, e in enumerate(E) if q not in worst]
    if not E:
        return kept[:1], np.zeros(1), np.zeros(1)
    idx, px, py = solve(kept, E)
    return kept, px - px.min(), py - py.min()


class CityMap:
    """The keyframe map of one city: city_learn/<serial>/kf.json (place per keyframe) + kf_NN.png (CITY_VIEW crops).
    A 'camera place' is the map coordinate of screen point (0, 0), so screen (sx, sy) = map (cx + sx, cy + sy)."""

    def __init__(self, path):
        self.path = path                                   # .../map.png (the stitched picture, for looking at)
        try:
            self.meta = json.loads(path.with_suffix(".json").read_text(encoding="utf-8"))
        except Exception:
            self.meta = {}
        self.kf = []                                       # [(x, y, gray, keypoints)]
        self.index = None
        self.labels = self.pts = None
        self.half = bool(self.meta.get("half"))            # shipped culture map: half-size pictures + precomputed features
        try:
            for v in self.meta.get("keyframes", []):
                im = cv2.imread(str(path.parent / v["file"]), cv2.IMREAD_GRAYSCALE)
                if im is not None:
                    if self.half:                          # back to the view size for the pixel check (the shot is blurred the same way)
                        im = cv2.resize(im, (CITY_VIEW[2], CITY_VIEW[3]), interpolation=cv2.INTER_LINEAR)
                    self.kf.append((float(v["x"]), float(v["y"]), im, None))
            if self.meta.get("feats"):
                self._load_feats(path.parent / self.meta["feats"])
        except Exception:
            self.kf = []

    def _load_feats(self, p):
        """Features computed at full size when the culture map was packed (cultures/<c>/feats.npz: pts, desc, label)."""
        with np.load(str(p), allow_pickle=False) as z:
            pts, desc, lab = z["pts"].astype(np.float32), z["desc"].astype(np.uint8), z["label"].astype(np.int64)
        if len(desc) != len(pts) or len(desc) != len(lab) or not len(desc) or lab.max() >= len(self.kf):
            raise ValueError("feats.npz does not fit map.json")
        self.labels, self.pts = lab, pts
        self.index = cv2.FlannBasedMatcher(dict(algorithm=6, table_number=6, key_size=12, multi_probe_level=1), dict(checks=50))
        self.index.add([desc])
        self.index.train()

    def ok(self):
        return len(self.kf) >= 2

    def _build(self):
        """Feature index over ALL keyframes at once (one search per locate instead of one per keyframe: 1.0 s instead of
        5.7 s for 56 keyframes)."""
        if self.index is not None:
            return
        descs, labels, pts = [], [], []
        for n, (x, y, g, _) in enumerate(self.kf):
            k, d = _kf_feats(g)
            if d is None:
                continue
            descs.append(d)
            labels.append(np.full(len(k), n))
            pts.append(np.float32([q.pt for q in k]))
        self.labels = np.concatenate(labels)
        self.pts = np.vstack(pts)
        self.index = cv2.FlannBasedMatcher(dict(algorithm=6, table_number=6, key_size=12, multi_probe_level=1), dict(checks=50))
        self.index.add([np.vstack(descs)])
        self.index.train()

    def locate(self, shot, min_pts=KF_MIN_PTS):
        """Camera place from any city screenshot: its feature points searched in all keyframes at once, the keyframe
        whose points agree on one shift wins once the pixels of the overlap agree too. -> (cx, cy, points) or None."""
        try:
            self._build()
            g = _kf_gray(shot)
            if float(g.std()) < 12:
                return None
            k, d = _kf_feats(g)
            halt_check()                                   # a locate takes seconds on a busy PC: Stop between its steps
            if d is None or len(k) < 30:
                return None
            pts = np.float32([q.pt for q in k])
            ms = self.index.knnMatch(d, k=3)
            halt_check()
            qi = np.array([m.queryIdx for mm in ms for m in mm], dtype=np.int64)
            ti = np.array([m.trainIdx for mm in ms for m in mm], dtype=np.int64)
            if len(qi) < min_pts:
                return None
            lab = self.labels[ti]
            cands = []
            for n in np.unique(lab):
                sel = lab == n
                if sel.sum() < min_pts:
                    continue
                s = _kf_consensus(pts[qi[sel]] - self.pts[ti[sel]], min_pts)
                if s:
                    cands.append((s[2], int(n), s[0], s[1]))
            cands.sort(reverse=True)
            if self.half:                                  # same blur as the half-size keyframes
                g = cv2.resize(cv2.resize(g, (g.shape[1] // 2, g.shape[0] // 2), interpolation=cv2.INTER_AREA),
                               (g.shape[1], g.shape[0]), interpolation=cv2.INTER_LINEAR)
            for npts, n, dx, dy in cands[:4]:
                if _kf_ncc(self.kf[n][2], g, dx, dy) >= KF_MIN_NCC:
                    return self.kf[n][0] - dx, self.kf[n][1] - dy, npts
            return None
        except Exception:
            return None


def city_map(dev):
    """The instance's own map, or None when 'Map my city' has not been run yet (or the old stitched-only map is there)."""
    key = str(getattr(dev, "serial", "default"))
    if not getattr(dev, "_mapping", False) and not city_mapped(dev):
        return None                                        # owner spec 28 Oct: 0 map until Map my city has run
    cult = city_culture(dev)
    if cult:                                               # matched to a shipped culture map (owner 25 Oct: no 20-min walk)
        cm = culture_map(cult["culture"])
        if cm is not None:
            return cm
    m = _CITY_MAPS.get(key)
    p = _map_dir(dev) / "map.png"
    if m is None or (p.exists() and m.path.stat().st_mtime != m.meta.get("_mtime")):
        if not p.exists():
            return None
        m = CityMap(p)
        m.meta["_mtime"] = p.stat().st_mtime
        _CITY_MAPS[key] = m
    return m if m.ok() else None


# --- culture reference maps (24 Oct): one keyframe map per city culture, packed from the owner's own accounts and shipped
#     with the app (cultures/<culture>/: map.json + feats.npz + kf_NN.jpg half-size grey + map.jpg). Read-only. -----------
CULTURES = ("europe", "russia", "china", "korea", "japan", "arabia", "america")
_CULTURE_MAPS = {}                                         # culture -> CityMap or None


def culture_dir(name):
    """The newest copy of a culture map: the one the update downloaded (USER) wins over the one in the installer (RES)."""
    for root in (USER / "cultures", RES / "cultures"):
        if (root / name / "map.json").exists():
            return root / name
    return None


def culture_map(name):
    """The shipped reference map of one culture (cached), or None when it is not on this PC."""
    name = str(name or "").lower()
    if name not in CULTURES:
        return None
    if name not in _CULTURE_MAPS:
        d = culture_dir(name)
        m = CityMap(d / "map.png") if d else None          # CityMap reads map.json next to it; map.png itself is not needed
        _CULTURE_MAPS[name] = m if m is not None and m.ok() and m.index is not None else None
    return _CULTURE_MAPS[name]


CULTURE_MARGIN = 1.5                                       # the best culture needs this many times the 2nd best's points
                                                           # (false hits on another culture share walls/terrain - 24 Oct test)


def match_culture(shot):
    """Which shipped culture map does this widest-zoom city screenshot belong to? Located on ALL cultures, the one with
    the most agreeing points wins only with a clear margin. -> (culture, cx, cy, points, second_best) or None."""
    hits = []
    for c in CULTURES:
        m = culture_map(c)
        loc = m.locate(shot) if m is not None else None
        if loc:
            hits.append((loc[2], c, loc[0], loc[1]))
    if not hits:
        return None
    hits.sort(reverse=True)
    second = hits[1][0] if len(hits) > 1 else 0
    if hits[0][0] < KF_MIN_PTS or hits[0][0] < second * CULTURE_MARGIN:
        return None
    return hits[0][1], hits[0][2], hits[0][3], hits[0][0], second


def city_culture(dev):
    """The culture this instance's city was matched to (city_learn/<serial>/culture.json), or None."""
    try:
        c = json.loads((_map_dir(dev) / "culture.json").read_text(encoding="utf-8"))
        return c if c.get("culture") in CULTURES else None
    except Exception:
        return None


def culture_pins(name):
    """Fixed-building places on a culture map: cultures/<c>/pins.json {building: [x, y]} (map coordinates)."""
    d = culture_dir(name) if name else None
    try:
        return {str(k): [float(v[0]), float(v[1])] for k, v in json.loads((d / "pins.json").read_text(encoding="utf-8")).items()}
    except Exception:
        return {}


def culture_pin(dev, bname):
    """The shipped pin of a building for this instance's matched culture, or None."""
    cult = city_culture(dev)
    if not cult or (not getattr(dev, "_mapping", False) and not city_mapped(dev)):
        return None                                        # owner spec 28 Oct: fixed pins arrive with Map my city
    pins = {**culture_pins(cult["culture"]), **pins_override(dev)}   # Fix pins > Adjust: this instance only (owner 27 Oct)
    want = re.sub(r"[^a-z]+", "", str(bname).lower())
    v = next((v for k, v in reversed(list(pins.items())) if re.sub(r"[^a-z]+", "", k.lower()) == want), None)
    # Pins are set on the map picture, whose pixel (0,0) is the CITY_VIEW corner of a keyframe; navigation works in
    # screen-corner places (screen = place - camera). Stalds / Rory / Kiravik 27 Oct: every culture-pin tap landed
    # ~80,100 px up-left of the building (stairs instead of the Tavern) -> shift the pin into the navigation frame.
    return [v[0] + CITY_VIEW[0], v[1] + CITY_VIEW[1]] if v else None


def pins_override(dev):
    """Fixed-building pins the user moved for THIS instance only (Fix pins > Adjust), in culture map picture pixels.
    The shipped culture pins never change."""
    try:
        return json.loads((_map_dir(dev) / "pins_override.json").read_text(encoding="utf-8"))
    except Exception:
        return {}


def _drop_own_places(dev):
    """Learned buildings' map places belong to one map: forget them when the instance changes map."""
    for p in _map_dir(dev).glob("*.json"):
        if p.stem not in ("map", "culture") and not p.stem.endswith("_prev"):
            try:
                m = json.loads(p.read_text(encoding="utf-8"))
                if "map" in m and m.get("by") != "user":   # pins the user placed by hand (Fix pins) stay
                    m.pop("map", None)
                    p.write_text(json.dumps(m), encoding="utf-8")
            except Exception:
                pass


def try_culture_match(dev, cfg, log, stop, nav=None):
    """Map my city, culture first: up to 3 widest-zoom screenshots (moved between) located on every culture map.
    A clear winner is saved as culture.json and used as the instance's city map. -> culture name or None."""
    if not any(culture_map(c) is not None for c in CULTURES):
        log("[i]   Map my city: no culture maps on this PC - walking the city")
        return None
    seen = []
    for i, move in enumerate(((0, 0), (300, 0), (-300, 400))):
        if stop.is_set():
            return None
        if i and nav is not None:
            nav.pan(*move)
        shot = dev.screenshot()
        if view_of(shot, cfg) != "city":
            leave_to_city(dev, cfg, stop, log)
            shot = dev.screenshot()
        r = match_culture(shot)
        if r:
            name, cx, cy, pts, second = r
            d = _map_dir(dev)
            d.mkdir(parents=True, exist_ok=True)
            was = city_culture(dev)
            if not was or was.get("culture") != name:
                _drop_own_places(dev)                      # places learned on another map do not fit this one
            if (d / "map.json").exists():                  # 27 Oct: an old own map left here wiped every mapped building on
                try:                                       # each Map my city run - keep it aside once, never wipe again
                    (d / "map.json").replace(d / "map_prev.json")
                except OSError:
                    pass
            (d / "culture.json").write_text(json.dumps({"culture": name, "score": pts, "second": second,
                                                        "at": time.strftime("%Y-%m-%d %H:%M")}), encoding="utf-8")
            _CITY_MAPS.pop(str(getattr(dev, "serial", "default")), None)
            log(f"[+]  Map my city: the city matches the {name.title()} culture map ({pts} points, next best {second}) - no walk needed")
            return name
        seen.append("no clear match")
    log(f"[i]   Map my city: no culture map matched clearly ({len(seen)} views) - walking the city")
    return None


def _at_map_zoom(dev, shot):
    """Is the city at the zoom the maps were made at (fully out)? True when the screen locates on this instance's own
    map or on a culture map (the locate's pixel check fails at another zoom)."""
    try:
        cm = city_map(dev)
        if cm is not None:                                 # owner 30 Oct 12:13: the own map decides - the 5 culture maps
            return bool(cm.locate(shot))                   # cost ~20 s and are only for a city with no own map yet
        for c in CULTURES:
            m = culture_map(c)
            if m is not None and m.locate(shot):
                return True
    except Exception as _e:
        quiet_err("at_map_zoom", _e)
    return False



def ensure_city_zoom(dev, cfg, stop, log):
    """Owner 30 Oct 11:45 + 11:54: every city duty starts zoomed out. Look first: already out -> carry on, no zooming.
    Not out -> ONE zoom-out (Ctrl+wheel), look again and carry on either way. A view that does not change is not an
    error: no loop of zoom tries, no real-mouse wait, never a reason to give up the task. -> True when confirmed out."""
    try:
        if not _on_city_now(dev, cfg):
            leave_to_city(dev, cfg, stop, log)
        if stop.is_set():
            return False
        before = dev.screenshot()
        if time.time() - getattr(dev, "_zoom_ok_at", 0) < 600:    # located on the map in the last 10 min: zoom is right,
            return True                                    # no extra ~20 s locate (the user rarely zooms by hand)
        if _at_map_zoom(dev, before):
            dev.zoomed_out = True
            dev._zoom_ok_at = time.time()
            return True
        name = (load_config().get("device_names") or {}).get(dev.serial)
        if not wheel_zoom_out(dev, log, name):
            log("[i]   zoom: could not send the zoom-out - carrying on with the task at this zoom")
            return False
        _nap(stop, 1.0, 1.3)
        after = dev.screenshot()
        if _at_map_zoom(dev, after):
            dev.zoomed_out = True
            dev._zoom_ok_at = time.time()
            log("[i]   zoom: zoomed out - the city now matches the map")
            return True
        sc = _view_scale(before, after)
        if sc and sc < 0.97:
            log(f"[i]   zoom: zoomed out (view {sc:.2f}x) - carrying on")
        else:
            log("[i]   zoom: the view did not change (probably already out) - carrying on with the task")
        return False
    except Exception as _e:
        quiet_err("ensure_city_zoom", _e)
        return False


def zoom_out_full(dev, cfg, stop, log):
    """All the way out: Ctrl+wheel until the picture stops getting smaller (Kiravik 23 Oct: the two-notch zoom of the duties
    left the city 1.8x bigger than the game's own widest view, so the map needed 56 views instead of ~8)."""
    shot0 = dev.screenshot()                               # owner 28 Oct 12:49: zoom (wheel, pinch) ONLY on the city view - on
    if purchase_guard(dev, shot0, log):                    # K it scrolled the Store and the pinch opened Google Play
        shot0 = dev.screenshot()
    def on_city(sh):
        if screen_state(sh, cfg) == "city":
            return True
        cm = city_map(dev)
        return bool(cm is not None and cm.locate(sh))
    if not on_city(shot0):
        leave_to_city(dev, cfg, stop, log)
        shot0 = dev.screenshot()
        if not on_city(shot0):
            log("[i]   zoom: the city view is not on screen - no zoom (nothing is scrolled or pinched elsewhere)")
            return
    if cfg.get("zoom_out", False):
        zoom_out_city(dev, stop, log)
    name = (load_config().get("device_names") or {}).get(dev.serial)
    use_real = False
    for i in range(6):
        if stop.is_set():
            return
        before = dev.screenshot()
        if not (real_wheel_zoom_out(dev, log, name, stop=stop) if use_real else wheel_zoom_out(dev, log, name)):
            return
        _nap(stop, 1.0, 1.3)
        sc = _view_scale(before, dev.screenshot())
        if (not sc or sc >= 0.97) and i == 0 and not use_real:
            # Stalds 27 Oct 20:21: the city was ALREADY fully out, so the first notch changed nothing and the bot went to
            # the real-mouse fallback, which waits up to 2 min x3 while the owner uses the PC. Test with one notch IN:
            # the view grows = window messages work and the city was fully out -> zoom back out, done.
            b0 = dev.screenshot()
            if wheel_zoom_out(dev, log, name, notches=1, up=True):
                _nap(stop, 1.0, 1.3)
                s0 = _view_scale(b0, dev.screenshot())
                if s0 and s0 > 1.03:
                    wheel_zoom_out(dev, log, name, notches=3)
                    _nap(stop, 1.0, 1.3)
                    log("[i]   zoom: the city was already fully out")
                    dev.zoomed_out = True
                    return
            # Owner 27 Oct 22:17 (Kiravik, Stalds, K, Rob all at once): the one-notch test did not show the view growing and
            # all four waited for the real mouse while the owner used the PC. The city maps were made fully out: when the
            # screen lines up with this instance's map or a culture map, the zoom is already right - carry on.
            if _at_map_zoom(dev, dev.screenshot()):
                log("[i]   zoom: the screen matches the city map - already fully out")
                dev.zoomed_out = True
                return
            # Owner 25 Oct: on testers' BlueStacks the Ctrl+wheel window message changes nothing and the bot said "fully
            # out". A real Ctrl + scroll down (what the owner does by hand) works there: try it a few times first.
            for k in range(3):
                if stop.is_set():
                    return
                b2 = dev.screenshot()
                if not real_wheel_zoom_out(dev, log, name, stop=stop):
                    break
                _nap(stop, 1.0, 1.3)
                s2 = _view_scale(b2, dev.screenshot())
                if s2 and s2 < 0.97:
                    log(f"[i]   zoom: the real Ctrl+scroll worked (try {k + 1})")
                    sc, use_real = s2, True
                    break
            else:                                        # owner: try every other way before mapping at this zoom
                log("[i]   zoom: neither Ctrl+wheel nor a real Ctrl+scroll changed the view - trying a two-finger pinch")
                dev.zoomed_out = False
                if zoom_out_city(dev, stop, log):
                    log("[i]   zoom: the pinch zoomed the city out")
                else:
                    log("[!]   zoom: no way of zooming out worked on this emulator (Ctrl+wheel, real Ctrl+scroll, pinch) - "
                        "mapping at this zoom; zoom the city out by hand once if the map comes out poor")
                return
        if not sc or sc >= 0.97:
            log(f"[i]   zoom: fully out after {i} more notch(es)")
            return
    dev.zoomed_out = True


MOVABLE_BUILDINGS = ("Market", "Barracks", "Prison", "Hospital", "Embassy", "Warehouse", "Stable", "Arsenal",
                     "Archer Camp", "Trap Factory", "Workshop", "War Hall", "Forge")   # owner 27 Oct: players move these


def building_pictures(dev, names, own=False):
    """Saved pictures of these buildings from every instance on this PC whose city has the SAME culture (owner 27 Oct:
    when the names can't be read, match the pictures already in the database). -> {name: [(img, dx, dy), ...]}"""
    cult = (city_culture(dev) or {}).get("culture")
    out = {}
    if not cult or not LEARN_DIR.exists():
        return out
    for d in LEARN_DIR.iterdir():
        try:
            if not d.is_dir() or (d == _map_dir(dev) and not own):
                continue
            if json.loads((d / "culture.json").read_text(encoding="utf-8")).get("culture") != cult:
                continue
        except Exception:
            continue
        for n in names:
            stem = re.sub(r"[^a-z]+", "_", n.lower()).strip("_")
            png, js = d / (stem + ".png"), d / (stem + ".json")
            if not png.exists():
                continue
            img = cv2.imread(str(png))
            if img is None:
                continue
            try:
                m = json.loads(js.read_text(encoding="utf-8"))
            except Exception:
                m = {}
            # Owner 28 Oct 02:04: Kiravik's pins were mapped wrong from pictures alone, and those wrong pictures then
            # 'confirmed' themselves and spread to the other instances. A picture counts only when its pin exists and the
            # building's menu NAME was checked there (named) or a task opened it there (worked).
            if not (m.get("named") or m.get("worked")):    # only pictures whose menu name was checked (pins not needed:
                continue                                   # Map city again wipes pins, the pictures stay - owner spec 28 Oct)
            out.setdefault(n, []).append((img, int(m.get("dx", img.shape[1] // 2)), int(m.get("dy", img.shape[0] // 2))))
    return out


def match_building_pictures(shot, pics, skip=()):
    """Find saved building pictures on this screen (same zoom as the maps: sizes 0.9-1.1 only). -> [(name, x, y, score)]
    tap points on screen, best per building, score >= 0.72."""
    hits = []
    area = shot[90:860, 0:470]
    for n, lst in pics.items():
        if n in skip:
            continue
        best = None
        for img, dx, dy in lst:
            for f in (1.0, 0.9, 1.1, 0.8, 0.7, 0.6):        # pictures learned at a closer zoom are bigger than the sweep's
                t = img if f == 1.0 else cv2.resize(img, None, fx=f, fy=f, interpolation=cv2.INTER_LINEAR)
                if t.shape[0] >= area.shape[0] or t.shape[1] >= area.shape[1]:
                    continue
                _, v, _, l = cv2.minMaxLoc(cv2.matchTemplate(area, t, cv2.TM_CCOEFF_NORMED))
                if v >= 0.72 and (best is None or v > best[3]):
                    best = (n, int(l[0] + dx * f), int(l[1] + 90 + dy * f), float(v))
        if best:
            hits.append(best)
    return hits


# --- City mapper (owner spec 28 Oct 02:52-03:06, claude/city_mapper_spec_28oct.md) -------------------------------------
#     Every instance starts with 0 map. ONE button: Map my city -> the bot moves round the whole city, builds THIS city's
#     own picture (live), the fixed buildings come from the culture pins (not visited, not counted), the movable ones are
#     pinned while moving (picture match -> tap -> menu name checked). Missing = hand pin or Map city again. Once mapped it
#     stays: the bot never re-maps or moves a pin by itself (looks change with upgrades / skins, positions do not).
#     Map city again deletes this instance's picture and ALL its pins. The building picture database is never deleted.
MYMAP_FILE = "mymap.json"                                  # city_learn/<serial>/mymap.json: the instance's mapping state


def real_city_paths(dev):
    d = _map_dir(dev)
    return d / "real_city.jpg", d / "real_city.json"


def mymap_info(dev):
    """{running, t, stop, stops, found, total, last, missing, complete, at} or {} (never mapped)."""
    try:
        return json.loads((_map_dir(dev) / MYMAP_FILE).read_text(encoding="utf-8"))
    except Exception:
        return {}


def mymap_save(dev, **kw):
    try:
        f = _map_dir(dev) / MYMAP_FILE
        f.parent.mkdir(parents=True, exist_ok=True)
        m = mymap_info(dev)
        m.update(kw, t=time.time())
        tmp = f.with_name("mymap.tmp")
        tmp.write_text(json.dumps(m), encoding="utf-8")
        os.replace(tmp, f)
    except Exception as _e:
        quiet_err("mymap_save", _e)


def city_mapped(dev):
    """True once Map my city finished on this instance (owner: before that the instance has 0 map)."""
    return bool(mymap_info(dev).get("complete"))


UNLOCK_MIN = 60                                             # Unlock = one run; locks again by itself if no run starts this long


def city_locked(dev):
    """Owner 30 Oct (Rob's hand pins were wiped by runs he never pressed): once a city is mapped it is LOCKED -
    Map my city / Map city again / Find missing refuse to run (from a button, Run now, a chat or anything else) until the
    owner presses Unlock on the City map card. Fix pins (moving pins by hand) is never locked."""
    m = mymap_info(dev)
    return bool(m.get("complete")) and time.time() > float(m.get("unlocked_until", 0) or 0)


def city_unlock(dev):
    mymap_save(dev, unlocked_until=time.time() + UNLOCK_MIN * 60)


def city_relock(dev):
    if mymap_info(dev).get("unlocked_until"):
        mymap_save(dev, unlocked_until=0)


def restore_city_map(dev, bk):
    """Put a city map back from its backup folder (wipe_city_map's copy): pins, picture, map state. Used when a Map my
    city run did not finish - the old map is never lost by a run that failed or was stopped."""
    d = _map_dir(dev)
    if not bk or not Path(bk).is_dir():
        return False
    try:
        for f in list(d.glob("*.json")):
            if f.stem not in ("culture", "hold"):
                m = None
                try:
                    m = json.loads(f.read_text(encoding="utf-8"))
                except Exception:
                    pass
                if f.stem in ("real_city", "mymap", "pins_override", "map_only", "retake_photo", "map", "map_prev") or f.stem.startswith("kf"):
                    f.unlink()
                elif isinstance(m, dict):                  # a pin from the failed run goes; the old one comes back below
                    m.pop("map", None)
                    m.pop("by", None)
                    f.write_text(json.dumps(m), encoding="utf-8")
        for name in ("real_city.jpg", "real_city.tmp.jpg"):
            try:
                (d / name).unlink()
            except Exception:
                pass
        for f in Path(bk).iterdir():
            if f.is_file() and f.stem not in ("culture", "hold"):
                shutil.copy2(f, d / f.name)
        _CITY_MAPS.pop(str(getattr(dev, "serial", "default")), None)
        return True
    except Exception as _e:
        quiet_err("restore_city_map", _e)
        return False


def mymap_running(dev):
    m = mymap_info(dev)
    return bool(m.get("running")) and time.time() - float(m.get("t", 0)) < 300   # a crashed run is not 'running' for ever


def wipe_city_map(dev, why=""):
    """Map city again / clean start: this instance's city picture and ALL its pins (hand pins too) are deleted. Copied to
    backups/city_maps/<serial>_<time>/ first. Kept: building pictures + their name checks (the database), culture.json
    (groups the database by culture), hold.json (which finger hold shows names)."""
    d = _map_dir(dev)
    if not d.exists():
        return
    bk = USER / "backups" / "city_maps" / (re.sub(r"[^\w.-]+", "_", str(dev.serial)) + "_" + time.strftime("%Y%m%d_%H%M%S"))
    try:
        files = [f for f in d.iterdir() if f.is_file()]
        if files:
            bk.mkdir(parents=True, exist_ok=True)
            for f in files:
                if f.suffix in (".json", ".jpg") or f.name == "map.png":
                    shutil.copy2(f, bk / f.name)
    except Exception as _e:
        quiet_err("wipe_city_map backup", _e)
    for f in list(d.glob("*.json")):
        stem = f.stem
        if stem in ("culture", "hold"):
            continue
        if stem in ("real_city", "mymap", "pins_override", "map_only", "retake_photo", "map", "map_prev") or stem.startswith("kf"):
            try:
                f.unlink()
            except Exception:
                pass
            continue
        try:                                               # a building: its pin goes, its picture + name check stay
            m = json.loads(f.read_text(encoding="utf-8"))
            if isinstance(m, dict) and ("map" in m or "by" in m):
                m.pop("map", None)
                m.pop("by", None)
                f.write_text(json.dumps(m), encoding="utf-8")
        except Exception:
            pass
    for name in ("real_city.jpg", "real_city.tmp.jpg", "map.png", "mymap.tmp"):
        try:
            (d / name).unlink()
        except Exception:
            pass
    for f in d.glob("kf_*.png"):                           # an own walked map (no culture matched) belongs to the old map
        try:
            f.unlink()
        except Exception:
            pass
    _CITY_MAPS.pop(str(getattr(dev, "serial", "default")), None)
    dev._wipe_backup = str(bk) if bk.is_dir() else ""
    return f"city map wiped{(' (' + why + ')') if why else ''} - backup {bk.name}"


class _SerialOnly:
    def __init__(self, serial):
        self.serial = serial


def migrate_city_maps_v2():
    """App start: a mapping run cut off by the restart must not show 'Mapping now'."""
    try:                                                   # app start: no mapping can be running - a run an app restart
        for d in (LEARN_DIR.iterdir() if LEARN_DIR.exists() else []):   # cut off must not show 'Mapping now' for 5 min
            f = d / MYMAP_FILE
            if d.is_dir() and f.exists():
                m = json.loads(f.read_text(encoding="utf-8"))
                if m.get("running"):
                    m["running"] = False
                    f.write_text(json.dumps(m), encoding="utf-8")
    except Exception as _e:
        quiet_err("mymap_reset_running", _e)
    # Owner 30 Oct: the one-time 'clean start' wipe of 28 Oct is gone. It wiped every city at an app start whenever the
    # marker file was missing - e.g. a new tester: no city_learn at the first start (no marker written), maps the city,
    # next app start = every map and hand pin deleted. The app never wipes a map by itself.


class RealCityPhoto:
    """This city's own picture: every at-rest screenshot of the sweep is pasted at its measured camera place (same pixel
    frame as the culture map and its pins: picture = map place - CITY_VIEW corner). Not visited yet = dark."""
    def __init__(self, dev, cmap):
        self.dev, self.cmap, self.done, self.img = dev, cmap, 0, None
        cult = city_culture(dev)
        cd = culture_dir(cult["culture"]) if cult else None
        if not cd:
            return
        try:
            W, H = json.loads((cd / "map.json").read_text(encoding="utf-8"))["size"]
        except Exception:
            return
        self.culture, self.W, self.H = cult["culture"], int(W), int(H)
        self.img = np.full((self.H, self.W, 3), 24, np.uint8)
        self.filled = np.zeros((self.H, self.W), bool)     # fix A 28 Oct: which pixels have a real screenshot (dark = not yet)
        self._saved = 0.0

    def paste(self, shot, loc=None):
        """Owner 28 Oct (fix A): every located, settled city screenshot is pasted (stops AND the drags on the way), only the
        PHOTO_VIEW part (no HUD strip). loc = the camera place when the caller already located the shot."""
        if self.img is None or shot is None:
            return False
        if find_detail_icon(shot):                          # a building ring is open: not a clean city view
            return False
        try:
            if lag_icon(shot):                             # owner 28 Oct: red lag wifi icons were pasted into Rob's picture
                return False
        except Exception:
            pass
        loc = loc or self.cmap.locate(shot)
        if not loc:
            return False
        x, y, _w, _h = CITY_VIEW
        px, py, w, h = PHOTO_VIEW
        X, Y = int(round(loc[0])) + (px - x), int(round(loc[1])) + (py - y)   # picture place of the crop's top-left
        crop = shot[py:py + h, px:px + w]
        x0, y0, x1, y1 = max(0, X), max(0, Y), min(self.W, X + w), min(self.H, Y + h)
        if x1 <= x0 or y1 <= y0:
            return False
        self.img[y0:y1, x0:x1] = crop[y0 - Y:y1 - Y, x0 - X:x1 - X]
        self.filled[y0:y1, x0:x1] = True
        self.done += 1
        if time.time() - self._saved >= 2.0:               # many pastes now: write the live picture at most every 2 s
            self.save()
        return True

    def view_rect(self, cx, cy):
        """Picture rectangle a camera at (cx, cy) photographs (clipped) -> (x0, y0, x1, y1) or None."""
        x, y, _w, _h = CITY_VIEW
        px, py, w, h = PHOTO_VIEW
        X, Y = int(round(cx)) + (px - x), int(round(cy)) + (py - y)
        x0, y0, x1, y1 = max(0, X), max(0, Y), min(self.W, X + w), min(self.H, Y + h)
        if (x1 - x0) * (y1 - y0) < 0.3 * w * h:            # mostly outside the picture
            return None
        return x0, y0, x1, y1

    def darkest(self, cams):
        """Of the camera places (keyframes = places the camera can really be), the one whose view is darkest.
        -> (dark share, map x, map y of the dark part's middle, cam) or None."""
        best = None
        x, y, _w, _h = CITY_VIEW
        for c in cams:
            r = self.view_rect(c[0], c[1])
            if not r:
                continue
            x0, y0, x1, y1 = r
            dark = ~self.filled[y0:y1, x0:x1]
            share = float(dark.mean())
            if best is None or share > best[0]:
                ys, xs = np.nonzero(dark)
                mx, my = (x0 + float(xs.mean()), y0 + float(ys.mean())) if len(xs) else ((x0 + x1) / 2, (y0 + y1) / 2)
                best = (share, mx + x, my + y, c)          # picture -> map place: + the CITY_VIEW corner
        return best

    def coverage(self, cams):
        """Share of the city (all keyframe views together) that has a real screenshot."""
        m = np.zeros_like(self.filled)
        for c in cams:
            r = self.view_rect(c[0], c[1])
            if r:
                m[r[1]:r[3], r[0]:r[2]] = True
        tot = int(m.sum())
        return float((self.filled & m).sum()) / tot if tot else 0.0

    def save(self):
        if self.img is None or not self.done:
            return
        self._saved = time.time()
        jp, mp = real_city_paths(self.dev)
        img = self.img
        base = getattr(self, "base", None)
        if base is not None and base.shape == img.shape:   # Find missing: the old picture stays, only its dark parts fill
            img = base.copy()
            add = self.filled & ~self.base_ok
            img[add] = self.img[add]
        try:
            jp.parent.mkdir(parents=True, exist_ok=True)
            tmp = jp.with_name("real_city.tmp.jpg")
            cv2.imwrite(str(tmp), img, [cv2.IMWRITE_JPEG_QUALITY, 88])
            os.replace(tmp, jp)
            mp.write_text(json.dumps({"culture": self.culture, "at": time.strftime("%Y-%m-%d %H:%M")}), encoding="utf-8")
        except Exception as _e:
            quiet_err("real_city_photo", _e)


def _city_seen(dev, shot, loc):
    """A settled screenshot was found on the city map: remember where the camera was (fix C uses it to drive back) and,
    while Map my city runs, paste it into the city picture (fix A)."""
    if not loc:
        return
    dev._last_cam = (float(loc[0]), float(loc[1]), time.time())
    dev._zoom_ok_at = time.time()                          # the screen located on the map = the city is at the map's zoom
    photo = getattr(dev, "_photo", None)
    if photo is not None:
        try:
            photo.paste(shot, loc)
        except Exception as _e:
            quiet_err("city_seen_paste", _e)


def relocate_view(dev, cfg, log, stop, cmap, nav):
    """Owner 28 Oct (fix C): the screen is not found on the city map - e.g. the camera parked on the farmland / forest
    edge that the culture map does not cover. Instead of giving up: close what is open, then drag back toward the city
    middle (from the last place the camera was seen; without one, try each direction and come back) and look again.
    -> (cx, cy, points) or None."""
    shot = dev.screenshot()
    if find_detail_icon(shot):
        close_ring(dev, stop, (270, 490))
        shot = nav._settled()
    r = cmap.locate(shot)
    if r:
        _city_seen(dev, shot, r)
        return r
    leave_to_city(dev, cfg, stop, log)                     # a window / pop-up in the way
    shot = nav._settled()
    r = cmap.locate(shot)
    if r:
        _city_seen(dev, shot, r)
        log(f"[i]   nav: relocate=hit after closing windows cx={round(r[0])} cy={round(r[1])}")
        return r
    # Owner 28 Oct 13:00 (Rob: a 'Comeback Celebration' ad with no X sat on the city 20 min while the bot dragged under
    # it): ads close with Back - try Back, then a tap outside, BEFORE any drag; what worked is learned for that ad.
    for how in ("back", "outside"):
        if nav.halted():
            return None
        purchase_guard(dev, shot, log)
        ph = _pop_hash(shot)
        _poplib_seen(ph, shot, log)
        if how == "back":
            dev.back()
        else:
            dev.tap(8, 480)
        _nap(stop, 0.8, 1.0)
        nxt = nav._settled()
        quit_seen = cancel_quit_dialog(dev, nxt, log)      # Back on the bare city asks to quit: Cancel, the city is there
        if quit_seen:
            nxt = nav._settled()
        r = cmap.locate(nxt)
        if r:
            if not quit_seen:                              # only a real pop-up is learned (never the bare city)
                _poplib_learn((ph, how, (0, 0) if how == "back" else (8, 480)), nxt, log)
            _city_seen(dev, nxt, r)
            log(f"[i]   nav: relocate=hit after {'Back' if how == 'back' else 'a tap outside'} (a pop-up was in the way)")
            return r
        shot = nxt
    cams = [(k[0], k[1]) for k in (cmap.kf or [])]
    if not cams:
        return None
    mx = sum(c[0] for c in cams) / len(cams)               # middle of the city (camera places)
    my = sum(c[1] for c in cams) / len(cams)
    sp = culture_pin(dev, "Shrine")                        # owner 28 Oct 13:55: the Shrine is the city's centre - home base
    if sp:
        x_, y_, w_, h_ = CITY_VIEW
        mx, my = sp[0] - (x_ + w_ / 2), sp[1] - (y_ + h_ / 2)   # the camera place that shows the Shrine in the middle
    last = getattr(dev, "_last_cam", None)
    if last and time.time() - last[2] < 900:
        vx, vy = mx - last[0], my - last[1]
        ln = (vx * vx + vy * vy) ** 0.5 or 1.0
        log(f"[i]   nav: relocate - screen not on the map, last seen at {round(last[0])},{round(last[1])}; dragging toward "
            + ("the Shrine (city centre)" if sp else "the city middle"))
        for k in range(3):
            if nav.halted():
                return None
            fx, fy = vx / ln * 300, vy / ln * 420           # camera move toward the middle (finger the other way)
            _dx, _dy, after = nav._drag(270 + fx / 2, 440 + fy / 2, 270 - fx / 2, 440 - fy / 2)
            r = cmap.locate(after)
            if r:
                _city_seen(dev, after, r)
                log(f"[i]   nav: relocate=hit after {k + 1} drag(s) cx={round(r[0])} cy={round(r[1])}")
                return r
    else:
        log("[i]   nav: relocate - screen not on the map and no recent camera place; trying each direction")
        for ux, uy in ((0, -1), (0, 1), (-1, 0), (1, 0)):
            if nav.halted():
                return None
            fx, fy = ux * 300, uy * 420
            dx, dy, after = nav._drag(270 + fx / 2, 440 + fy / 2, 270 - fx / 2, 440 - fy / 2)
            r = cmap.locate(after)
            if r:
                _city_seen(dev, after, r)
                log(f"[i]   nav: relocate=hit dragging {ux},{uy} cx={round(r[0])} cy={round(r[1])}")
                return r
            if abs(dx) + abs(dy) > 30:                      # it moved: come back before the next direction
                nav._drag(270 - fx / 2, 440 - fy / 2, 270 + fx / 2, 440 + fy / 2)
    log("[i]   nav: relocate=miss shot=debug/duty_nav_relocate.png")
    rd_snap(dev.screenshot(), "nav_relocate")
    return None


def _map_tap_note(dev, log, stop_no, bname, tx, ty, before, after, cmap):
    """Owner 28 Oct (fix B): a picture match was tapped but no building menu opened. Log it and save before|after with
    the tap marked (debug/map_notap/), so the real cause can be found. At most 30 pictures per mapping run."""
    n = getattr(dev, "_notap_n", 0) + 1
    dev._notap_n = n
    try:
        diff = float(np.mean(cv2.absdiff(before[190:780, 80:440], after[190:780, 80:440]))) if before is not None and after is not None else -1
    except Exception:
        diff = -1
    if n > 30:
        log(f"[!]   stop {stop_no}: tapped {bname} at {tx},{ty} - no menu opened (screen change {diff:.1f}; picture limit reached)")
        return
    on_city = "?"
    try:
        on_city = "city view" if cmap.locate(after) else "NOT the city view (window / pop-up?)"
    except Exception:
        pass
    name = "?"
    try:
        d = USER / "debug" / "map_notap"
        d.mkdir(parents=True, exist_ok=True)
        a, b = before.copy(), after.copy()
        for im in (a, b):
            cv2.circle(im, (int(tx), int(ty)), 14, (0, 0, 255), 2)
            cv2.line(im, (int(tx) - 20, int(ty)), (int(tx) + 20, int(ty)), (0, 0, 255), 1)
            cv2.line(im, (int(tx), int(ty) - 20), (int(tx), int(ty) + 20), (0, 0, 255), 1)
        if a.shape == b.shape:
            img = np.hstack([a, b])
        else:
            img = b
        ser = re.sub(r"[^A-Za-z0-9]+", "_", str(getattr(dev, "serial", "dev")))
        name = f"{ser}_{time.strftime('%H%M%S')}_{re.sub(r'[^A-Za-z]+', '_', bname)}_{int(tx)}_{int(ty)}.png"
        cv2.imwrite(str(d / name), img)
    except Exception as _e:
        quiet_err("map_tap_note", _e)
    log(f"[!]   stop {stop_no}: tapped {bname} at {tx},{ty} - no menu opened (screen change {diff:.1f}, after the tap: {on_city}) "
        f"shot=debug/map_notap/{name} (left before, right after)")


def _canvas_mask(img):
    """The city picture's never-photographed parts (the dark canvas, value 24): big flat blobs only."""
    m = (np.abs(img.astype(np.int16) - 24) <= 10).all(axis=2).astype(np.uint8)
    k = np.ones((9, 9), np.uint8)
    m = cv2.morphologyEx(m, cv2.MORPH_OPEN, k)            # a real dark pixel is never a 9x9 flat block
    return cv2.dilate(m, np.ones((5, 5), np.uint8)) > 0    # + the jpg fringe along the edges


def picture_from_pin(dev, bname, img=None):
    """Owner 28 Oct 11:40: a pin the user placed by hand is a checked place - cut the building out of this city's own
    picture there and save it as a CHECKED picture ('named'), so every instance of the same culture can match it
    (K's hand pins -> Rob). Skipped when the spot was never photographed. -> True when saved."""
    try:
        p = _learn_path(dev, bname)
        js = p.with_suffix(".json")
        meta = json.loads(js.read_text(encoding="utf-8"))
        pin = meta.get("map")
        if not pin or meta.get("by") != "user":
            return False
        if img is None:
            img = cv2.imread(str(real_city_paths(dev)[0]))
        if img is None:
            return False
        px, py = int(round(pin[0] - CITY_VIEW[0])), int(round(pin[1] - CITY_VIEW[1]))   # nav frame -> picture
        x0, y0 = px - 70, py - 45
        if x0 < 0 or y0 < 0 or x0 + 140 > img.shape[1] or y0 + 130 > img.shape[0]:
            return False
        crop = img[y0:y0 + 130, x0:x0 + 140]
        if _canvas_mask(crop).mean() > 0.1:                # the spot is (partly) dark: no picture
            return False
        if p.exists():
            p.replace(p.with_name(p.stem + "_prev.png"))
        cv2.imwrite(str(p), crop)
        now = time.strftime("%Y-%m-%d %H:%M")
        meta.update({"dx": 70, "dy": 45, "named": now, "pic_from_pin": list(pin)})
        js.write_text(json.dumps(meta), encoding="utf-8")
        return True
    except Exception as _e:
        quiet_err("picture_from_pin", _e)
        return False


def fill_city_gaps(dev):
    """Owner 28 Oct 11:40: once EVERY building is pinned, the picture's dark parts that hold no building (grass, rocks,
    roads) are filled from the culture's saved picture. Never near a pin (fixed or movable): buildings are never painted
    from the database. -> number of pixels filled."""
    cult = city_culture(dev)
    cd = culture_dir(cult["culture"]) if cult else None
    jp, mp = real_city_paths(dev)
    if not cd or not jp.exists() or not (cd / "map.jpg").exists():
        return 0
    if any(not _pin_of(dev, b) for b in MOVABLE_BUILDINGS):
        return 0                                           # a missing building could sit in the dark part
    img = cv2.imread(str(jp))
    ref = cv2.imread(str(cd / "map.jpg"))
    if img is None or ref is None:
        return 0
    mask = _canvas_mask(img)
    if not mask.any():
        return 0
    keep = np.zeros(mask.shape, np.uint8)
    pins = list({**culture_pins(cult["culture"]), **pins_override(dev)}.values())
    pins += [[v[0] - CITY_VIEW[0], v[1] - CITY_VIEW[1]] for v in (_pin_of(dev, b) for b in MOVABLE_BUILDINGS) if v]
    for x, y in pins:
        cv2.circle(keep, (int(x), int(y)), 110, 1, -1)    # a building and its plot stay dark if never photographed
    mask &= keep == 0
    mask[:70] = False                                      # the culture picture's own top edge still has HUD bits
    n = int(mask.sum())
    if not n:
        return 0
    ref = cv2.resize(ref, (img.shape[1], img.shape[0]), interpolation=cv2.INTER_LINEAR)
    img[mask] = ref[mask]
    tmp = jp.with_name("real_city.tmp.jpg")
    cv2.imwrite(str(tmp), img, [cv2.IMWRITE_JPEG_QUALITY, 88])
    os.replace(tmp, jp)
    try:
        m = json.loads(mp.read_text(encoding="utf-8"))
    except Exception:
        m = {}
    m["gaps_filled"] = time.strftime("%Y-%m-%d %H:%M")
    mp.write_text(json.dumps(m), encoding="utf-8")
    return n


def city_picture_upkeep(dev):
    """Called when the City map card loads (mapped, not mapping): new hand pins -> checked pictures; all pinned ->
    fill the dark gaps. Cheap when nothing changed."""
    try:
        img = None
        for b in MOVABLE_BUILDINGS:
            try:
                meta = json.loads(_learn_path(dev, b).with_suffix(".json").read_text(encoding="utf-8"))
            except Exception:
                continue
            if meta.get("by") == "user" and meta.get("map") and meta.get("pic_from_pin") != meta.get("map"):
                if img is None:
                    img = cv2.imread(str(real_city_paths(dev)[0]))
                picture_from_pin(dev, b, img)
        jp, mp = real_city_paths(dev)
        if jp.exists():
            try:
                m = json.loads(mp.read_text(encoding="utf-8"))
            except Exception:
                m = {}
            sig = [round(jp.stat().st_mtime)] + sorted(str(_pin_of(dev, b)) for b in MOVABLE_BUILDINGS)
            if m.get("gap_sig") != sig:
                fill_city_gaps(dev)
                try:
                    m = json.loads(mp.read_text(encoding="utf-8"))
                except Exception:
                    m = {}
                m["gap_sig"] = [round(jp.stat().st_mtime)] + sig[1:]
                mp.write_text(json.dumps(m), encoding="utf-8")
    except Exception as _e:
        quiet_err("city_picture_upkeep", _e)


def run_map_missing(dev, cfg, log, stop):
    """Owner 28 Oct 10:47: once the city is mapped and some movable buildings are missing, look for ONLY those again -
    nothing is wiped (picture, pins and hand pins stay). Before the first mapping there is nothing to 'find again'."""
    if not city_mapped(dev):
        log("[i] Find missing buildings: this city is not mapped yet - press Map my city first")
        return
    if city_locked(dev):
        log("[!] Find missing buildings: this city's map is locked (press Unlock on the City map card first) - skipped")
        return
    city_relock(dev)
    miss = [b for b in MOVABLE_BUILDINGS if not _pin_of(dev, b)]
    if not miss:
        log("[+] Find missing buildings: every movable building is pinned already")
        mymap_save(dev, missing=[])
        return
    log(f"[*] Find missing buildings: looking for {', '.join(miss)} - nothing is wiped")
    mymap_save(dev, running=True, stop=0, stops=0, found=len(MOVABLE_BUILDINGS) - len(miss), total=len(MOVABLE_BUILDINGS), last="")
    try:
        leave_to_city(dev, cfg, stop, log)
        zoom_out_full(dev, cfg, stop, log)
        run_map_movable(dev, cfg, log, stop, only=miss)
    finally:
        left = [b for b in MOVABLE_BUILDINGS if not _pin_of(dev, b)]
        mymap_save(dev, running=False, found=len(MOVABLE_BUILDINGS) - len(left), total=len(MOVABLE_BUILDINGS), missing=left)


def _pin_of(dev, bname):
    try:
        return json.loads(_learn_path(dev, bname).with_suffix(".json").read_text(encoding="utf-8")).get("map")
    except Exception:
        return None


def run_map_movable(dev, cfg, log, stop, only=None):
    """Map my city, the sweep: visit every stop of the city map; at each stop paste the screen into this city's picture,
    match the saved building pictures (every match is tapped and its menu NAME checked before it is pinned) and, for a
    movable building with no usable picture, read the names with a finger hold. Pins appear on the picture as found.
    -> list of the movable buildings pinned."""
    cmap = city_map(dev)
    if cmap is None or not cmap.kf:
        log("[!] Map my city: no city map to move on")
        return []
    x, y, w, h = CITY_VIEW
    stops = []                                             # camera places a good half view apart, row by row (serpentine)
    for kx, ky, _, _ in sorted(cmap.kf, key=lambda k: (round(k[1] / 300), k[0])):
        if not any(abs(kx - sx) < w * 0.75 and abs(ky - sy) < h * 0.6 for sx, sy in stops):
            stops.append((kx, ky))
    rows = {}
    for sx, sy in stops:
        rows.setdefault(round(sy / 300), []).append((sx, sy))
    stops = [p for i, r in enumerate(sorted(rows)) for p in (sorted(rows[r]) if i % 2 == 0 else sorted(rows[r], reverse=True))]
    want = list(only) if only else list(MOVABLE_BUILDINGS)
    base = len(MOVABLE_BUILDINGS) - len(want)              # Find missing: the buildings pinned before count as found
    found, tried, seen_all, later = {}, set(), set(), {}
    photo = RealCityPhoto(dev, cmap) if city_culture(dev) else None
    if photo is not None and photo.img is not None and only:   # owner 28 Oct 14:05: Find missing also fills the black parts -
        try:                                                   # it builds on the existing picture instead of starting dark
            old = cv2.imread(str(real_city_paths(dev)[0]))
            if old is not None and old.shape != photo.img.shape:
                old = cv2.resize(old, (photo.img.shape[1], photo.img.shape[0]), interpolation=cv2.INTER_LINEAR)
            if old is not None:
                photo.img = old.copy()
                photo.filled = ~_canvas_mask(old)
                photo.base, photo.base_ok = old, photo.filled.copy()   # owner 30 Oct: Find missing only ADDS to the picture
                photo.done = 1
        except Exception as _e:
            quiet_err("photo_reuse", _e)
    if photo is not None and photo.img is None:
        photo = None
    dev._photo = photo                                     # fix A: every located settled screenshot on the way is pasted too
    dev._notap_n = 0
    pics = building_pictures(dev, want, own=True)
    last = [""]

    def missing():
        return [b for b in want if b not in found]

    # Names (finger hold): remember per emulator which way of holding shows them. 'none' = pictures only (retried weekly).
    hold_f = _map_dir(dev) / "hold.json"
    names_ok, proven = True, set()
    try:
        hj = json.loads(hold_f.read_text(encoding="utf-8"))
        if hj.get("mode") == "none" and time.time() - hj.get("t", 0) < 7 * 86400:
            names_ok = False
        elif hj.get("mode") in ("motion", "window", "swipe"):
            dev._hold_mode = hj["mode"]
            proven.add(hj["mode"])
    except Exception:
        pass

    def save_hold(mode):
        try:
            hold_f.parent.mkdir(parents=True, exist_ok=True)
            hold_f.write_text(json.dumps({"mode": mode, "t": time.time()}), encoding="utf-8")
        except Exception as _e:
            quiet_err("save_hold", _e)

    def progress(stop_no, checking=None):
        """'3 / 13 found - Market' on the instance's Now line, the live panel and the City map card."""
        text = (f"{'Finding missing buildings' if only else 'Mapping your city'}: stop {stop_no} of {len(stops)} · {base + len(found)} / {base + len(want)} found"
                + (f" - {last[0]}" if last[0] else ""))
        log("@act " + json.dumps({"k": "step", "text": text}))
        log("@act " + json.dumps({"k": "map", "stop": stop_no, "stops": len(stops), "found": list(found),
                                  "checking": checking, "seen": sorted(b for b in seen_all if b in want and b not in found),
                                  "missing": missing(), "kept": 0, "t0": round(t0)}))
        mymap_save(dev, running=True, stop=stop_no, stops=len(stops), found=base + len(found), total=base + len(want), last=last[0])

    def pinned(b, place):
        found[b] = place
        last[0] = b
        log(f"[+]   {b}: pinned ({base + len(found)} / {base + len(want)})")

    log(f"[*] Map my city: {len(stops)} stops, looking for {len(want)} movable buildings - pictures first, names only when needed")
    log(f"[i]   finger hold: {dev.hold_mode() if names_ok else 'off (this emulator shows no names - pictures only)'}; "
        "saved pictures of the same culture: " + (", ".join(f"{n} x{len(v)}" for n, v in pics.items()) if pics else "none"))
    state = {"empty": 0}
    pic_hit = {}                                           # building -> picture score of its match on the current stop
    t0 = time.time()
    skipped = []                                           # stops whose names were not read in the first pass

    def pictures_at(i, nav, rest):
        """Saved pictures on the screen at rest -> labels to check by tap (never pinned from a picture alone)."""
        labels = []
        for n, px, py, sc in sorted(match_building_pictures(rest, pics, skip=tuple(found)) if pics else [], key=lambda hh: -hh[3]):
            if n not in found and sc >= 0.70:
                labels.append((n, round(nav.cx + px), round(nav.cy + py) + 30))
                pic_hit[n] = sc
                log(f"[i]   stop {i + 1}: {n} picture matched ({sc:.2f}) at {px},{py}"
                    + (" - pinning it, then tapping to confirm" if sc >= PIN_FIRST_SCORE else " - checking its name"))
        return labels

    def names_at(i, nav, labels):
        """Hold a finger so the game shows the names, read them, tap the movable ones on this screen."""
        nonlocal names_ok
        try:
            more, _held_img, _ = look_with_names(dev, stop, nav, shots=1)
            labels = labels + [l for l in more if BUILDING_ALIASES.get(l[0], l[0]) not in {n for n, _, _ in labels}]
        except InstanceStopped:
            raise
        except Exception as e:
            log(f"[i]   stop {i + 1}: names not read ({e})")
            return
        got_names = sorted({BUILDING_ALIASES.get(n, n) for n, _, _ in more}) if more else []
        if got_names:
            state["empty"] = 0
            proven.add(dev.hold_mode())
            save_hold(dev.hold_mode())
        elif dev.hold_mode() not in proven:
            state["empty"] += 1
        if state["empty"] >= 3:
            old = dev.hold_mode()
            if old == "swipe":
                names_ok = False
                save_hold("none")
                log("[!]   no names shown with any finger hold (motion, window, swipe) - this emulator maps by pictures only")
            else:
                log(f"[i]   no names on 3 stops with the '{old}' finger hold - trying '{dev.next_hold_mode() or 'swipe'}'")
            state["empty"] = 0
        names = sorted({BUILDING_ALIASES.get(n, n) for n, _, _ in labels})
        seen_all.update(names)
        log(f"[i]   stop {i + 1}/{len(stops)}: names {', '.join(names) if names else '(none read)'}")
        tap_labels(i, nav, labels)

    def tap_labels(i, nav, labels):
        """Tap each movable building on THIS screen, read the menu that opens and pin whatever movable building it names
        (at most 3 spots per building, then the next stop)."""
        todo = []
        for n, mx, my in labels:
            nb = BUILDING_ALIASES.get(n, n)
            key = (round(mx / 80), round(my / 80))
            if nb in want and nb not in found and key not in tried:
                tried.add(key)
                todo.append((nb, mx, my))
        for nb, mx, my in todo:
            if stop.is_set():
                break
            sc = pic_hit.pop(nb, 0.0)
            pre = False                                    # owner 28 Oct: strong picture match -> pin FIRST, then tap
            if sc >= PIN_FIRST_SCORE and nb not in found and pin_from_picture(dev, nb, mx, my - 30, sc):
                pinned(nb, [mx, my - 30])
                log(f"[+]   {nb}: pinned from its picture ({sc:.2f}) - tapping to confirm the name")
                progress(i + 1)
                pre = True
            ok_name = False
            progress(i + 1, nb)
            # Owner 28 Oct (fix B findings): 1) a ring makes the camera glide to its building, so the closing tap can land
            # on ANOTHER building (Kiravik: the Auction House opened, the next taps hit its window); 2) taps aimed a bit
            # left of the building hit the ground (Stalds). So: before EVERY tap check the city is on screen (else back to
            # it), measure the camera again, aim from the building's MAP place, and try a few spots around it.
            for ox, oy in [(0, 0), (0, 35), (0, -35), (40, 15), (-40, 15)]:
                if stop.is_set():
                    break
                before = nav._settled()
                loc = cmap.locate(before)
                if not loc:
                    leave_to_city(dev, cfg, stop, log)
                    before = nav._settled()
                    loc = cmap.locate(before)
                    if not loc:
                        log(f"[i]   stop {i + 1}: the city view is not found before tapping {nb} - next")
                        break
                nav.cx, nav.cy = loc[0], loc[1]
                tx, ty = int(mx - nav.cx + ox), int(my - 30 - nav.cy + oy)
                if not (70 <= tx <= 420 and 160 <= ty <= 800):
                    continue
                dev.tap(tx, ty)
                _nap(stop, 1.2, 1.5)
                shot = dev.screenshot()
                if not find_detail_icon(shot):
                    _map_tap_note(dev, log, i + 1, nb, tx, ty, before, shot, cmap)   # fix B: never silent
                    continue
                rn = (ring_building_name(shot) or ("",))[0]
                got = match_building(rn.split(",")[0]) if rn else None
                close_ring(dev, stop, (tx, ty + 60))
                _nap(stop, 0.6, 0.8)
                if pre and got == nb:                      # the picture pin is confirmed by the menu name
                    learn_building(dev, before, got, tx, ty)   # 'named' picture for the database (the pin stays as it is)
                    try:
                        js = _learn_path(dev, nb).with_suffix(".json")
                        m = json.loads(js.read_text(encoding="utf-8"))
                        m["by"] = "bot"                    # confirmed: an ordinary bot pin now
                        js.write_text(json.dumps(m), encoding="utf-8")
                    except Exception as _e:
                        quiet_err("pin_confirm", _e)
                    log(f"[+]   {nb}: name confirmed by its menu")
                    ok_name = True
                    break
                if got in want and got not in found:
                    learn_building(dev, before, got, tx, ty)   # picture + pin of this instance (menu name checked)
                    pinned(got, [round(nav.cx + tx), round(nav.cy + ty)])
                    progress(i + 1)
                    if got == nb:
                        break
                else:
                    log(f"[i]   the menu at {tx},{ty} is '{rn or '?'}'" + (" (already pinned)" if got in found else "") + f" - looking for {nb}")
                    if got in found and got == nb:
                        break
            if pre and not ok_name and not stop.is_set():
                log(f"[i]   {nb}: name not confirmed by a tap - the picture pin stays (tell me if it is wrong)")
            if nb not in found:
                later.setdefault(nb, []).append((mx, my))
            leave_to_city(dev, cfg, stop, log)

    last_edge = [False]

    def visit(i):
        duty_progress()
        sx, sy = stops[i]
        nav = CityNav(dev, stop, log)
        last_edge[0] = False
        if goto_on_map(dev, cfg, log, stop, nav, cmap, sx + x + w / 2, sy + y + h / 2, tol=120) is None:
            last_edge[0] = bool(getattr(nav, "_edge", False))
            log(f"[i]   stop {i + 1}: could not get there - next")
            leave_to_city(dev, cfg, stop, log)
            return None, None
        rest = nav._settled()
        loc = cmap.locate(rest)
        if loc:
            nav.cx, nav.cy = loc[0], loc[1]
            _city_seen(dev, rest, loc)                     # pasted into the picture here (fix A)
        return nav, rest

    # Owner 28 Oct 13:17 (said many times): PICTURES ONLY in the sweep - at every stop the saved pictures are matched and
    # each building's best match is pinned at once (shown live). No taps, no name reading. After the sweep the bot goes
    # to each pin, opens the building and checks its name. Missing ones -> Find missing / Fix pins.
    best = {}                                              # building -> (score, map x, map y) of its best match so far
    # Owner 28 Oct 13:45 (Rob lost 7 min at the top edge): a stop the map cannot scroll to is remembered for this city
    # (edge_stops.json) and skipped next time; after one such stop, the rest of that row is skipped at once.
    edge_f = _map_dir(dev) / "edge_stops.json"
    try:
        edge_known = [tuple(p) for p in json.loads(edge_f.read_text(encoding="utf-8"))]
    except Exception:
        edge_known = []
    edge_rows = set()
    for i in range(len(stops)):
        if stop.is_set():
            break
        sxy = stops[i]
        if any(abs(sxy[0] - ex) < 80 and abs(sxy[1] - ey) < 80 for ex, ey in edge_known):
            log(f"[i]   stop {i + 1}: skipped - the map could not scroll there before (city edge)")
            continue
        if round(sxy[1] / 300) in edge_rows:
            log(f"[i]   stop {i + 1}: skipped - same edge row as a stop the map could not reach")
            continue
        if time.time() - t0 > 11 * 60:                     # owner 28 Oct: 55 min was far too long - the sweep ends at ~11 min
            log(f"[i]   sweep time limit - {len(stops) - i} stop(s) left; checking the pins now (missing -> Find missing)")
            break
        progress(i + 1)
        nav, rest = visit(i)
        if nav is None and not last_edge[0] and not stop.is_set():   # owner 28 Oct: a pop-up came - pause, clear it, resume here
            log(f"[i]   stop {i + 1}: the screen did not match the city - clearing it and trying this stop again")
            leave_to_city(dev, cfg, stop, log)
            clear_to_bare_city(dev, cfg, log, stop)
            nav, rest = visit(i)
        elif nav is not None and rest is not None and cmap.locate(rest) is None and not stop.is_set():
            clear_to_bare_city(dev, cfg, log, stop)       # arrived, but something covers the view (a pop-up) - clear, look again
            nav, rest = visit(i)
        if nav is None and last_edge[0]:
            edge_rows.add(round(sxy[1] / 300))
            edge_known.append(tuple(sxy))
            try:
                edge_f.write_text(json.dumps([list(p) for p in edge_known]), encoding="utf-8")
            except Exception as _e:
                quiet_err("edge_save", _e)
        if nav is None or not pics:
            continue
        for n, px, py, sc in match_building_pictures(rest, pics):
            if n not in want or sc < PIN_FIRST_SCORE or (n in best and sc <= best[n][0]):
                continue
            mx, my = round(nav.cx + px), round(nav.cy + py)
            if n in found and _pin_of(dev, n) and json.loads(_learn_path(dev, n).with_suffix(".json").read_text(encoding="utf-8")).get("by") != "picture":
                continue                                   # a pin set another way (hand / checked) is never moved
            try:                                           # a better match of the same building: its picture pin follows it
                js = _learn_path(dev, n).with_suffix(".json")
                meta = json.loads(js.read_text(encoding="utf-8")) if js.exists() else {"dx": 0, "dy": 0}
                if meta.get("by") == "picture":
                    meta.pop("map", None)
                    js.write_text(json.dumps(meta), encoding="utf-8")
            except Exception as _e:
                quiet_err("picture_pin_move", _e)
            if pin_from_picture(dev, n, mx, my, sc):
                best[n] = (sc, mx, my)
                was = n in found
                found[n] = [mx, my]
                last[0] = n
                log(f"[+]   stop {i + 1}: {n} {'pin moved to a better' if was else 'pinned from its'} picture match ({sc:.2f})"
                    f" - {base + len(found)} / {base + len(want)}")
                progress(i + 1)
    # Check: go to each picture pin, open the building, read its name. Confirmed -> an ordinary checked pin; not
    # confirmed -> the pin stays (the owner tells which are wrong) and is listed.
    unconfirmed = []
    for k, nb in enumerate([b for b in want if b in found]):
        if stop.is_set():
            break
        if time.time() - t0 > 17 * 60:                     # the whole run stays under ~20 min with the photo moves
            log("[i]   time limit - the remaining pins stay unchecked (tasks check them when they open the building)")
            break
        duty_progress()
        log("@act " + json.dumps({"k": "step", "text": f"Checking the pins: {k + 1} of {len(found)} - {nb}"}))
        try:
            ok = find_on_map(dev, cfg, log, stop, nb, None, {"map": found[nb], "dx": 0, "dy": 0}, _learn_path(dev, nb))
        except InstanceStopped:
            raise
        except Exception as e:
            log(f"[i]   {nb}: {e}")
            ok = None
        if ok:
            try:
                js = _learn_path(dev, nb).with_suffix(".json")
                m2 = json.loads(js.read_text(encoding="utf-8"))
                m2["by"] = "bot"
                m2["named"] = time.strftime("%Y-%m-%d %H:%M")
                js.write_text(json.dumps(m2), encoding="utf-8")
            except Exception as _e:
                quiet_err("pin_confirm", _e)
            log(f"[+]   {nb}: name confirmed at its pin")
        else:
            unconfirmed.append(nb)
            log(f"[i]   {nb}: name not confirmed at its pin - the pin stays (tell me if it is wrong)")
        leave_to_city(dev, cfg, stop, log)
    if unconfirmed:
        log(f"[i]   pins not confirmed by name: {', '.join(unconfirmed)}")
    # Fix A (owner 28 Oct): the picture's dark parts (failed stops, gaps) - drive there for a photo only (no taps), at most
    # 6 extra moves, each place once.
    if photo is not None and not stop.is_set():
        cams = [(k[0], k[1]) for k in cmap.kf]
        log(f"[i]   picture: {round(photo.coverage(cams) * 100)}% of the city covered after the sweep")
        t_photo = time.time()
        for k in range(6):
            if stop.is_set():
                break
            if time.time() - t_photo > 240:                # Rob 28 Oct: stuck drags made each photo move 1-2 min - 4 min at most
                log("[i]   picture: 4 min of photo moves - stopping here")
                break
            mymap_save(dev, running=True)                  # keep 'mapping now' fresh (the card hid the map after 5 min of photo moves)
            best = photo.darkest(cams)
            if not best or best[0] < 0.2:
                break
            share, tx, ty, cam = best
            cams.remove(cam)
            duty_progress()
            log(f"[*]   picture: {round(share * 100)}% dark around map {round(tx)},{round(ty)} - going there for a photo ({k + 1}/6)")
            nav = CityNav(dev, stop, log)
            if goto_on_map(dev, cfg, log, stop, nav, cmap, tx, ty, tol=120) is None:
                leave_to_city(dev, cfg, stop, log)
                continue
            rest = nav._settled()
            _city_seen(dev, rest, cmap.locate(rest))
        log(f"[i]   picture: {round(photo.coverage([(k[0], k[1]) for k in cmap.kf]) * 100)}% of the city covered")
        photo.save()
    dev._photo = None
    miss = missing()
    log(f"[*] Map my city: {len(found)} of {len(want)} movable buildings pinned in {round((time.time() - t0) / 60, 1)} min"
        + (f"; missing: {', '.join(miss)} - place them in Fix pins" if miss else " - all found"))
    mymap_save(dev, found=base + len(found), total=base + len(want), last=last[0], missing=miss)
    return list(found)


def run_test_adb_zoom(dev, cfg, log, stop):
    """Developer test (owner 27 Oct): can the city be zoomed with ADB alone (no window message, no real mouse)? Tries a
    few Android scroll / key ways, each OUT then back IN, and logs how much the view changed (scale < 1 = zoomed out)."""
    leave_to_city(dev, cfg, stop, log)
    cx, cy = int(270 * dev.sx), int(440 * dev.sy)
    ways = [
        ("mouse scroll", ["input", "mouse", "scroll", str(cx), str(cy), "--axis", "VSCROLL,-3"], ["input", "mouse", "scroll", str(cx), str(cy), "--axis", "VSCROLL,3"]),
        ("scroll", ["input", "scroll", str(cx), str(cy), "--axis", "VSCROLL,-3"], ["input", "scroll", str(cx), str(cy), "--axis", "VSCROLL,3"]),
        ("trackball roll", ["input", "trackball", "roll", "0", "3"], ["input", "trackball", "roll", "0", "-3"]),
        ("ctrl+minus keys", ["input", "keycombination", "113", "69"], ["input", "keycombination", "113", "70"]),
        ("zoom keys", ["input", "keyevent", "169"], ["input", "keyevent", "168"]),
    ]
    for name, out_cmd, in_cmd in ways:
        if stop.is_set():
            return
        before = dev.screenshot()
        r = dev._run("shell", *out_cmd)
        err = (r.stderr or b"").decode("utf-8", "ignore").strip().splitlines()[-1:] if r.returncode else []
        _nap(stop, 1.2, 1.5)
        sc = _view_scale(before, dev.screenshot())
        log(f"[i] ADB zoom test - {name}: view scale {sc if sc is None else round(sc, 3)}" + (f" (adb: {err[0]})" if err else ""))
        if sc and sc < 0.97:
            log(f"[+] ADB zoom test - {name} ZOOMED OUT")
        b2 = dev.screenshot()
        dev._run("shell", *in_cmd)                         # put the zoom back as it was
        _nap(stop, 1.2, 1.5)
        s2 = _view_scale(b2, dev.screenshot())
        if s2 and abs(s2 - 1) > 0.03:
            log(f"[i] ADB zoom test - {name} back: view scale {round(s2, 3)}")
    log("[*] ADB zoom test done")


def run_test_pins(dev, cfg, log, stop):
    """Developer test (owner 27 Oct): on an instance that uses its culture's map, go to EVERY fixed building by its culture
    pin and open its menu (the menu name is checked; nothing is pressed). Ends with a summary of what opened and what not,
    so the shipped pins can be checked before a release. Pictures of the misses: debug/duty_pintest_<name>.png."""
    cult = city_culture(dev)
    if not cult:
        log("[!] Pin test: this instance does not use a culture map (it has its own map) - run it on a culture-matched instance")
        return
    if city_map(dev) is None:
        log("[!] Pin test: no city map loaded")
        return
    name = cult["culture"]
    pins = culture_pins(name)
    if not pins:
        log(f"[!] Pin test: no pins for {name.title()}")
        return
    log(f"[*] Pin test: {len(pins)} {name.title()} pins")
    ok, bad = [], []
    tmp = USER / "debug" / "pintest"
    tmp.mkdir(parents=True, exist_ok=True)
    for b in sorted(pins):
        if stop.is_set():
            break
        duty_progress()                                    # 20+ buildings take longer than the stuck-duty limit
        leave_to_city(dev, cfg, stop, log)
        t0 = time.time()
        pin = culture_pin(dev, b)
        try:
            r = find_on_map(dev, cfg, log, stop, b, None, {"map": pin, "dx": 0, "dy": 0}, tmp / f"{re.sub(r'[^A-Za-z]+', '_', b)}.png")
        except InstanceStopped:
            raise
        except Exception as e:
            log(f"[!]   Pin test: {b}: {e}")
            r = None
        secs = round(time.time() - t0)
        if r:
            ok.append(b)
            log(f"[+]   Pin test: {b} opened ({secs} s)")
        else:
            bad.append(b)
            rd_snap(dev.screenshot(), f"pintest_{re.sub(r'[^A-Za-z]+', '_', b)}")
            log(f"[!]   Pin test: {b} NOT opened ({secs} s) - picture debug/duty_pintest_{re.sub(r'[^A-Za-z]+', '_', b)}.png")
        leave_to_city(dev, cfg, stop, log)
    log(f"[*] Pin test {name.title()}: {len(ok)} of {len(ok) + len(bad)} opened" + (f"; NOT opened: {', '.join(bad)}" if bad else " - all good"))


MAP_REQUEST = "map_request.json"                          # written by the Map my city / Map city again button (web_app)


def map_request_set(dev):
    try:
        f = _map_dir(dev) / MAP_REQUEST
        f.parent.mkdir(parents=True, exist_ok=True)
        f.write_text(json.dumps({"t": time.time()}), encoding="utf-8")
    except Exception as _e:
        quiet_err("map_request_set", _e)


def map_request_fresh(dev, take=True):
    """Owner 28 Oct 12:53: K's map was wiped by a Map my city nobody pressed. A run that wipes needs a button press
    from the last 15 min; the request is used up when the run starts."""
    f = _map_dir(dev) / MAP_REQUEST
    try:
        ok = time.time() - float(json.loads(f.read_text(encoding="utf-8")).get("t", 0)) < UNLOCK_MIN * 60   # owner 30 Oct: busy instances start later
    except Exception:
        ok = False
    if take:
        try:
            f.unlink()
        except Exception:
            pass
    return ok


def run_map_city(dev, cfg, log, stop):
    """Duty 'Map my city': at the widest zoom, explore the city from the current view (each direction once from every
    view, one measured drag per step), keep every view that shows buildings and is new ground, then solve all the
    views' places from their picture links at once and save them as keyframes. The finger only chooses the next drag."""
    if not map_request_fresh(dev):
        log("[!] Map my city was not asked for on this instance (no button press in the last hour) - skipped, the map stays")
        return
    if city_locked(dev):
        log("[!] Map my city: this city's map is locked (press Unlock on the City map card first) - skipped, the map stays")
        return
    city_relock(dev)                                       # one Unlock = one run
    # Owner spec 28 Oct: Map my city (and Map city again) starts from 0 - this instance's picture and all its pins go.
    # Owner 30 Oct: ... but only when the new run works - a failed or stopped run puts the old map back.
    dev._wipe_backup = ""
    log("[*] Map my city: " + (wipe_city_map(dev, "Map my city") or "starting from 0"))
    backup = getattr(dev, "_wipe_backup", "")
    dev._mapping = True                                    # the city map + culture pins are usable while mapping
    mymap_save(dev, running=True, complete=False, stop=0, stops=0, found=0, total=len(MOVABLE_BUILDINGS), last="", missing=[])
    try:
        ok = _run_map_city(dev, cfg, log, stop)
        if ok is not False and not stop.is_set() and city_map(dev) is not None and (ok or (_map_dir(dev) / "map.json").exists()):
            mymap_save(dev, running=False, complete=True, at=time.strftime("%Y-%m-%d %H:%M"))
            log("[+] Map my city: done - the map stays until you press Map city again")
        else:
            mymap_save(dev, running=False, complete=False)
            if backup and restore_city_map(dev, backup):
                log("[i] Map my city: not finished - the old map and its pins are back (nothing lost)")
            else:
                log("[i] Map my city: not finished - press Map my city to start again")
    except Exception:
        if backup and restore_city_map(dev, backup):
            log("[i] Map my city: stopped by an error - the old map and its pins are back (nothing lost)")
        raise
    finally:
        dev._mapping = False
        dev._photo = None


def clear_to_bare_city(dev, cfg, log, stop, tries=4):
    """Owner 28 Oct 14:38: pop-ups come any time - clear the screen down to the bare city. Rewards are claimed, a Store
    is left; then Back until the game's 'exit?' box shows (= nothing else is open), Cancel. -> True when the bare city
    was reached."""
    for _ in range(tries):
        if stop.is_set():
            return False
        shot = dev.screenshot()
        if purchase_guard(dev, shot, log) or claim_popup(dev, shot, log):
            continue
        if cancel_quit_dialog(dev, shot, log):
            return True
        dev.back()
        _nap(stop, 0.9, 1.2)
        sh2 = dev.screenshot()
        if cancel_quit_dialog(dev, sh2, log):
            return True
    return False


def _run_map_city(dev, cfg, log, stop):
    leave_to_city(dev, cfg, stop, log)
    clear_to_bare_city(dev, cfg, log, stop)                # owner 28 Oct: Rob's Daily Rewards was still open when the zoom began
    zoom_out_full(dev, cfg, stop, log)
    nav = CityNav(dev, stop, log, pause=0.6)
    for attempt in range(3):                               # a pop-up in front makes the culture match fail: clear, try again
        if try_culture_match(dev, cfg, log, stop, nav):
            run_map_movable(dev, cfg, log, stop)           # fixed buildings = culture pins, movable ones = found in the sweep
            return True
        if stop.is_set():
            return False
        if attempt < 2:
            log("[i]   the city did not match a culture map - a pop-up may be in the way: clearing the screen and trying again")
            leave_to_city(dev, cfg, stop, log)
            clear_to_bare_city(dev, cfg, log, stop)
    if CULTURES:                                           # never the old walk with nothing on screen (Rob 14:22: 'done' with no map)
        log("[!] Map my city: the city did not match any culture map 3 times - stopped, nothing marked as mapped (press Map my city again)")
        return False
    x, y, w, h = CITY_VIEW
    STEPX, STEPY = int(w * 0.5), int(h * 0.6)          # one step in GAME px: views overlap half sideways, 40 % up/down. The
    views = []                                             # finger distance comes from the measured gain (a fixed 234 finger px
    t0 = time.time()                                       # moved up to 340 game px = 20 px overlap, no picture link); a third
    # of a view sideways (120 px) was not enough on Kiravik's east side (cliff, few features): 03:28 "no picture link".
    drags = [0]
    gain = [1.3, 1.3]                                      # game px per finger px, per axis (measured as we go)

    def known(px_, py_):
        """Is this camera place within one third of a view of ground we already keep?"""
        return any(abs(ex - px_) < 120 and abs(ey - py_) < 120 for _, _, _, ex, ey in views)

    def anchor(k, d, g):
        """Where the pictures say the camera is: median of the places implied by picture links to the kept views nearby
        (by the running estimate). -> (x, y) or None when no nearby view links. The drag estimates drift (24 Oct 02:44:
        164 moves put 3 'new' views on one edge spot and lost the west half as a separate group), the pictures do not."""
        order = sorted(range(len(views)), key=lambda i: abs(views[i][3] - nav.cx) / w + abs(views[i][4] - nav.cy) / h)
        for rng in (1.5, None):                            # the 4 nearest first; then ALL views (a drag read as 0 by the static
            px_, py_ = [], []                              # HUD pixels leaves the estimate a whole step off - 24 Oct 03:28)
            for i in (order[:4] if rng else order):
                _, g2, f2, ex, ey = views[i]
                if rng and not (abs(ex - nav.cx) < w * rng and abs(ey - nav.cy) < h * rng):
                    continue
                s = _kf_link(f2, (k, d), g2, g)
                if s:
                    px_.append(ex - s[0])
                    py_.append(ey - s[1])
            if px_:
                ax, ay = float(np.median(px_)), float(np.median(py_))
                if rng is None or abs(ax - nav.cx) > 60 or abs(ay - nav.cy) > 60:
                    log(f"[i]   view at {round(nav.cx)},{round(nav.cy)}: the pictures put it at {round(ax)},{round(ay)} ({len(px_)} links{'' if rng else ', found far from the estimate'})")
                return ax, ay
        return None

    nolink = [0]                                           # views in a row that linked to nothing (a window over the city?)
    last = [None]                                          # the settled picture the camera is on now (reused: one
                                                           # screenshot round per move instead of three)

    def clean_shot(shot=None):
        shot = dev.screenshot() if shot is None else shot
        if view_of(shot, cfg) != "city":
            if find_text(shot, ["disconnected", "someone login", "logged in elsewhere", "another device"], region=(60, 250, 360, 300), cutoff=0.8):
                raise RuntimeError("the game was opened on another device - mapping stopped (the bot waits and reclaims it, then maps again)")
            leave_to_city(dev, cfg, stop, log)
            shot = nav._settled()
        if find_detail_icon(shot):
            close_ring(dev, stop, (270, 490))
            shot = nav._settled()
        last[0] = shot
        return shot

    def keep(shot):
        """Keep this view when it shows buildings (the countryside / water has few feature points and no links)."""
        g = _kf_gray(shot)
        k, d = _kf_feats(g)
        if d is None or len(k) < 700:
            log(f"[i]   view at {round(nav.cx)},{round(nav.cy)}: {0 if d is None else len(k)} points - countryside, not kept")
            return False
        if views:
            a = anchor(k, d, g)
            if a is None:
                log(f"[i]   view at {round(nav.cx)},{round(nav.cy)}: no picture link to any kept view - not kept")
                rd_snap(shot, f"map_x{drags[0]:03d}")       # debug: the view that did not link
                nolink[0] += 1
                if nolink[0] >= 2:                         # Stalds 24 Oct 05:14: a "Bounty Cave" sale window over the city (HUD
                    nolink[0] = 0                          # still visible = looks like the city) - 7 unlinked views in 10 min
                    log("[!]   two views in a row link to nothing - a window may be covering the city, closing pop-ups")
                    clear_popups(dev, cfg, log, stop, rounds=3)
                    last[0] = None
                return False
            nolink[0] = 0
            nav.cx, nav.cy = a                             # the estimate follows the pictures from here on
        if known(nav.cx, nav.cy):                          # the same ground again (the edge slid the camera back)
            return False
        views.append((shot[y:y + h, x:x + w].copy(), g, (k, d), nav.cx, nav.cy))
        rd_snap(shot, f"map_v{len(views):02d}")
        log(f"[i]   map view {len(views)} at about {round(nav.cx)},{round(nav.cy)} ({len(k)} points)")
        log("@act " + json.dumps({"k": "step", "text": f"Duty: Mapping {len(views)} views"}))   # progress in the instance chip
        if len(views) % 5 == 0:
            log(f"[i]   Map my city: {len(views)} views, {drags[0]} moves, {round((time.time() - t0) / 60)} min")
        return True

    def move(dx, dy):
        """ONE measured drag per step (pan() tops a step up with extra drags: 20 s per step on Kiravik 24 Oct 00:08).
        Wherever the camera lands is fine - the places come from the pictures, not from the steps."""
        fx = max(-300.0, min(300.0, dx / gain[0]))         # finger px for the wanted game px (kept inside the map area)
        fy = max(-560.0, min(560.0, dy / gain[1]))
        ddx, ddy, after = nav._drag(270 + fx / 2, 440 + fy / 2, 270 - fx / 2, 440 - fy / 2, before=last[0])
        last[0] = after
        drags[0] += 1
        nav.cx -= ddx
        nav.cy -= ddy
        for a, f, m in ((0, fx, ddx), (1, fy, ddy)):       # learn the gain from full drags (not the edge's short ones)
            if abs(f) >= 100 and abs(m) >= abs(f) / 2:
                gain[a] = max(0.8, min(2.0, 0.7 * gain[a] + 0.3 * abs(m) / abs(f)))
        return -ddx, -ddy

    def timed_out():
        if stop.is_set() or time.time() - t0 > KF_MAP_MINUTES * 60:
            log(f"[!]   Map my city: stopping after {round((time.time() - t0) / 60)} min - saving what there is")
            return True
        return False

    keep(clean_shot())
    # The frontier is the VIEWS, not rows: the city is a diamond and its slanted edges slide the camera sideways, so a
    # row sweep ends early (00:22 run: 9 views) while from every view each of the 4 directions is tried once and
    # wherever the camera lands is a new view when it is new ground (the 21:45 run reached all 60 views this way).
    STEP = ((STEPX, 0), (0, STEPY), (-STEPX, 0), (0, -STEPY))
    tried = [set()]                                        # per view: directions already tried from it
    at = 0                                                 # the view the camera is on (or nearest to)

    def nearest():
        return min(range(len(views)), key=lambda i: abs(views[i][3] - nav.cx) + abs(views[i][4] - nav.cy))

    # No "idle" stop: Kiravik 24 Oct 01:45 ended after 8 old-ground moves in a row at the diamond's edge with half the
    # city unexplored (18 views, 13 min) while Stalds got the whole city (51 views, 28 min) only because its edge runs were
    # shorter. The walk ends when every kept view has had its 4 directions; the time cap is the safety.
    while len(views) < 80 and not timed_out():            # ~45 views with half-view steps; Stalds needed 51 at a third
        if len(tried[at]) == 4:                            # this view is done: go to the nearest view with directions left
            cand = [i for i in range(len(views)) if len(tried[i]) < 4]
            if not cand:
                break
            at = min(cand, key=lambda i: abs(views[i][3] - nav.cx) + abs(views[i][4] - nav.cy))
            for _ in range(4):
                rx, ry = views[at][3] - nav.cx, views[at][4] - nav.cy
                if abs(rx) < 80 and abs(ry) < 80 or timed_out():
                    break
                move(max(-STEPX, min(STEPX, rx)), max(-STEPY, min(STEPY, ry)))
            continue
        # Directions whose landing (by the measured gain) is ground we already keep - the way we came, a neighbour's
        # view - are marked tried without a drag: half of all moves landed on old ground before (Stalds: 137 moves, 56 views).
        for d in STEP:
            if d not in tried[at] and known(nav.cx + d[0], nav.cy + d[1]):
                tried[at].add(d)
        left = [d for d in STEP if d not in tried[at]]
        if not left:
            continue
        # Outward first (away from the centre of what is mapped) so the walk sweeps to the edge instead of circling
        # the start; sideways before up/down (the diamond is wider than tall).
        cx0 = sum(v[3] for v in views) / len(views)
        cy0 = sum(v[4] for v in views) / len(views)
        sx, sy = max(left, key=lambda d: (d[0] / STEPX * (nav.cx - cx0) + d[1] / STEPY * (nav.cy - cy0), abs(d[0]) > 0))
        tried[at].add((sx, sy))
        move(sx, sy)
        if keep(clean_shot(last[0])):
            tried.append(set())
            at = len(views) - 1
        else:                                              # old ground (the edge: did not move, slid, or sprang back)
            at = nearest()
    if len(views) < 2:
        log("[!]  Map my city: fewer than 2 views with buildings - nothing saved")
        return
    # solve the places from the pictures
    t1 = time.time()
    edges = _kf_links_all([(v[1], v[2]) for v in views], w, h)
    kept, px, py = _kf_solve(len(views), edges)
    d = _map_dir(dev)
    d.mkdir(parents=True, exist_ok=True)
    for old in d.glob("kf_*.png"):
        old.unlink()
    kfs = []
    for q, i in enumerate(kept):
        cv2.imwrite(str(d / f"kf_{q + 1:02d}.png"), views[i][0])
        kfs.append({"file": f"kf_{q + 1:02d}.png", "x": float(px[q]), "y": float(py[q])})
    W, H = int(px.max()) + w + 1, int(py.max()) + h + 1   # the stitched picture, for the user
    canvas = np.zeros((H, W, 3), np.uint8)
    for q, i in enumerate(kept):
        X, Y = int(round(px[q])), int(round(py[q]))
        canvas[Y:Y + h, X:X + w] = views[i][0]
    cv2.imwrite(str(d / "map.png"), canvas)
    meta = {"at": time.strftime("%Y-%m-%d %H:%M"), "views": len(kept), "size": [W, H], "keyframes": kfs,
            "links": len(edges), "zoomed_out": True}
    (d / "map.json").write_text(json.dumps(meta), encoding="utf-8")
    try:
        (d / "culture.json").unlink()                      # the own walked map is used from now on
    except Exception:
        pass
    _CITY_MAPS.pop(str(getattr(dev, "serial", "default")), None)
    for p in d.glob("*.json"):                             # learned buildings' map places belonged to the old map
        if p.stem != "map" and not p.stem.endswith("_prev"):
            try:
                m = json.loads(p.read_text(encoding="utf-8"))
                if "map" in m and m.get("by") != "user":   # pins the user placed by hand (Fix pins) stay
                    m.pop("map", None)
                    p.write_text(json.dumps(m), encoding="utf-8")
            except Exception:
                pass
    dropped = len(views) - len(kept)
    log(f"[+]  City map built: {len(kept)} keyframes ({dropped} views without a picture link dropped), {len(edges)} links, "
        f"{W}x{H} px, {drags[0]} moves, {round(time.time() - t0)} s (solve {round(time.time() - t1)} s)")
    if not stop.is_set():
        run_map_movable(dev, cfg, log, stop)               # the movable buildings on the own walked map too


_BUFF_SWIPES = {}                                          # serial -> swipes down the City Buff list to City Labor
CITY_BUFF_ICON = (27, 114)                                 # buff icon under the avatar (owner recording 25 Oct 16:02)


def city_buff_jump(dev, cfg, log, stop):
    """Owner 25 Oct: the game's own jump. City -> buff icon (top-left) -> City Buff page -> row 'City Labor' -> its arrow:
    the game returns to the city with the camera centred on the PRISON. Only City Labor jumps to a building (every other
    row opens Use Item). Used for Labor and as the camera ANCHOR for every other pinned building.
    -> True when back on the city after the jump."""
    leave_to_city(dev, cfg, stop, log)
    if stop.is_set():
        return False
    dev.tap(*CITY_BUFF_ICON)
    _nap(stop, 1.6, 2.0)
    shot = dev.screenshot()
    if not rd_seen(shot, ["City Buff"], region=(100, 0, 340, 70)):
        rd_snap(shot, "buff_0_nopage")
        log("[i]   City Buff: the buff page did not open")
        leave_to_city(dev, cfg, stop, log)
        return False
    hit = None
    known = _BUFF_SWIPES.get(dev.serial, 0)               # swipes it took last time: do them blind, read only from there
    for _ in range(max(0, known - 1)):
        if stop.is_set():
            return False
        dev.swipe(270, 740, 270, 300, 1200)
        _nap(stop, 0.5, 0.6)
    done = max(0, known - 1)
    if done:
        _nap(stop, 0.6, 0.8)
        shot = dev.screenshot()
    same = 0
    for i in range(18):                                    # active buffs sit at the top - the row moves, find it by its words
        if stop.is_set():                                  # (Kiravik 27 Oct: 6 long buffs on top, the row sat past 8 swipes)
            return False
        hit = find_text(shot, ["City Labor"], region=(120, 70, 360, 860), cutoff=0.72)
        dy = 22
        if not hit:                                        # the gold title reads badly (Kiravik 16:16): the white line under it
            hit = find_text(shot, ["instantly gain resources", "resources from Main City"], region=(120, 70, 360, 860), cutoff=0.72)
            dy = -5
        if hit and hit[1] <= 800:
            _BUFF_SWIPES[dev.serial] = done
            break
        hit = None
        prev = shot
        if i < 14:
            dev.swipe(270, 740, 270, 300, 1200)            # list up, held (owner holds the finger: no glide, sharp picture)
            done += 1
        else:
            dev.swipe(270, 300, 270, 740, 1200)            # overshot: back down
            done -= 1
        _nap(stop, 0.9, 1.1)
        shot = dev.screenshot()
        if float(cv2.absdiff(prev[70:900], shot[70:900]).mean()) < 1.5:   # the list did not move: end of the page
            same += 1
            if same >= 2 and i < 14:
                break                                      # bottom reached without the row - no point swiping on
        else:
            same = 0
    if not hit:
        rd_snap(shot, "buff_1_norow")
        log("[i]   City Buff: no 'City Labor' row found")
        leave_to_city(dev, cfg, stop, log)
        return False
    dev.tap(505, min(900, hit[1] + dy))                    # the row's arrow (right side, middle of the row)
    _nap(stop, 2.2, 2.6)
    shot = dev.screenshot()
    if rd_seen(shot, ["City Buff"], region=(100, 0, 340, 70)):
        dev.tap(270, min(900, hit[1] + 30))                # owner tapped the row itself - try that too
        _nap(stop, 2.2, 2.6)
        shot = dev.screenshot()
    if view_of(shot, cfg) != "city":
        rd_snap(shot, "buff_2_nocity")
        log("[i]   City Buff: the City Labor jump did not land on the city")
        leave_to_city(dev, cfg, stop, log)
        return False
    log("[i]   City Buff: jumped to the Prison (City Labor)")
    return True


BUFF_PRISON_SPOTS = [(290, 480), (270, 490), (300, 450), (260, 455), (290, 520)]   # Prison in the middle after the jump


def buff_anchor(dev, cfg, log, stop, cmap):
    """Camera anchor: City Labor jump -> camera on the Prison -> where is the camera on the map? -> (cx, cy) or None."""
    if not city_buff_jump(dev, cfg, log, stop):
        return None
    shot = dev.screenshot()
    r = cmap.locate(shot)
    rd_snap(shot, "nav_anchor")
    if r:
        log(f"[i]   nav: anchor_locate=hit cx={round(r[0])} cy={round(r[1])} points={r[2]} shot=debug/duty_nav_anchor.png")
    else:
        log("[i]   nav: anchor_locate=miss shot=debug/duty_nav_anchor.png")
    if r:
        log(f"[i]   anchor: Prison jump - camera at {round(r[0])},{round(r[1])}")
        return r[0], r[1]
    pin = culture_pin(dev, "Prison")
    if pin is None:
        log("[i]   anchor: Prison jump, but the view is not on the map and there is no Prison pin")
        return None
    cx, cy = pin[0] - BUFF_PRISON_SPOTS[0][0], pin[1] - BUFF_PRISON_SPOTS[0][1]
    log(f"[i]   anchor: Prison jump - camera taken from the Prison pin {round(pin[0])},{round(pin[1])}")
    return cx, cy


_DRAG_SCALE = {}          # serial -> map pixels moved per finger pixel (learned by jump_to_pin)


def jump_to_pin(dev, cfg, log, stop, nav, cmap, mapx, mapy):
    """Owner 25 Oct: reach a pinned building like a jump, no roaming. 1) anchor: drag to the city's top-left corner until
    the map stops (the edge is the only camera place the game always returns to the same); read the camera once there.
    2) split the whole corner->pin vector into 1-4 fixed drags (each <= 330 x 500 px, ends off the side button columns),
    NO looking between them. 3) wait 1 s for the glide / spring-back, ONE check on the map -> the pin's screen place.
    -> (sx, sy) or None (then the caller's closed loop takes over)."""
    import math
    x, y, w, h = CITY_VIEW
    mid_x, mid_y = x + w / 2, y + h / 2
    t0 = time.time()
    shot = dev.screenshot()                                # owner 25 Oct 15:15: no corner reset - start from where the camera is
    if find_detail_icon(shot):
        close_ring(dev, stop, (270, 490))
        shot = dev.screenshot()
    r = cmap.locate(shot)                                  # already looking at the pin? then no jump at all
    rd_snap(shot, "nav_initial")
    if not r:                                              # fix C (owner 28 Oct): drive back onto the known city first
        log("[i]   nav: initial_locate=miss shot=debug/duty_nav_initial.png - relocating")
        r = relocate_view(dev, cfg, log, stop, cmap, nav)   # (pastes its own located screenshot)
    else:
        _city_seen(dev, shot, r)
    if r:
        log(f"[i]   nav: initial_locate=hit cx={round(r[0])} cy={round(r[1])} points={r[2]} shot=debug/duty_nav_initial.png")
    else:
        log("[i]   nav: initial_locate=miss shot=debug/duty_nav_initial.png")
    if r and 110 <= mapx - r[0] <= 410 and 220 <= mapy - r[1] <= 740:
        log(f"[i]   nav: origin_used=initial cx={round(r[0])} cy={round(r[1])}")
        nav.cx, nav.cy = r[0], r[1]                        # the caller saves the building's map place from nav (27 Oct: left at 0,0 -> Tavern saved at the corner)
        return mapx - r[0], mapy - r[1]
    # Owner 27 Oct: the camera is measured after every slow drag now, so the current view is a good enough start -
    # the City Buff (Prison) anchor is only the fallback when the view is NOT found on the map (on Kiravik the buff
    # list is long and 'City Labor' was never found: ~2 min lost on every trip, the task then parked).
    if r:
        log(f"[i]   nav: origin_used=initial cx={round(r[0])} cy={round(r[1])}")
    else:
        a = buff_anchor(dev, cfg, log, stop, cmap)
        if a:
            log(f"[i]   nav: origin_used=anchor cx={round(a[0])} cy={round(a[1])}")
            r = a
        else:
            log("[i]   nav: origin_used=none")
            log("[i]   jump: no anchor and this view is not on the map - using the step-by-step route")
            return None
    cx, cy = r[0], r[1]
    dx, dy = (mapx - cx) - mid_x, (mapy - cy) - mid_y      # how far the camera has to move (map px)
    if abs(dx) < 120 and abs(dy) < 150 and 110 <= mapx - cx <= 410 and 220 <= mapy - cy <= 740:
        nav.cx, nav.cy = cx, cy
        return mapx - cx, mapy - cy                        # already on screen: no drag at all
    k_scale = _DRAG_SCALE.get(dev.serial, 1.0)             # learned: map px moved per finger px (slow drag: ~1.0 expected)
    log(f"[i]   jump: camera at {round(cx)},{round(cy)} - pin {round(mapx)},{round(mapy)} - {round(dx)},{round(dy)} px away (scale {k_scale:.2f})")
    before = dev.screenshot()
    last_loc = None
    t_lim = t0 + 30                                        # plan 25 Oct: max ~6 drags / 30 s, then the task fails and retries later
    zero = 0
    for k in range(6):                                     # closed loop: slow drag -> measure the real move -> correct
        if stop.is_set() or time.time() > t_lim or dev.serial in TASK_ABORT:
            break
        sx, sy = mapx - cx, mapy - cy                      # pin on screen now (estimated)
        if 110 <= sx <= 410 and 220 <= sy <= 740:          # safely inside the map area (Kiravik 27 Oct: a pin at x=419 put
            break                                          # the tap-around spots on the right HUD badges = event page)
        rx, ry = sx - mid_x, sy - mid_y                    # remaining camera move (map px)
        fdx = max(-330.0, min(330.0, rx / k_scale))        # finger move, one long drag at a time
        fdy = max(-500.0, min(500.0, ry / k_scale))
        ln = (fdx * fdx + fdy * fdy) ** 0.5
        if ln < 60:                                        # tiny drags are ignored or act as taps: stretch to 60 px
            fdx, fdy = (fdx / ln * 60, fdy / ln * 60) if ln else (0.0, 60.0)
        fx, fy = 270 + fdx / 2, 480 + fdy / 2
        tx, ty = 270 - fdx / 2, 480 - fdy / 2
        fx, tx = max(100, min(440, fx)), max(100, min(440, tx))   # safe zone (no HUD under the finger)
        fy, ty = max(200, min(760, fy)), max(200, min(760, ty))
        fx, fy, tx, ty = calm_drag(before, fx, fy, tx, ty)        # start on empty ground: never opens a ring
        dev.slow_drag(int(fx), int(fy), int(tx), int(ty))
        _nap(stop, 0.4, 0.5)
        after = nav._settled()
        mdx, mdy = safe_shift(before, after, tx - fx, ty - fy)    # map content shift on screen (cheap, no map match)
        fl = max(1.0, ((tx - fx) ** 2 + (ty - fy) ** 2) ** 0.5)
        ratio = ((mdx * mdx + mdy * mdy) ** 0.5) / fl
        log(f"[i]   nav: drag {k + 1} finger={round(tx - fx)},{round(ty - fy)} map={round(mdx)},{round(mdy)} ratio={ratio:.2f}")
        if ratio < 0.15:                                   # 0x: nothing moved - a pop-up, a ring or the city edge
            zero += 1
            if find_detail_icon(after):
                close_ring(dev, stop, (270, 490))
                after = dev.screenshot()
            elif zero == 1:
                clear_popups(dev, cfg, log, stop, rounds=2)
                after = dev.screenshot()
            else:
                log("[i]   jump: the map does not move here (city edge?) - checking the map")
                before = after
                break
            before = after
            continue
        zero = 0
        cx, cy = cx - mdx, cy - mdy                        # the map moved by (mdx, mdy) on screen -> camera moved the other way
        ra = cmap.locate(after)                            # K 27 Oct: a 330 px drag leaves ~30 px overlap, the frame measure then
        last_loc = (after, ra) if ra else None             # owner 30 Oct 12:13: a locate costs up to ~20 s on a busy PC - reused below
        if ra:                                             # falls back to 'moved like the finger' and drifted 197 px - the map
            cx, cy = ra[0], ra[1]                          # match is absolute, so it wins whenever it hits
            log(f"[i]   nav: located cx={round(cx)} cy={round(cy)} points={ra[2]}")
            _city_seen(dev, after, ra)
        if fl > 150:
            k_new = max(0.6, min(2.5, ratio))
            k_scale = round(0.5 * k_scale + 0.5 * k_new, 3) if dev.serial in _DRAG_SCALE else round(k_new, 3)
            _DRAG_SCALE[dev.serial] = k_scale
        before = after
    if find_detail_icon(before):
        close_ring(dev, stop, (270, 490))
        before = dev.screenshot()
    r = last_loc[1] if last_loc is not None and last_loc[0] is before else cmap.locate(before)   # the one real check on the map
    if not r:
        log("[i]   jump: the view after the drags is not found on the map - using the step-by-step route")
        return None
    nav.cx, nav.cy = r[0], r[1]
    err = ((nav.cx - cx) ** 2 + (nav.cy - cy) ** 2) ** 0.5
    sx, sy = mapx - nav.cx, mapy - nav.cy
    log(f"[i]   jump: camera at {round(nav.cx)},{round(nav.cy)} after {time.time() - t0:.0f}s - pin on screen at {round(sx)},{round(sy)} (dead-reckoning was {round(err)} px off)")
    if 110 <= sx <= 410 and 220 <= sy <= 740:
        return sx, sy
    return None


def goto_on_map(dev, cfg, log, stop, nav, cmap, mapx, mapy, tol=60):
    """Closed loop on the own map: locate -> drag the difference -> locate again, until map point (mapx, mapy) is near
    the middle of the view. -> the point's screen place (sx, sy), or None."""
    x, y, w, h = CITY_VIEW
    mid_x, mid_y = x + w / 2, y + h / 2
    try:
        at = jump_to_pin(dev, cfg, log, stop, nav, cmap, mapx, mapy)
        if at:
            log(f"[i]   nav: goto_on_map=success via=jump sx={round(at[0])} sy={round(at[1])}")
            return at
    except Exception as _e:
        quiet_err("jump_to_pin", _e)
    lost = 0
    prev_cam = None
    for i in range(8):
        if stop.is_set():
            log("[i]   nav: goto_on_map=failure reason=stopped")
            return None
        shot = nav._settled() if i else dev.screenshot()
        if find_detail_icon(shot):
            close_ring(dev, stop, (270, 490))
            shot = nav._settled()
        r = cmap.locate(shot)
        if not r:
            lost += 1
            if lost >= 3:
                log("[i]   the screen is not found on the city map (zoomed differently, window in the way, or the city changed?)")
                log("[i]   nav: goto_on_map=failure reason=map_not_located")
                return None
            r = relocate_view(dev, cfg, log, stop, cmap, nav)   # fix C: drive back toward the city, don't give up
            if not r:
                continue
        else:
            _city_seen(dev, shot, r)
        lost = 0
        nav.cx, nav.cy = r[0], r[1]
        sx, sy = mapx - nav.cx, mapy - nav.cy
        # owner 25 Oct: reach the building, don't polish the camera - anywhere safely on screen is good enough
        # (a building near the city edge can never be centred: the map springs back, Kiravik looped 2 min on the Tavern)
        if (abs(sx - mid_x) <= tol and abs(sy - mid_y) <= tol) or (110 <= sx <= 410 and 220 <= sy <= 740):
            log(f"[i]   camera at {round(nav.cx)},{round(nav.cy)} on the map ({r[2]} points), target on screen at {round(sx)},{round(sy)}")
            log(f"[i]   nav: goto_on_map=success via=closed_loop sx={round(sx)} sy={round(sy)}")
            return sx, sy
        if i and prev_cam and abs(prev_cam[0] - nav.cx) < 15 and abs(prev_cam[1] - nav.cy) < 15:
            log("[!]   camera: the last drag did not move the map (a button or building under the finger?)")
            still_n = getattr(nav, "_still_n", 0) + 1
            nav._still_n = still_n
            if still_n >= 2:                               # owner 28 Oct (Rob, 55 min): the city edge - don't fight it
                log("[i]   nav: goto_on_map=failure reason=edge (the map does not move this way) - skipping")
                nav._edge = True
                return None
        prev_cam = (nav.cx, nav.cy)
        log(f"[i]   camera at {round(nav.cx)},{round(nav.cy)} ({r[2]} points) - target {round(sx - mid_x)},{round(sy - mid_y)} px from the middle, moving (round {i + 1})")
        nav.pan(sx - mid_x, sy - mid_y)                    # measured drags (the diamond's edge stops them safely)
    log("[i]   nav: goto_on_map=failure reason=attempts_exhausted")
    return None


def find_on_map(dev, cfg, log, stop, bname, tpl, meta, p):
    """Building with a known map place: go there on the own map, check its learned picture near the expected spot, tap.
    -> True (ring open), False (went there but not it), None (no map / place / camera lost: explore instead)."""
    cmap = city_map(dev)
    if cmap is None or not meta.get("map"):
        return None
    nav = CityNav(dev, stop, log)
    at = goto_on_map(dev, cfg, log, stop, nav, cmap, float(meta["map"][0]), float(meta["map"][1]))
    if at is None:
        return None
    shot = dev.screenshot()
    mv, ml, f = _learn_match(shot, tpl) if tpl is not None else (0.0, None, 1.0)
    ex, ey = at
    if ml:
        x, y = ml[0] + int(meta["dx"] * f), ml[1] + int(meta["dy"] * f)
    if ml and mv >= 0.6 and abs(x - ex) < 90 and abs(y - ey) < 90:
        spot = (x, y)
    else:
        spot = (int(ex), int(ey))                          # trust the map place (the picture may have changed: upgrade, decoration)
        if tpl is not None:
            log(f"[i]   {bname}: picture match {mv:.2f} near the map place - tapping the map place")
    if not (60 <= spot[0] <= 470 and 150 <= spot[1] <= 820):
        return None
    # Kiravik 25 Oct 14:02: camera reached the Tavern pin, but one tap exactly on the pin hit the ground (no ring) and the
    # map route gave up. A pin is a hand-placed point: try it, then a few spots around it.
    near = [spot] + [(spot[0] + ox, spot[1] + oy) for ox, oy in ((0, 45), (-45, 20), (45, 20), (0, 80), (-40, -30), (0, -40))]   # lower spots first: icons float above a building (Kiravik Tavern chest 27 Oct)
    near = [(x, y) for x, y in near if 70 <= x <= 420 and 160 <= y <= 800]   # never the HUD columns / bars
    rd_snap(shot, "nav_arrived")
    log(f"[i]   nav: arrived - tapping {bname} at {spot} shot=debug/duty_nav_arrived.png")
    if open_building_here(dev, cfg, log, stop, bname, spots=near, how=f"the city map (match {mv:.2f})", trust=mv >= 0.85):
        try:                                               # refresh the place and the picture (open_building_here learned it)
            m2 = json.loads(p.with_suffix(".json").read_text(encoding="utf-8")) if p.with_suffix(".json").exists() else {"dx": 0, "dy": 0}
            if not m2.get("map"):                          # owner spec 28 Oct: an existing pin never moves
                m2["map"] = [round(nav.cx + spot[0]), round(nav.cy + spot[1])]
            m2["worked"] = time.strftime("%Y-%m-%d %H:%M")   # this picture opened its building: good for the picture database
            p.with_suffix(".json").write_text(json.dumps(m2), encoding="utf-8")
        except Exception:
            pass
        return True
    return False                                           # the pin stays; the task tries again later

# --- Alliance page ------------------------------------------------------------------------------------------------
ALLIANCE_GIFT_OPEN_ALL = (320, 923)        # owner recording 29 Oct: orange 'Open All' (grey when nothing is left)
ALLIANCE_HELP_ALL = (309, 912)             # owner recording 29 Oct: green 'Help All' (gone when nobody needs help)
ALLIANCE_BACK_ARROW = (40, 50)             # gold Back arrow top left (also closes the gift 'Congratulations!' list)


def btn_colour(shot, x, y, w=40, h=12):
    """'orange' / 'green' / 'grey' for the button under (x, y): share of strongly coloured pixels around the spot
    (white text and the recorder's red circle are ignored)."""
    try:
        hsv = cv2.cvtColor(shot[max(0, y - h):y + h, max(0, x - w):x + w], cv2.COLOR_BGR2HSV)
        n = float(hsv.shape[0] * hsv.shape[1])
        green = cv2.inRange(hsv, (40, 90, 50), (85, 255, 255)).sum() / 255 / n
        orange = cv2.inRange(hsv, (8, 120, 110), (28, 255, 255)).sum() / 255 / n
    except Exception:
        return "grey"
    if green > 0.3 and green > orange:
        return "green"
    if orange > 0.3:
        return "orange"
    return "grey"


def alliance_page_btn(shot, words, region, spot, colour):
    """A button at the bottom of an Alliance sub-page that is ready to press: read by its word (else the recorded spot)
    and only when it has its live colour (`colour`); a grey one = nothing to do. -> (x, y) or None."""
    hit = rd_find(shot, words, region=region, cutoff=0.75)
    x, y = (hit[0], hit[1]) if hit else spot
    return (int(x), int(y)) if btn_colour(shot, int(x), int(y)) == colour else None


