# ------------------------------------------------------------ Royal Thief (owner's recording 22 Oct 21:38, project doc claude/flow_royal_thief.md)
# A thief only appears when an alliance member invites you (Invite icon on the left of the city / map).
# Invite > Royal Thief row > Go > tap a thief that is not killed > map flies there > tap it > Attack > Attack >
# troops (Power First or a preset) > March. No free march: wait for the soonest march to come back, then try again.
RT_POLL_MIN = 15                         # look for an Invite icon this often
RT_RECHECK_MIN = 5                       # after marching / when something got in the way: look again this soon
RT_THIEF_SPOTS = {"left": (120, 600), "mid": (288, 392), "right": (410, 600)}
RT_PRESETS = ["I", "II", "III", "IV", "V", "VI", "VII", "VIII"]


def rt_save(serial, **kw):
    with _DUTY_LOCK:
        data = load_duty_state()
        row = data.setdefault(serial or "default", {}).setdefault("royal_thief", {})
        row.update(kw)
        save_duty_state(data)


def rt_row(serial):
    return (load_duty_state().get(serial or "default") or {}).get("royal_thief") or {}


def rt_col(x):
    return "left" if x < 190 else ("mid" if x < 350 else "right")


def rt_marches(img):
    """World map March panel (top left): -> (busy, total, soonest_seconds or None), or None when not read."""
    busy = total = None
    # Open panel = "v March ... n/6" bar. On a busy map OCR splits or drops parts, so the count is read on its own
    # (right end of the bar) and "March" on the left; the folded "> March" pill has no count (owner screenshots 25 Oct).
    for r in ((200, 135, 120, 30), (200, 132, 130, 36), (0, 120, 320, 60)):
        m = re.search(r"\b(\d)\s*/\s*(\d)\b", " ".join(t for t, _ in rd_lines(img, r)))
        if m and 0 <= int(m.group(1)) <= int(m.group(2)) <= 8:
            break
    else:
        return None
    if not any("arch" in " ".join(t for t, _ in rd_lines(img, r)).lower() for r in ((0, 120, 320, 60), (0, 135, 320, 30), (0, 132, 160, 36))):
        return None
    busy, total = int(m.group(1)), int(m.group(2))
    if busy is None:
        return None
    waits = []
    txt = " ".join(t for t, _ in rd_lines(img, (40, 165, 240, 60 * max(1, busy)))).replace(";", ":")
    for h, mi, s in re.findall(r"(\d{1,2})\s*[:.]\s*(\d{2})\s*[:.]\s*(\d{2})", txt):
        waits.append(int(h) * 3600 + int(mi) * 60 + int(s))
    return busy, total, (min(waits) if waits else None)


def rt_go_rows(img):
    """Invitation list: -> y of each row's green Go button (x 390-480), top to bottom."""
    a = img[90:850, 390:480].astype(int)
    b, g, r = a[..., 0], a[..., 1], a[..., 2]
    ys = list(np.where(((g > 30) & (g > r + 25) & (g > b + 20)).mean(axis=1) > 0.5)[0])
    rows, start, prev = [], None, None
    for y in ys + [10 ** 6]:
        if start is None:
            start = prev = y
            continue
        if y - prev > 3:
            if 25 <= prev - start <= 80:
                rows.append(90 + int(start + prev) // 2)
            start = y
        prev = y
    return rows


def run_royal_thief(dev, cfg, log, stop):
    serial = getattr(dev, "serial", "")
    day = _game_day()
    row = rt_row(serial)
    done = row.get("done", []) if row.get("day") == day else []
    rt_save(serial, day=day, done=done, next_at=time.time() + RT_POLL_MIN * 60)

    def later(minutes, why):
        rt_save(serial, next_at=time.time() + minutes * 60)
        log(f"[*]  Royal Thief: {why} - again at {time.strftime('%H:%M', time.localtime(time.time() + minutes * 60))}")

    shot = dev.screenshot()
    p = rd_find(shot, ["Invite"], region=(0, 220, 130, 560), cutoff=0.75, whole=True)
    if not p:                                               # no invite = no thief to kill (Kiravik 27 Oct 20:23: said nothing)
        rd_snap(shot, "thief_0_noinvite")
        return later(RT_POLL_MIN, "no Invite button on the city screen (no thief invitation right now)")
    dev.tap(p[0], max(100, p[1] - 18))
    _nap(stop, 2.0, 2.5)
    shot = dev.screenshot()
    rd_snap(shot, "thief_1")
    if not rd_seen(shot, ["Invitation"], region=(0, 0, 540, 80)):
        dev.back()
        return later(RT_RECHECK_MIN, "the Invitation list did not open")
    rows = []
    for t, ws in rd_lines(shot, (0, 90, 540, 760)):
        if "thief" in t.lower():
            rows.append(int(sum(s[2] for s in ws) / len(ws)))
    if not rows:                                            # faint brown "Royal Thief" on beige is often not read
        rows = rt_go_rows(shot)                             # (Kiravik 27 Oct 20:37) - the green Go buttons are
        if rows:
            log(f"[i]  Royal Thief: {len(rows)} row(s) found by their Go button")
    target = None
    for y in rows:                                          # the inviter's name sits on the line above "Royal Thief"
        who = " ".join(t for t, _ in rd_lines(shot, (60, max(0, y - 40), 300, 30))).strip() or f"row{y}"
        if who not in done:
            target = (y, who)
            break
    if not target:
        dev.back()
        return later(RT_POLL_MIN, f"no new thief in the Invitation list ({len(rows)} row(s), all done today)")
    y, who = target
    dev.tap(438, max(100, y - 8))                           # green Go on that row
    _nap(stop, 2.5, 3.0)
    shot = dev.screenshot()
    rd_snap(shot, "thief_2")
    if not rd_seen(shot, ["Royal Thief", "Help kill"], region=(0, 0, 540, 160)):
        leave_to_city(dev, cfg, stop, log)
        return later(RT_RECHECK_MIN, "the Royal Thief page did not open")
    alive, killed = [], set()
    for t, ws in rd_lines(shot, (0, 200, 540, 300)):
        x = int(sum(s[1] for s in ws) / len(ws))
        if "killed" in t.lower():
            killed.add(rt_col(x))
        elif re.search(r"x\s*[:.]?\s*\d{3}", t.lower()):
            alive.append(rt_col(x))
    if row.get("who") == who and row.get("col") in killed:   # the thief we attacked is dead: this invite is done
        done.append(who)
        rt_save(serial, done=done, who="", col="")
        leave_to_city(dev, cfg, stop, log)
        log(f"[+]  Royal Thief: {who}'s thief killed")
        return
    cols = [c for c in ("mid", "left", "right") if c not in killed and (c in alive or not alive)]
    if row.get("who") == who and row.get("col") in cols:     # keep on the same thief until it is killed
        cols.remove(row["col"])
        cols.insert(0, row["col"])
    if not cols:
        done.append(who)
        rt_save(serial, done=done)
        leave_to_city(dev, cfg, stop, log)
        log(f"[+]  Royal Thief: all 3 of {who}'s thieves are killed")
        return
    col = cols[0]
    dev.tap(*RT_THIEF_SPOTS[col])
    shot = _wait_view(dev, cfg, stop, "landscape", 60)     # the map flies to the thief
    if shot is None:
        leave_to_city(dev, cfg, stop, log)
        return later(RT_RECHECK_MIN, "the map did not open")
    _nap(stop, 2.0, 2.5)
    shot = dev.screenshot()
    rd_snap(shot, "thief_3")
    mk = rt_marches(shot)
    if mk and mk[0] >= mk[1]:
        wait = (mk[2] or 120) + 20
        leave_to_city(dev, cfg, stop, log)
        return later(max(1, round(wait / 60)), f"all {mk[1]} marches are out")
    dev.tap(274, 477)                                      # the thief sits in the middle of the screen
    _nap(stop, 1.5, 2.0)
    if not rd_ring(dev, stop, ["Attack"]):
        leave_to_city(dev, cfg, stop, log)
        return later(RT_RECHECK_MIN, "no Attack on the thief")
    shot = dev.screenshot()
    rd_snap(shot, "thief_4")
    if not rd_tap(dev, stop, ["Attack"], region=(150, 680, 260, 130), whole=True, wait=(2.0, 2.5), shot=shot):
        leave_to_city(dev, cfg, stop, log)
        return later(RT_RECHECK_MIN, "no Attack button on the thief's page")
    shot = dev.screenshot()
    if not rd_seen(shot, ["Select a Preset", "March"], region=(0, 0, 540, 180)):
        rd_snap(shot, "thief_5")
        leave_to_city(dev, cfg, stop, log)
        return later(RT_RECHECK_MIN, "the March page did not open (no free march?)")
    troops = str(rd_opt(cfg, "royal_thief", "troops", "Power First"))
    if troops.startswith("Preset"):
        n = RT_PRESETS.index(troops.split()[-1]) if troops.split()[-1] in RT_PRESETS else 0
        for _ in range(2):                                  # the first tap on a preset is sometimes lost
            dev.tap(62 + n * 61, 115)
            _nap(stop, 1.4, 1.8)
    else:
        dev.tap(57, 928)                                    # small button bottom left -> Power First
        _nap(stop, 1.2, 1.5)
        if not rd_tap(dev, stop, ["Power First"], region=(90, 885, 230, 75), wait=(1.4, 1.8)):
            dev.tap(57, 928)
            _nap(stop, 1.2, 1.5)
            rd_tap(dev, stop, ["Power First"], region=(90, 885, 230, 75), wait=(1.4, 1.8))
    shot = dev.screenshot()
    rd_snap(shot, "thief_6")
    if not rd_tap(dev, stop, ["March"], region=(330, 880, 210, 75), wait=(2.0, 2.5), shot=shot):
        leave_to_city(dev, cfg, stop, log)
        return later(RT_RECHECK_MIN, "no March button")
    shot = dev.screenshot()
    if rd_seen(shot, ["cannot send more troops", "cannot send more"], region=(0, 150, 540, 450)):
        rd_snap(shot, "thief_7_full")                       # owner's recording 27 Oct 20:39: all marches out -> this note
        mk = None
        if not rt_marches(shot):                            # folded "> March" pill: open it to read the return times
            dev.tap(67, 143)
            _nap(stop, 1.2, 1.6)
            mk = rt_marches(dev.screenshot())
            dev.tap(67, 143)                                # fold it again (it hides the map)
        else:
            mk = rt_marches(shot)
        wait = ((mk[2] if mk and mk[2] else 120) + 20)
        leave_to_city(dev, cfg, stop, log)
        return later(max(1, -(-wait // 60)), "no free march (all marches out)")
    if rd_seen(shot, ["Select a Preset"], region=(0, 120, 540, 60)):
        rd_snap(shot, "thief_7")
        leave_to_city(dev, cfg, stop, log)
        return later(RT_RECHECK_MIN, "the march did not leave (no troops?)")
    rt_save(serial, who=who, col=col)
    later(RT_RECHECK_MIN, f"marched on {who}'s thief ({troops})")
    leave_to_city(dev, cfg, stop, log)


# ------------------------------------------------------------ Monster rally starter (owner's recording 23 Oct 07:44, project doc claude/flow_rally_monsters.md)
# Coordinates come from the Telegram section (live feed + boss finder). Map > coordinate search (Server / X / Y / Go) >
# tap the monster in the middle > Attack > monster page (name, level) > Alliance War > rally time > preset > March.
# No free march: stay on the monster until it is rallied (owner 23 Oct 08:20) - only a march line to it or the monster
# disappearing makes the bot move on. 'max_wait' minutes > 0 sets a limit (0 = no limit, the default).
# Skipped: a monster that is gone (no Attack / other name on its page) or that a march line is already going to.
MR_RUN_MIN = 30                          # one non-stop run lasts at most this long, then the main loop checks in (owner 25 Oct)
MR_POLL_MIN = 1                          # look for a new target this often (monsters die fast - owner 23 Oct)
MR_FORGET_MIN = 30                       # a target that was started / skipped is not tried again for this long
MR_CENTER = (272, 480)                   # the searched tile sits in the middle of the map
MR_ALLIANCE_WAR = (384, 768)              # Alliance War button on a monster page (Attack sits at 170)
MR_MARCH = (404, 910)                    # March button on the Alliance War troop page
MR_EMPTY = (330, 250)                     # a map spot with no button: closes a ring (40,640 was the Quests button)
MR_NEAR = [(0, 0), (0, -30)]             # owner 28 Oct 21:29: at most 2 taps - centre, then a little above (monster drawn off the tile centre)
MR_TIMES = {"5": (190, 512), "10": (395, 512), "30": (190, 590), "60": (395, 590)}   # Alliance War Rally! buttons (fallback spots)


def mr_save(serial, **kw):
    with _DUTY_LOCK:
        data = load_duty_state()
        row = data.setdefault(serial or "default", {}).setdefault("monster_rally", {})
        if "hold" in kw and kw["hold"] != row.get("hold"):
            kw["hold_at"] = time.time() if kw["hold"] else 0         # when this target started waiting ('Give up on monster')
        row.update(kw)
        save_duty_state(data)


def mr_row(serial):
    return (load_duty_state().get(serial or "default") or {}).get("monster_rally") or {}


MR_DEFAULT_RULES = [{"name": "Ymir", "min": 1, "max": 99, "preset": "I", "time": "5", "on": True}]


def mr_rules(cfg):
    """The Monster rallies tab: which monster (and levels) each preset attacks, and that preset's rally time."""
    rules = rd_opt(cfg, "monster_rally", "rules", None)
    out = []
    for r in (rules if isinstance(rules, list) else MR_DEFAULT_RULES):
        if not isinstance(r, dict) or not str(r.get("name") or "").strip() or r.get("on") is False:
            continue
        out.append({"name": str(r["name"]).strip(), "min": int(r.get("min") or 1), "max": int(r.get("max") or 99),
                    "preset": r.get("preset") if r.get("preset") in RT_PRESETS else "I",
                    "time": str(r.get("time")) if str(r.get("time")) in MR_TIMES else "5"})
    return out


# --- Hunts (owner 28 Oct 17:07): every preset hunts its own monster list in its own mode - Rally (Alliance War) or
# Solo (attack alone). Rally and Solo are equals. Smart mode is shown as "soon" in the app only.
MR_MODES = ("rally", "solo")
MR_ATTACK = (170, 768)                    # Attack button on a monster page (solo; Alliance War sits at 384)


def mr_button_y(page, default=768):
    """Height of the Attack / Alliance War buttons on a monster page. An ad row (e.g. Hunting Privilege Card)
    pushes them up from the usual 768, and a tap at 768 then lands outside the page and closes it."""
    try:
        h, w = page.shape[:2]
        b, g, r = [page[:, 90:250, i].astype(np.int16).mean(axis=1) for i in range(3)]   # Attack button = green
        rows = [y for y in range(int(h * 0.55), int(h * 0.95)) if g[y] > r[y] + 18 and g[y] > b[y] + 18 and g[y] > 38]
        best, run = [], []
        for y in rows:
            if run and y != run[-1] + 1:
                best, run = max(best, run, key=len), []
            run.append(y)
        best = max(best, run, key=len)
        if len(best) >= 25:
            return (best[0] + best[-1]) // 2
    except Exception:
        pass
    return default

RALLY_ONLY = {"aglaope"}                  # lower-case names that can only be rallied (owner 28 Oct; more to come)
SOLO_ONLY = {"goblin"}                     # lower-case names that can only be attacked solo (owner 28 Oct)


def mr_pnum(p):
    return RT_PRESETS.index(p) + 1 if p in RT_PRESETS else 1


def mr_presets(cfg):
    """Each preset's mode and solo hunt limit a day: {"I": {"mode": "rally", "hunts": 0}, ...}. Old settings = all Rally."""
    raw = rd_opt(cfg, "monster_rally", "presets", None)
    raw = raw if isinstance(raw, dict) else {}
    out = {}
    for p in RT_PRESETS:
        r = raw.get(p) if isinstance(raw.get(p), dict) else {}
        out[p] = {"mode": r.get("mode") if r.get("mode") in MR_MODES else "rally",
                  "hunts": max(0, int(float(r.get("hunts") or 0))),
                  "on": r.get("on") is not False}          # owner 29 Oct (v2): Off = its monsters stay, the preset is not used
    return out


def mr_own_order(cfg):
    """Owner 29 Oct 21:15-21:26: the "Use my own hunt order" switch. Never set -> on only for an instance that already
    saved an order in 2.5.24 (its setup stays exactly as it was); new instances start off."""
    v = rd_opt(cfg, "monster_rally", "own_order", None)
    if v is None:
        return isinstance(rd_opt(cfg, "monster_rally", "order", None), list)
    return bool(v)


def mr_order(cfg, rules=None):
    """Hunts v2 (owner 29 Oct): ONE hunt order per instance, top = hunted first; each row = monster + levels + its own
    max km (0 = any). Own order switched off -> built from the presets (place in its box, then lower preset); the
    saved list is kept (switching off never deletes it)."""
    raw = rd_opt(cfg, "monster_rally", "order", None)
    if mr_own_order(cfg):                              # own order on: its list (empty = only the presets, after it)
        out = []
        for r in (raw if isinstance(raw, list) else []):
            if isinstance(r, dict) and str(r.get("name") or "").strip():
                try:
                    out.append({"name": str(r["name"]).strip(), "min": int(r.get("min") or 1), "max": int(r.get("max") or 99),
                                "km": float(r.get("km") or 0)})
                except (TypeError, ValueError):
                    continue
        return out
    rules = rules if rules is not None else mr_rules(cfg)
    seen, rows, rank_of = set(), [], {}
    for i, r in enumerate(rules):
        rank = sum(1 for x in rules[:i] if x["preset"] == r["preset"])
        rank_of[id(r)] = rank                  # no saved order: the old priority (place in its box) stays exactly as it was
        rows.append((rank, mr_pnum(r["preset"]), i, r))
    out = []
    for _, _, _, r in sorted(rows):
        k = (r["name"].lower(), r["min"], r["max"])
        if k not in seen:
            seen.add(k)
            out.append({"name": r["name"], "min": r["min"], "max": r["max"], "km": 0, "rank": rank_of[id(r)]})
    return out


def mr_order_index(order, name, level):
    """-> (index, row) of the first hunt-order row that fits this monster, or (None, None)."""
    low = str(name or "").lower().strip()
    for i, r in enumerate(order):
        if mr_name_fits(r["name"].lower(), low) and (not level or r["min"] <= level <= r["max"]):
            return i, r
    return None, None


def mr_solo_done(serial):
    """-> {preset: solo hunts done today}."""
    row = mr_row(serial)
    return dict(row.get("solo_n") or {}) if row.get("solo_day") == _game_day() else {}


def mr_why_rank(rank):
    return "#1 in the hunt order" if rank == 0 else f"#{rank + 1} in the hunt order"


HUNT_DEC_FILE = USER / "hunt_decisions.json"
HUNT_DEC_MAX = 400                        # rows kept per instance (today only - owner 28 Oct)
_hunt_dec, _hunt_dec_lock = {}, threading.Lock()


def _hunt_dec_load():
    if not _hunt_dec and HUNT_DEC_FILE.exists():
        try:
            d = json.loads(HUNT_DEC_FILE.read_text(encoding="utf-8"))
            _hunt_dec.update(d if isinstance(d, dict) else {})
        except Exception as _e:
            quiet_err("hunt_dec_load", _e)
    if _hunt_dec.get("day") != _game_day():                # a new game day starts an empty list
        _hunt_dec.clear()
        _hunt_dec.update(day=_game_day(), rows={})


def hunt_note(serial, it, decision, kind, why, save=True, keep_done=False):
    """Decisions list (Hunts > Live): one row per coordinate - what the bot decided and why. kind: go | solo | wait | skip.
    keep_done: never write over a row where this instance already rallied / attacked the monster."""
    key = f"{it.get('x')},{it.get('y')}"
    with _hunt_dec_lock:
        _hunt_dec_load()
        rows = _hunt_dec["rows"].setdefault(serial or "default", {})
        old = rows.get(key)
        if old and old.get("decision") == decision and old.get("why") == why:
            return
        if old and keep_done and old.get("kind") in ("go", "solo"):
            return
        rows[key] = {"t": time.time(), "name": it.get("name") or "", "level": it.get("level") or 0, "km": it.get("km"),
                     "seen": float(it.get("t") or 0), "decision": decision, "kind": kind, "why": why}
        if len(rows) > HUNT_DEC_MAX:
            # skips go first, oldest first - rallies / attacks stay for the day's counts (owner 29 Oct)
            for k in sorted(rows, key=lambda k: (rows[k].get("kind") in ("go", "solo"), rows[k]["t"]))[:len(rows) - HUNT_DEC_MAX]:
                rows.pop(k, None)
        if save:
            hunt_dec_save()


def hunt_dec_save():
    try:
        save_json(HUNT_DEC_FILE, _hunt_dec)
    except Exception as _e:
        quiet_err("hunt_dec_save", _e)


def hunt_decisions(serial):
    with _hunt_dec_lock:
        _hunt_dec_load()
        rows = list((_hunt_dec["rows"].get(serial or "default") or {}).items())
    rows = [(k, r) for k, r in rows if not str(r.get("why") or "").startswith("Too old")]   # rows saved before 29 Oct
    return sorted([dict(r, key=k) for k, r in rows], key=lambda r: -r["t"])


def hunt_status(serial, state, title, sub=""):
    """Hunts status bar: state running | waiting | blocked, a title and one line of why."""
    mr_save(serial, status={"state": state, "title": title, "sub": sub, "t": time.time()})


MR_LAST_SKIPS = {}                         # serial -> {reason: count} of the last target look-up (status bar "top reason")


MR_BLOCK_FILE = USER / "monster_blocks.json"
MR_BLOCK_H = 2                            # safety cap; normally a block ends when Telegram stops listing the monster
_mr_block, _mr_block_lock = {}, threading.Lock()


def _mr_block_load():
    if not _mr_block and MR_BLOCK_FILE.exists():
        try:
            _mr_block.update(json.loads(MR_BLOCK_FILE.read_text(encoding="utf-8")) or {})
        except Exception as _e:
            quiet_err("mr_block_load", _e)
    now = time.time()
    for k in [k for k, v in _mr_block.items() if now - float(v.get("t", 0)) > MR_BLOCK_H * 3600]:
        _mr_block.pop(k, None)


def mr_block(key, by, why):
    """Owner 25 Oct: a monster an instance picked, that is being rallied (anyone in the alliance) or that is dead
    is blocked for every instance on this PC - a Telegram refresh can never bring it back."""
    if not key:
        return
    with _mr_block_lock:
        _mr_block_load()
        old = _mr_block.get(key) or {}
        if old.get("why") in ("rallied", "dead") and why == "picked":
            return                                           # never weaken a block
        _mr_block[key] = {"t": time.time(), "by": by or "", "why": why}
        try:
            save_json(MR_BLOCK_FILE, _mr_block, indent=1)
        except Exception as _e:
            quiet_err("mr_block", _e)


def mr_unblock(key):
    """Telegram stopped listing this monster (dead): forget its block - a new monster on that tile is a new one."""
    with _mr_block_lock:
        _mr_block_load()
        if _mr_block.pop(key, None) is not None:
            try:
                save_json(MR_BLOCK_FILE, _mr_block, indent=1)
            except Exception as _e:
                quiet_err("mr_unblock", _e)


def mr_block_why(key):
    with _mr_block_lock:
        _mr_block_load()
        return (_mr_block.get(key) or {}).get("why")


def mr_blocked(key, me=None):
    """True = no instance may pick it. 'picked' only blocks the OTHER instances (the picker keeps it while it waits)."""
    with _mr_block_lock:
        _mr_block_load()
        b = _mr_block.get(key)
    if not b:
        return False
    return b.get("why") != "picked" or me is None or b.get("by") != me


_mr_card_seen = {}                        # (monster, end time // 30) -> time: each rally card is read only once


def mr_card_block(screen, hit, serial, mon, left):
    """Owner 25 Oct: a rally card on the Alliance War list shows the monster's X : Y under its name (right side) -
    block that monster for Monster rallies on this PC. Read once per rally (the joiner scans the list often)."""
    try:
        now = time.time()
        ck = (mon, round((now + float(left)) / 30))
        if ck in _mr_card_seen:
            return
        _mr_card_seen[ck] = now
        if len(_mr_card_seen) > 400:
            for k in [k for k, t in _mr_card_seen.items() if now - t > 3600]:
                _mr_card_seen.pop(k, None)
        x0, y0 = int(hit[0]) - 200, int(hit[1]) - 105
        txt = " ".join(t for t, _ in rd_lines(screen, (max(0, x0), max(0, y0), 290, 50)))
        m = re.search(r"(\d{3,4})\s*[:;.]\s*(\d{3,4})", txt)
        if m:
            mr_block(f"{int(m.group(1))},{int(m.group(2))}", serial, "rallied")
        else:
            _mr_card_seen.pop(ck, None)                      # not read: try again on the next scan
    except Exception as _e:
        quiet_err("mr_card_block", _e)


def mr_preset_loaded(shot):
    """Alliance War troop page: a general is set (no 'Select a Main General' card). An empty preset = its general is out."""
    return not rd_seen(shot, ["Select a Main General"], region=(0, 450, 540, 170))


MR_PANEL_TAP = (50, 147)                  # world map: folded "> March" pill opens it; tapping the open "v March n/6" bar folds it (owner 25 Oct)


def mr_to_map(dev, cfg, stop, tries=3):
    """Back from the troop / monster page to the world map - never presses Back on the map itself (exit box)."""
    for _ in range(tries):
        shot = dev.screenshot()
        if view_of(shot, cfg) in ("landscape", "world"):
            return True
        dev.back()
        _nap(stop, 1.0, 1.3)
    return view_of(dev.screenshot(), cfg) in ("landscape", "world")


def mr_fold_panel(dev, stop, log, shot=None):
    """World map: the March panel open ('March n/6' bar) -> fold it; already folded ('> March') -> nothing to do."""
    shot = dev.screenshot() if shot is None else shot
    if not rt_marches(shot):
        return False
    for spot in (MR_PANEL_TAP, (150, 147)):
        dev.tap(*spot)
        _nap(stop, 0.8, 1.0)
        if not rt_marches(dev.screenshot()):
            return True
    rd_snap(dev.screenshot(), "mrally_march_panel")
    log("[i]  Monster rally: the March panel did not fold - see debug/duty_mrally_march_panel.png")
    return False


def mr_return_secs(dev, cfg, stop, log):
    """Open the March panel, read the soonest return countdown, fold it again. -> seconds or None."""
    shot = dev.screenshot()
    mk = rt_marches(shot)
    opened = False
    if not mk:
        dev.tap(*MR_PANEL_TAP)
        _nap(stop, 1.0, 1.2)
        shot = dev.screenshot()
        mk = rt_marches(shot)
        opened = True
    rd_snap(shot, "mrally_march_panel")
    if opened or mk:
        for spot in (MR_PANEL_TAP, (150, 147)):              # fold it again: tap the "March n/6" bar (owner: keep it minimised)
            if not rt_marches(dev.screenshot()):
                break
            dev.tap(*spot)
            _nap(stop, 0.8, 1.0)
        if rt_marches(dev.screenshot()):
            log("[i]  Monster rally: the March panel did not fold - see debug/duty_mrally_march_panel.png")
    return mk[2] if mk else None


def mr_march_look(dev, cfg, stop, log, shot=None):
    """Owner 29 Oct 18:29-18:39: before every hunt one quick look at the March panel (open it if folded, read
    "March n/6" + the soonest return, fold it again; ~1-2 s). -> (busy, total, soonest_s) or None.
    Never blocks the hunt: not readable 3 times in a row -> no more looks for 30 min (the bot's own timers decide)."""
    now = time.time()
    if now < float(getattr(dev, "mr_look_off_until", 0) or 0):
        return None
    try:
        shot = shot if shot is not None else dev.screenshot()
        mk = rt_marches(shot)
        opened = False
        if not mk:
            dev.tap(*MR_PANEL_TAP)
            _nap(stop, 0.7, 0.9)
            shot = dev.screenshot()
            mk = rt_marches(shot)
            opened = True
        if opened:                                         # fold it again (owner: keep it minimised)
            for spot in (MR_PANEL_TAP, (150, 147)):
                if not rt_marches(dev.screenshot()):
                    break
                dev.tap(*spot)
                _nap(stop, 0.5, 0.7)
        if mk:
            dev.mr_look_fails = 0
            return mk
        dev.mr_look_fails = int(getattr(dev, "mr_look_fails", 0) or 0) + 1
        if dev.mr_look_fails >= 3:
            dev.mr_look_fails = 0
            dev.mr_look_off_until = now + 1800
            log("[i]  Monster hunts: the March panel could not be read 3 times - using the bot's own march timers for 30 min")
    except Exception as _e:
        quiet_err("mr_march_look", _e)
    return None


MR_PAN_KINDS = ("ground", "ranged", "mounted")


def mr_pan_kind(low):
    """'ground pan' / 'pan (ranged troop)' -> ('pan', 'ranged'); plain 'pan' -> ('pan', None); other names -> (None, None)."""
    words = re.findall(r"[a-z]+", low)
    if "pan" not in words:
        return None, None
    return "pan", next((k for k in MR_PAN_KINDS if k in words), None)


def mr_name_fits(rn, low):
    """owner 29 Oct (v2): presets may hold Ground / Ranged / Mounted Pan. A Telegram 'Pan' without a kind fits any of
    them (the preset order decides); a named kind only fits that kind or a plain 'Pan' row."""
    a, b = mr_pan_kind(rn), mr_pan_kind(low)
    if a[0] and b[0]:
        return not a[1] or not b[1] or a[1] == b[1]
    return rn in low or low in rn


def mr_rule_for(rules, name, level):
    """-> (index, rule) of the first row that fits this monster, or (None, None)."""
    low = str(name or "").lower().strip()
    if not low:
        return None, None
    for i, r in enumerate(rules):
        rn = r["name"].lower()
        if mr_name_fits(rn, low) and (not level or r["min"] <= level <= r["max"]):
            return i, r
    return None, None


def mr_targets(cfg, tried, serial=None):
    """Telegram coordinates of monsters that sit on a preset (Hunts tab), best first (top of a preset, then nearest).
    Every coordinate gets a line in the Decisions list (why it is hunted or skipped). -> [{name, level, x, y, km, t, rule, rank, mode}]"""
    modes = mr_presets(cfg)
    rules = [r for r in mr_rules(cfg) if modes[r["preset"]]["on"]]     # a switched-off preset hunts nothing
    order = mr_order(cfg, mr_rules(cfg))
    # v2: when two presets can kill a monster, the one that can take FEWER other hunt-order rows goes - the strong one
    # stays free for the rest (owner 29 Oct Pan 7 example)
    cover = {}
    for oi, o in enumerate(order):
        for r in rules:
            if mr_name_fits(r["name"].lower(), o["name"].lower()) and r["min"] <= o["max"] and o["min"] <= r["max"]:
                cover.setdefault(r["preset"], set()).add(oi)
    done = mr_solo_done(serial)
    age_min = float(rd_opt(cfg, "monster_rally", "max_age", 10) or 10)
    _feed_cache_min[0] = age_min
    age = age_min * 60
    now = time.time()
    feed, _ = feed_get(_feed_keep[0] if _feed_keep[0] is not None else int(cfg.get("tg_keep_min", 60) or 0))
    try:
        upd = json.loads(BOSS_FILE.read_text(encoding="utf-8")).get("updated", 0) if BOSS_FILE.exists() else 0
    except Exception:
        upd = 0
    pool = list(feed) + [dict(b, t=upd) for b in get_bosses()]
    max_km = float(rd_opt(cfg, "monster_rally", "max_km", 0) or 0)
    out, seen, skips = [], set(), {}

    def skip(it, why, short, keep=False):
        skips[short] = skips.get(short, 0) + 1
        if serial is not None:
            hunt_note(serial, it, "Skipped", "skip", why, save=False, keep_done=keep)

    for it in pool:
        key = f"{it.get('x')},{it.get('y')}"
        if key in seen:
            continue
        seen.add(key)
        if str(it.get("name") or "").lower().strip() in NEVER_JOIN:      # world bosses: nobody can hunt them (not listed)
            continue
        if now - float(tried.get(key, 0)) < MR_FORGET_MIN * 60:          # this instance just had it: its row stays as it is
            continue
        if mr_blocked(key, serial):
            w = mr_block_why(key)
            skip(it, {"rallied": "Taken by another rally", "dead": "Gone (not on the map any more)"}.get(w, "Picked by another instance"),
                 "taken", keep=True)
            continue
        if now - float(it.get("t") or 0) > age:     # owner 29 Oct: the cache REFRESHES - older coordinates are simply
            continue                                   # dropped (not listed as "too old"); the next Telegram list shows
        if max_km and it.get("km") is not None and float(it["km"]) > max_km:    # owner 28 Oct: e.g. only 700 km or closer
            skip(it, f"Too far · max distance is {max_km:g} km", "too far")
            continue
        low = str(it.get("name") or "").lower().strip()
        fits = [(i, r) for i, r in enumerate(rules) if mr_rule_for([r], it.get("name"), it.get("level") or 0)[1]]
        if not fits:
            offp = sorted({mr_pnum(r["preset"]) for r in mr_rules(cfg) if not modes[r["preset"]]["on"]
                           and mr_rule_for([r], it.get("name"), it.get("level") or 0)[1]})
            if offp:
                skip(it, "Preset " + ", ".join(map(str, offp)) + (" is" if len(offp) == 1 else " are") + " switched off", "preset off")
            else:
                skip(it, "Not in any preset", "not in a preset")
            continue
        oi, orow = mr_order_index(order, it.get("name"), it.get("level") or 0)
        if oi is None:                                   # owner 29 Oct 21:23: own order on -> a monster only in a preset
            oi, orow = len(order), {"km": 0, "after": True}     # is hunted AFTER every row of the order (marches never idle)
        if orow["km"] and it.get("km") is not None and float(it["km"]) > orow["km"]:
            skip(it, f"Too far · its rule is up to {orow['km']:g} km", "too far")
            continue
        oi = orow.get("rank", oi)
        pairs, why_not, seen_p = [], "", set()
        for i, r in fits:                                # owner 29 Oct 13:31: EVERY preset whose box holds it may take it
            m, p = modes[r["preset"]]["mode"], r["preset"]
            if p in seen_p:
                continue
            if m == "solo" and low in RALLY_ONLY:
                why_not = why_not or f"Rally only · Preset {mr_pnum(p)} is Solo"
                continue
            if m == "rally" and low in SOLO_ONLY:
                why_not = why_not or f"Solo only · Preset {mr_pnum(p)} is Rally"
                continue
            lim = modes[p]["hunts"]
            if m == "solo" and lim and int(done.get(p, 0)) >= lim:
                why_not = why_not or f"Preset {mr_pnum(p)} did its {lim} hunts today"
                continue
            seen_p.add(p)
            pairs.append({"preset": p, "mode": m, "rule": r,
                          **({"rank": sum(1 for x in rules[:i] if x["preset"] == p), "top": 0} if "rank" in orow    # no own order: old rule
                             else {"rank": oi + sum(1 for x in rules[:i] if x["preset"] == p), "top": 0, "after": True} if orow.get("after")   # after the order, box place
                             else {"rank": oi, "top": len(cover.get(p, set()) - {oi})})})   # v2: rank = hunt-order place
        if not pairs:
            skip(it, why_not, "wrong mode" if why_not.startswith(("Rally only", "Solo only")) else "at the hunt limit")
            continue
        pairs.sort(key=mr_pair_order)                    # owner 29 Oct: higher box place wins, tie -> lower preset number
        b = pairs[0]
        out.append(dict(it, rule=b["rule"], rank=b["rank"], mode=b["mode"], pairs=pairs))
    if serial is not None:
        MR_LAST_SKIPS[serial] = skips
        with _hunt_dec_lock:
            hunt_dec_save()
    km = lambda it: it.get("km") if it.get("km") is not None else 1e9
    # v2: the hunt-order place first; inside one row (e.g. Pumpkin all levels) the HIGHER level goes first, then the closest
    out.sort(key=lambda it: (it["rank"], -int(it.get("level") or 0), km(it)))
    return out


def mr_march_line(img, center=MR_CENTER):
    """True when a march line (white = another player, green = an alliance march) ends at the monster in the middle.
    First guess, not checked on a real line yet: long straight bright strokes whose line passes the centre."""
    try:
        h, w = img.shape[:2]
        x0, y0, x1, y1 = 0, 200, w, 800                     # below the march panel, above the bottom buttons
        roi = img[y0:y1, x0:x1]
        hsv = cv2.cvtColor(roi, cv2.COLOR_BGR2HSV)
        white = cv2.inRange(hsv, (0, 0, 215), (180, 45, 255))
        green = cv2.inRange(hsv, (45, 120, 120), (80, 255, 255))
        cx, cy = center[0] - x0, center[1] - y0
        for name, mask in (("white", white), ("green", green)):
            m = mask.copy()
            cv2.circle(m, (cx, cy), 45, 0, -1)              # the monster itself (Ymir is white / ice blue) never counts
            segs = cv2.HoughLinesP(m, 1, np.pi / 180, 40, minLineLength=70, maxLineGap=12)
            for s in (segs.reshape(-1, 4) if segs is not None else []):    # (N,1,4) or (N,4) depending on the OpenCV build
                ax, ay, bx, by = [int(v) for v in s]
                dx, dy = bx - ax, by - ay
                ln = (dx * dx + dy * dy) ** 0.5
                if ln < 70 or abs(dy) < 6:                  # text and flat map edges are level - a march line to the middle is not
                    continue
                dist = abs(dy * (cx - ax) - dx * (cy - ay)) / ln
                near_end = min(((ax - cx) ** 2 + (ay - cy) ** 2) ** 0.5, ((bx - cx) ** 2 + (by - cy) ** 2) ** 0.5)
                if dist < 22 and near_end < 150:
                    return name
    except Exception:
        return None
    return None


def mr_box_number(shot, box):
    """One number box of the coordinate search (digits only, enlarged) -> int or None. The whole-line read missed
    'Y: 622' on Kiravik (23 Oct)."""
    try:
        x, y, w, h = box
        g = cv2.resize(cv2.cvtColor(shot[y:y + h, x:x + w], cv2.COLOR_BGR2GRAY), None, fx=3, fy=3)
        t = pytesseract.image_to_string(g, config="--psm 7 -c tessedit_char_whitelist=0123456789").strip()
        return int(t) if t.isdigit() else None
    except Exception:
        return None


def mr_search(dev, stop, x, y):
    """Map shown: open the coordinate search, type X and Y, check them, Go. -> True when the map flew there."""
    if cancel_quit_dialog(dev, dev.screenshot(), lambda *_: None):   # an 'exit the game?' box left open would eat the tap
        _nap(stop, 0.8, 1.2)
    dev.tap(300, 845)                                       # the X: Y: box at the bottom of the map
    _nap(stop, 1.4, 1.8)
    shot = dev.screenshot()
    if not rd_seen(shot, ["Search", "Server"], region=(0, 280, 540, 280)):
        rd_snap(shot, "mrally_search")
        return False
    for spot, val in (((206, 535), x), ((428, 545), y)):
        dev.tap(*spot)
        _nap(stop, 1.0, 1.4)
        rd_clear_field(dev, stop, 6)
        dev.text(str(val))
        _nap(stop, 0.5, 0.8)
        rd_keyboard_ok(dev, stop)
    shot = dev.screenshot()
    got = [mr_box_number(shot, (110, 500, 150, 45)), mr_box_number(shot, (315, 500, 150, 45))]   # the X and Y boxes
    if None in got:                                          # digits-only read missed: the old whole-line read
        got = rd_numbers(" ".join(t for t, _ in rd_lines(shot, (30, 505, 480, 70))))
    if x not in got and y not in got:                       # neither number read back: the typing went wrong
        rd_snap(shot, "mrally_xy")
        dev.back()
        _nap(stop, 0.8, 1.1)
        raise RuntimeError(f"the search box does not show X {x} Y {y} (read {got[:4]})")
    # one number misread (Y 444 read as 40404): go anyway - the monster check on the tile catches a wrong spot
    dev.tap(333, 610)                                       # owner 29 Oct 03:39: Go at once - reading the word "Go" first
    _nap(stop, 1.6, 1.9)                                     # cost seconds on every monster; the button never moves
    return True


MR_EMPTY_RING = [False]                    # set by mr_attack_spot: the last ring was the empty-land one (Occupy / Teleport)


def mr_attack_spot(shot):
    """The monster's ring menu: -> (x, y) of its 'Attack' label, or None. Plain OCR only reads 'Att' on the ring's
    dark label (Kiravik 23 Oct) - read the ring area enlarged and bright. Empty land (Occupy / Teleport ring) sets
    MR_EMPTY_RING[0] so the caller can skip the monster at once."""
    MR_EMPTY_RING[0] = False
    try:
        for t, ws in ocr_lines(shot[250:700, 0:540], 2.5, bright=True):
            for w in ws:
                word = str(w[0]).lower().strip("|.,:;!() ")
                if word in ("attack", "attac", "atack"):
                    return int(w[1]), int(w[2]) + 250
                if word in ("occupy", "teleport"):
                    MR_EMPTY_RING[0] = True
    except Exception as _e:
        quiet_err("mr_attack_spot", _e)
    if MR_EMPTY_RING[0]:
        return None
    p = rd_find(shot, ["Attack"], region=(0, 250, 540, 450), cutoff=0.75)
    return (p[0], p[1]) if p else None


def mr_still_there(dev, stop):
    """While waiting for a march: tap the monster in the middle; True when its ring shows Attack (the ring is closed again)."""
    for dx, dy in MR_NEAR[:3]:
        if stop.is_set():
            return True
        dev.tap(MR_CENTER[0] + dx, MR_CENTER[1] + dy)
        _nap(stop, 1.2, 1.5)
        hit = mr_attack_spot(dev.screenshot())
        dev.tap(*MR_EMPTY)                                  # close the ring on empty map
        _nap(stop, 0.7, 0.9)
        if hit:
            return True
        if MR_EMPTY_RING[0]:                                # empty land on the tile: the monster is dead
            return False
    return False


def mr_open_monster(dev, stop, want, level=None):
    """Tap the monster in the middle; its ring menu must have Attack, its page must show the wanted name.
    -> ('ok', page_shot) | ('gone', None) | ('other', name_read)"""
    for dx, dy in MR_NEAR:
        if stop.is_set():
            return "gone", None
        dev.tap(MR_CENTER[0] + dx, MR_CENTER[1] + dy)
        _nap(stop, 1.3, 1.7)
        shot = dev.screenshot()
        rd_snap(shot, f"mrally_ring{MR_NEAR.index((dx, dy))}")   # what the tap opened (test pictures)
        p = mr_attack_spot(shot)
        if not p:
            dev.tap(*MR_EMPTY)                              # no Attack button: close whatever ring opened, try the second spot
            _nap(stop, 0.8, 1.0)
            continue
        dev.tap(p[0], max(100, p[1] - 30))
        _nap(stop, 1.8, 2.3)
        page = dev.screenshot()
        rd_snap(page, "mrally_page")
        def _is_mon_page(img):                               # owner 29 Oct 03:35: a Lv6 Pumpkin page was called "not a monster
            if rd_seen(img, ["Alliance War", "Winning Odds"], region=(0, 650, 540, 220)):    # page" - plain reading missed the gold
                return True                                  # buttons; read them enlarged as light text too
            try:
                txt = " ".join(t for t, _ in ocr_lines(img[650:870, 0:540], 2.5, bright=True)).lower()
            except Exception:
                return False
            return "alliance war" in txt or "winning" in txt or ("attack" in txt and "alliance" in txt)
        if not _is_mon_page(page):
            dev.back()                                      # something with Attack but no monster page: not ours - skip at once (no more taps)
            _nap(stop, 0.8, 1.1)
            return "other", "not a monster page"
        head = " ".join(t for t, _ in ocr_lines(page[120:300, 0:540], 2.5, bright=True))   # plain OCR garbled the name
        import difflib
        toks = re.findall(r"[a-z]+", head.lower())
        words = [w for w in strip_troop_suffix(want).lower().split() if len(w) > 2]   # 'Pan (Ranged Troop)' -> check 'pan
        missing = [w for w in words if not any(w == t or difflib.SequenceMatcher(None, w, t).ratio() >= (0.75 if len(w) <= 5 else 0.8) for t in toks)]
        lv = re.search(r"(?:lv|level)\.?\s*(\d{1,2})\b", head.lower())
        wrong_lv = bool(level and lv and int(lv.group(1)) != int(level))
        if missing or wrong_lv:                               # every word of the name (Epic Cerberus is not Legendary Cerberus) and the level must fit
            dev.back()
            _nap(stop, 0.8, 1.1)
            return "other", head[:40]
        return "ok", page
    return "gone", None


# ---- Monster hunts as a background service (owner 29 Oct, root_cause_plan P1 + hunts_service_design_29oct.md) ----
HUNT_TICK_S = 30               # how often a wait checks for a handoff (due duty, Auto-Join, heal, check-in)
HUNT_ALIVE_S = 60              # one "still waiting" log line a minute - only while the map was seen recently
HUNT_MAP_FRESH_S = 90
HUNT_ERR_MAX = 5               # errors in a row -> hunts pause 5 min (still not a duty failure)


def hunt_handoff_reason(dev, cfg, serial, t_start):
    """-> why the hunts should hand over now (a normal end, never a failure), or None."""
    if time.time() - t_start > MR_RUN_MIN * 60:
        return "check-in"
    if getattr(dev, "aj_next", 0) and time.time() >= dev.aj_next:
        return "Auto-Join renewal"
    heal_min = float(rd_opt(cfg, "monster_rally", "heal_min", 0) or 0)
    if heal_min:
        h = float(mr_row(serial).get("heal_at") or 0)
        if h and time.time() - h >= heal_min * 60:
            return "troop healing"
    try:
        other = [t for t in city_tasks_due(cfg, getattr(_TL, "city_last", None) or {}, serial)
                 if t.get("name") != "duty:monster_rally"]
    except Exception as _e:
        quiet_err("hunt_handoff_reason", _e)
        other = []
    if other:
        nm = str(other[0].get("name") or "").split(":", 1)[-1]
        return (DUTY_BY_ID.get(nm) or {}).get("title") or nm
    return None


def hunt_tick(dev, cfg, log, stop, serial, what=""):
    """Called inside every hunt wait. Writes one alive line a minute (only when a look at the screen shows the map,
    so a dead game never looks alive to the watchdog) and checks for a handoff every HUNT_TICK_S.
    -> handoff reason (also kept in _TL.hunt_handoff) or None."""
    now = time.time()
    if what and now - getattr(_TL, "hunt_alive", 0) >= HUNT_ALIVE_S:
        if now - getattr(_TL, "hunt_map_ok", 0) > HUNT_MAP_FRESH_S:
            try:
                if view_of(dev.screenshot(), cfg) in ("landscape", "world"):
                    _TL.hunt_map_ok = time.time()
            except Exception as _e:
                quiet_err("hunt_tick", _e)
        if time.time() - getattr(_TL, "hunt_map_ok", 0) <= HUNT_MAP_FRESH_S:
            _TL.hunt_alive = now
            log(f"[*]  Monster hunts: {what}")
    if now - getattr(_TL, "hunt_chk", 0) >= HUNT_TICK_S:
        _TL.hunt_chk = now
        why = hunt_handoff_reason(dev, cfg, serial, getattr(_TL, "hunt_t0", now))
        if why:
            _TL.hunt_handoff = why
            return why
    return None


def hunt_nap(dev, cfg, log, stop, serial, secs, what=""):
    """A hunt wait in small steps with hunt_tick between them. -> handoff reason or None (waited the full time)."""
    end = time.time() + max(0.0, secs)
    while not stop.is_set():
        why = hunt_tick(dev, cfg, log, stop, serial, what)
        if why:
            return why
        left = end - time.time()
        if left <= 0:
            return None
        _nap(stop, min(5.0, left), min(5.5, left + 0.5))
    return "stop"


def hunt_error(dev, cfg, log, stop, serial, err):
    """An error inside a hunt pass that is NOT lost game control: log, evidence (best effort), back to the map,
    count it. -> errors in a row."""
    log(f"[!]  Monster hunts: {err} - back to the map, trying again in 1 min")
    failure_evidence(dev, "monster_rally", str(err)[:200])
    row = mr_row(serial)
    day = _game_day()
    n_day = int(row.get("err_n", 0)) + 1 if row.get("err_day") == day else 1
    streak = int(row.get("err_streak", 0)) + 1
    mr_save(serial, err_day=day, err_n=n_day, err_streak=streak)
    try:
        mr_to_map(dev, cfg, stop)
    except InstanceStopped:
        raise
    except Exception as _e:
        quiet_err("hunt_error", _e)
    return streak



def run_monster_rally(dev, cfg, log, stop):
    """Monster hunts = a background service (owner 29 Oct). No wall clock: it runs until Stop, a handoff (another duty
    due, Auto-Join renewal, heal, the 30-min check-in) or nothing is left to hunt. A handoff is a NORMAL end (the duty
    is recorded OK and comes straight back after the other task). Errors inside a pass never fail the duty: evidence,
    back to the map, retry in 1 min. Only lost game control (Stop, the watchdog's TASK_ABORT) leaves by raising.
    The universal pop-up closer is held off meanwhile: it closed the rally time window by its X (Kiravik 23 Oct)."""
    was = getattr(dev, "_guard_busy", False)
    dev._guard_busy = True
    serial = getattr(dev, "serial", "")
    t_start = time.time()
    _TL.duty_deadline = None                                 # no 40-min kill any more (root_cause_plan P1)
    _TL.hunt_t0, _TL.hunt_chk, _TL.hunt_handoff = t_start, t_start, None
    try:
        while True:
            _TL.mr_go_on = _TL.mr_idle = False
            _TL.hunt_handoff = None
            try:
                _run_monster_rally(dev, cfg, log, stop)
                if mr_row(serial).get("err_streak"):
                    mr_save(serial, err_streak=0)
            except InstanceStopped:
                raise
            except Exception as e:
                if stop.is_set() or serial in TASK_ABORT:          # lost control: the watchdog path, unchanged
                    raise
                streak = hunt_error(dev, cfg, log, stop, serial, e)
                pause = 5 if streak >= HUNT_ERR_MAX else 1
                mr_save(serial, next_at=time.time() + pause * 60)
                n_day = mr_row(serial).get("err_n", 0)
                hunt_status(serial, "waiting", "Monster hunts: trying again soon",
                            f"Something went wrong ({str(e)[:60]}) · again in {pause} min · {n_day} hunt error(s) today")
                return
            if stop.is_set():
                return
            why = getattr(_TL, "hunt_handoff", None) or (hunt_handoff_reason(dev, cfg, serial, t_start) if _TL.mr_go_on else None)
            if not why and _TL.mr_go_on and _TL.mr_idle:     # nothing to hunt right now: wait on the map for new coordinates
                why = hunt_nap(dev, cfg, log, stop, serial, random.uniform(20, 25), "waiting for new monster coordinates")
                if stop.is_set():
                    return
            if why == "troop healing":                       # the next pass queues the heal duty and hands over itself
                continue
            if why:
                mr_save(serial, next_at=time.time())                 # straight back after the other task
                if why == "check-in":
                    log("[*]  Monster hunts: 30-min check-in - back right after")
                    return
                log(f"[*]  Monster hunts: {why} is due - doing it, the hunts go on after")
                hunt_status(serial, "running", f"Doing {why}" if why != "Auto-Join renewal" else "Renewing Auto-Join",
                            "Back to Monster hunts after")
                return
            if not _TL.mr_go_on:
                return
    finally:
        dev._guard_busy = was


# ---- Hunts step 6: (target, preset) pairs (owner 29 Oct 13:31, claude/hunts_preset_selection_29oct.md) ----
HUNT_OUT_DEFAULT_S = 30        # owner 29 Oct 23:57: a preset seen empty is tried again after 30 s (unless the March panel says when it is back)
HUNT_WAIT_CAP_S = 30           # owner 29 Oct 23:57: waits for presets / marches are at most 30 s, then it simply tries again
HUNT_ROUNDS = 12               # targets tried in one pass


def mr_pair_order(e, last=None):
    """Hunts v2 (owner 29 Oct): the preset that can take fewer other hunt-order rows goes first (the strong one stays
    free); a tie -> (owner 29 Oct 23:40) the preset used longest ago (its troops are most likely home), then the lower
    preset number. last = {preset: time it last marched}."""
    return (int(e.get("rank") or 0), int(e.get("top") or 0), float((last or {}).get(e.get("preset")) or 0),
            mr_pnum(e.get("preset")))


def mr_last_used(serial):
    """{preset: time it last marched} for this instance (hunts)."""
    try:
        return {p: float(t or 0) for p, t in (mr_row(serial).get("busy") or {}).items()}
    except Exception:
        return {}


MR_MARCH_BACK_MIN = 1          # extra minutes after the rally time before a preset counts as back (the march home)
MR_STILL_OUT_S = 30            # a preset found still out on the troop page is not tried again for this long
MR_BACK_MAX_MIN = 12           # learned march-home time is never counted longer than this (minutes after the rally time)


def mr_preset_until(cfg, serial, preset, now=None, row=None, seen_only=False):
    """When this preset is expected back; 0 = free now, or not known to be out (the troop page proves it).
    From its last march (start + its rally time, as before) and 'pout' (seen empty on the troop page).
    seen_only (owner 29 Oct 23:57): only what the game showed (empty on the troop page / March panel) - a guessed
    return time never stops the bot from trying; it tries, and a preset still out is tried again 30 s later."""
    now = now or time.time()
    row = row if row is not None else mr_row(serial)
    until = 0.0
    try:
        b = float((row.get("busy") or {}).get(preset) or 0)
        if b and now - b < 1800:
            rt = next((int(r["time"]) for r in mr_rules(cfg) if r["preset"] == preset), 5)
            back = float(row.get("back_min") or MR_MARCH_BACK_MIN)   # learned per instance: march there + fight + home
            # the rally time itself is certain (the troops wait in the rally); the march home is a guess, so with
            # seen_only the bot starts trying as soon as the rally time is over
            until = b + (rt + (0 if seen_only else back)) * 60   # owner 29 Oct 18:22: the troops still march home after the rally
        until = max(until, float((row.get("pout") or {}).get(preset) or 0))
    except Exception as _e:
        quiet_err("mr_preset_until", _e)
    return until if until > now else 0


def mr_free_presets(cfg, serial, presets, now=None):
    """-> the presets of this list that are free now ('slots_until' = the March panel showed no free march)."""
    now = now or time.time()
    row = mr_row(serial)
    if float(row.get("slots_until") or 0) > now:
        return set()
    return {p for p in presets if not mr_preset_until(cfg, serial, p, now, row, seen_only=True)}


def mr_plan(targets, free, hold=None, skip=(), last=None):
    """Every target with at least one FREE preset, best first, each with its best free preset:
    the held target first, then the place in that preset's box, higher level, closer, lower preset number.
    -> [(target, pair)]"""
    out = []
    for t in targets:
        key = f"{t.get('x')},{t.get('y')}"
        if key in skip:
            continue
        ps = [e for e in (t.get("pairs") or []) if e["preset"] in free]
        if not ps:
            continue
        e = min(ps, key=lambda x: mr_pair_order(x, last))
        km = t.get("km") if t.get("km") is not None else 1e9
        out.append(((0 if hold and key == hold else 1, int(e.get("rank") or 0), -int(t.get("level") or 0), km,
                     float((last or {}).get(e["preset"]) or 0), mr_pnum(e["preset"])), t, e))
    out.sort(key=lambda x: x[0])
    return [(t, e) for _, t, e in out]


def mr_next_back(cfg, serial, targets, now=None):
    """The earliest time a preset used by these targets (or a march) is expected back; 0 = not known."""
    now = now or time.time()
    row = mr_row(serial)
    ts = [mr_preset_until(cfg, serial, p, now, row, seen_only=True) for p in {e["preset"] for t in targets for e in (t.get("pairs") or [])}]
    su = float(row.get("slots_until") or 0)
    ts = [x for x in ts if x] + ([su] if su > now else [])
    return min(ts) if ts else 0


def _mr_label(tgt):
    lv = f"Lv{tgt['level']} " if tgt.get("level") else ""
    short = f"{lv}{tgt.get('name') or 'monster'}"
    return f"{short} ({tgt['x']},{tgt['y']})", short


def _run_monster_rally(dev, cfg, log, stop):
    serial = getattr(dev, "serial", "")
    row = mr_row(serial)
    now = time.time()
    tried = {k: v for k, v in (row.get("tried") or {}).items() if now - float(v) < MR_FORGET_MIN * 60}
    mr_save(serial, tried=tried, next_at=now + MR_POLL_MIN * 60)

    def later(minutes, why):
        mr_save(serial, tried=tried, next_at=time.time() + minutes * 60)
        log(f"[*]  Monster rally: {why} - again at {time.strftime('%H:%M', time.localtime(time.time() + minutes * 60))}")

    heal_min = float(rd_opt(cfg, "monster_rally", "heal_min", 0) or 0)
    if heal_min:                                             # Auto heal every N min: the heal duty runs in between, then Hunts go on
        if not row.get("heal_at"):
            mr_save(serial, heal_at=now)
        elif now - float(row["heal_at"]) >= heal_min * 60 and "duty:troop_healing" not in run_now_list(serial):
            run_now_set(serial, run_now_list(serial) + ["duty:troop_healing"])
            mr_save(serial, heal_at=now)
            log("[*]  Monster hunts: time to heal the troops - healing first, the hunts go on after")
            hunt_status(serial, "running", "Healing troops", "Auto heal · back to Monster hunts after")
            _TL.mr_go_on = True
            return
    targets = mr_targets(cfg, tried, serial)
    hold = row.get("hold")                                  # a monster reached but not started (preset out / window): first
    if hold:
        targets.sort(key=lambda t: f"{t.get('x')},{t.get('y')}" != hold)
        if not any(f"{t.get('x')},{t.get('y')}" == hold for t in targets):
            mr_save(serial, hold=None)                       # gone from the list (dead / too old)
    if not targets:
        _TL.mr_go_on = _TL.mr_idle = True
        sk = MR_LAST_SKIPS.get(serial) or {}
        top = max(sk, key=sk.get) if sk else ""
        hunt_status(serial, "waiting", "Waiting for monsters",
                    "No matching monster in Telegram" + (f" · top reason: {sk[top]} {top}" if top else "") + " · checks again in 1 min")
        return later(MR_POLL_MIN, "no Telegram coordinate matches the monster list")
    keep_free = 0                                            # owner 28 Oct: "Marches kept free" is not needed
    max_wait = float(rd_opt(cfg, "monster_rally", "max_wait", 0) or 0) * 60          # 0 = hold until it is hunted / gone
    refill = rd_opt(cfg, "monster_rally", "refill", True) in (True, "true", "1", 1)
    skip_lines = rd_opt(cfg, "monster_rally", "skip_busy", False) in (True, "true", "1", 1)
    if not ensure_view(dev, cfg, stop, log, "world"):       # the world map ("landscape" here = the rally list view)
        return later(MR_POLL_MIN, "the map did not open")
    shot = _wait_view(dev, cfg, stop, "landscape", 30)
    if shot is None:
        return later(MR_POLL_MIN, "the map did not open")
    _TL.hunt_map_ok = time.time()
    # Owner 29 Oct 13:31 (Hunts step 6, claude/hunts_preset_selection_29oct.md): (target, preset) PAIRS. Any free preset
    # that has a target goes - rally or solo, any preset whose box holds the monster. A target whose presets are all out
    # is HELD (not flown to, not forgotten) and goes first as soon as one of them is back. No parking on a monster while
    # another preset could work; every march slot is used (keep_free = 0, Auto-Join reserves nothing).
    mk = None if getattr(dev, "mr_no_march_count", False) else rt_marches(shot)
    if mk and mk[1] - mk[0] <= keep_free:                   # every march is out: no flight this pass
        mr_save(serial, slots_until=time.time() + min(HUNT_WAIT_CAP_S, max(10, (mk[2] or 60) + 2)))
    elif mk:
        mr_save(serial, slots_until=0)
    started, done_keys = 0, set()
    for _round in range(HUNT_ROUNDS):
        if stop.is_set():
            return
        row = mr_row(serial)
        hold = row.get("hold")
        now = time.time()
        live = [t for t in targets if f"{t['x']},{t['y']}" not in done_keys and not mr_blocked(f"{t['x']},{t['y']}", serial)]
        if hold and not any(f"{t['x']},{t['y']}" == hold for t in live):
            hold = None                                      # rallied / dead / taken / gone from the cache: let go
            mr_save(serial, hold=None)
        allp = {e["preset"] for t in live for e in (t.get("pairs") or [])}
        plan = mr_plan(live, mr_free_presets(cfg, serial, allp, now), hold, last=mr_last_used(serial))
        if not plan:
            break
        tgt, pair = plan[0]
        res = mr_hunt_one(dev, cfg, log, stop, serial, tgt, pair, tried, later, keep_free, refill, skip_lines)
        if res in ("stop", "later"):
            return
        if res in ("started", "gone", "other", "taken"):
            done_keys.add(f"{tgt['x']},{tgt['y']}")
        if res == "started":
            started += 1
        # "busy": its preset / the marches are marked out; the next round plans again (other presets, other targets)
    if stop.is_set():
        return
    live = [t for t in targets if f"{t['x']},{t['y']}" not in done_keys and not mr_blocked(f"{t['x']},{t['y']}", serial)]
    if live:                                                 # targets left, but no free preset for any of them right now
        row = mr_row(serial)
        hold = row.get("hold") if any(f"{t['x']},{t['y']}" == row.get("hold") for t in live) else None
        if not hold:
            hold = f"{live[0]['x']},{live[0]['y']}"          # the best one waits first in line (never flown to while out)
            mr_save(serial, hold=hold)
            hunt_note(serial, live[0], "Waiting", "wait", "Every preset for it is out · goes first when one is back")
        if max_wait and time.time() - float(mr_row(serial).get("hold_at") or time.time()) >= max_wait:
            tried[hold] = time.time()                         # 'Give up on monster' (Patience setting): drop it for now
            mr_save(serial, tried=tried, hold=None, next_at=time.time())
            log(f"[*]  Monster hunts: no preset freed up for {hold} in {round(max_wait / 60)} min - giving up on it")
            _TL.mr_go_on = True
            return
        ht = next(t for t in live if f"{t['x']},{t['y']}" == hold)
        back = mr_next_back(cfg, serial, live)
        wait = min(HUNT_WAIT_CAP_S, max(5, back - time.time())) if back else 20
        hl, hs = _mr_label(ht)
        at = time.strftime('%H:%M', time.localtime(back)) if back else "soon"
        if started or not getattr(_TL, "mr_said_wait", 0) or time.time() - _TL.mr_said_wait > 300:
            _TL.mr_said_wait = time.time()
            log(f"[*]  Monster hunts: every free preset is busy - holding {hl}, next preset back ~{at}")
        hunt_status(serial, "waiting", "Waiting for presets", f"Holding {hs} · next preset back ~{at}")
        mr_save(serial, tried=tried, next_at=time.time())
        _TL.mr_go_on = True
        if hunt_nap(dev, cfg, log, stop, serial, wait, f"holding {hs} - next preset back ~{at}"):
            return                                           # handoff (kept in _TL.hunt_handoff): the hold stays
        return
    if started:
        _TL.mr_go_on = True
        return later(0, f"{started} hunt(s) started, looking for the next one")
    _TL.mr_go_on = _TL.mr_idle = True
    hunt_status(serial, "waiting", "Waiting for monsters", "Every coordinate tried was gone or taken · checks again in 1 min")
    later(MR_POLL_MIN, "every coordinate tried was gone or taken")


def mr_hunt_one(dev, cfg, log, stop, serial, tgt, pair, tried, later, keep_free=0, refill=True, skip_lines=False):
    """Fly to one target and hunt it with this pair's preset (or another FREE preset of the same mode that has it).
    -> "started" | "gone" | "other" | "taken" (blocked) | "busy" (preset / marches out: marked, nothing waited) |
       "later" (pass ends, next_at set) | "stop". Never parks on the monster (owner 29 Oct 13:31)."""
    preset, solo = pair["preset"], pair["mode"] == "solo"
    rtime = str(pair["rule"].get("time") or "5")
    key = f"{tgt['x']},{tgt['y']}"
    label, short = _mr_label(tgt)
    far = f" · {tgt['km']} km" if tgt.get("km") is not None else ""
    hunt_status(serial, "running", f"{'Attacking' if solo else 'Going to rally'} {short} with Preset {mr_pnum(preset)}",
                f"Flying to X {tgt['x']} Y {tgt['y']}{far}")
    mr_block(key, serial, "picked")
    tried[key] = time.time()
    mr_save(serial, tried=tried)

    def release(out=None, slots=None, hold_it=False):       # not hunted now: it stays in the cache for the next pass
        tried.pop(key, None)
        kw = {"tried": tried}
        if out:
            po = {p: u for p, u in (mr_row(serial).get("pout") or {}).items() if float(u) > time.time()}
            po.update(out)
            kw["pout"] = po
        if slots:
            kw["slots_until"] = slots
        if hold_it:
            kw["hold"] = key
        mr_save(serial, **kw)

    if not mr_search(dev, stop, tgt["x"], tgt["y"]):
        later(MR_POLL_MIN, "the coordinate search did not open")
        return "later"
    _nap(stop, 1.0, 1.4)
    mr_fold_panel(dev, stop, log)                            # owner 25 Oct: an open March panel hides the monster's Attack
    shot = dev.screenshot()
    rd_snap(shot, "mrally_map")
    if view_of(shot, cfg) not in ("landscape", "world"):     # a popup / restart took the map away
        tried.pop(key, None)
        later(1, "the map was closed")
        return "later"
    _TL.hunt_map_ok = time.time()
    if skip_lines and mr_march_line(shot):
        mr_block(key, serial, "rallied")
        log(f"[*]  Monster rally: {label} - a march line is already going to it, skipped")
        return "taken"
    mk = mr_march_look(dev, cfg, stop, log, shot)          # quick look at the March panel before every hunt (owner 29 Oct)
    if mk and mk[1] - mk[0] <= keep_free:                    # every march is out: no waiting on the monster
        release(slots=time.time() + min(HUNT_WAIT_CAP_S, max(10, (mk[2] or 60) + 2)), hold_it=not solo)
        hunt_note(serial, tgt, "Waiting", "wait", "Every march is out · tries again when one is back")
        log(f"[*]  Monster hunts: {label} - every march is out, back to the list")
        return "busy"
    if stop.is_set():
        return "stop"
    got, page = mr_open_monster(dev, stop, tgt.get("name") or "", tgt.get("level"))
    if got == "gone":
        hunt_note(serial, tgt, "Skipped", "skip", "Gone before arrival")
        mr_block(key, serial, "dead")
        log(f"[*]  Monster rally: {label} - the monster is not there any more, skipped")
        return "gone"
    if got == "other":
        hunt_note(serial, tgt, "Skipped", "skip", "Spot taken by another monster")
        mr_block(key, serial, "dead")
        log(f"[*]  Monster rally: {label} - another monster stands there ({page}), skipped")
        return "other"
    nomarch = time.time() + HUNT_WAIT_CAP_S                  # the game would not open a march: treat the marches as out 1 min
    if solo:                                                 # Solo: Attack opens the troop page straight away (no rally time)
        dev.tap(MR_ATTACK[0], mr_button_y(page))              # buttons sit higher when the page shows an ad row
        _nap(stop, 1.0, 1.2)
        for _ in range(12):
            shot = dev.screenshot()
            if rd_seen(shot, ["Select a Preset"], region=(0, 0, 540, 180)):
                break
            _nap(stop, 0.6, 0.8)
        else:
            rd_snap(shot, "hunt_solo_nopage")
            if view_of(shot, cfg) not in ("landscape", "world"):
                dev.back()
                _nap(stop, 1.0, 1.3)
            release(slots=nomarch)
            hunt_note(serial, tgt, "Skipped", "skip", "No troop page after Attack (no free march?)")
            log(f"[*]  Monster hunts: {label} - no troop page after Attack (no free march?), back to the list")
            return "busy"
        rd_snap(shot, "hunt_solo_troops")
    else:
        opened = False
        for attempt in range(2):                             # the rally time window can be slow: one more open, no waiting
            dev.tap(MR_ALLIANCE_WAR[0], mr_button_y(page))
            _nap(stop, 1.0, 1.2)
            for _ in range(5):
                shot = dev.screenshot()
                if rd_seen(shot, ["Alliance War Rally", "rally time"], region=(0, 300, 540, 160)):
                    opened = True
                    break
                _nap(stop, 0.7, 0.9)
            if opened or attempt:
                break
            rd_snap(shot, "mrally_time")
            if view_of(shot, cfg) not in ("landscape", "world"):
                dev.back()
                _nap(stop, 1.0, 1.3)
            got, page = mr_open_monster(dev, stop, tgt.get("name") or "", tgt.get("level"))
            if got != "ok":
                break
        if not opened:
            rd_snap(shot, "mrally_time")
            if view_of(shot, cfg) not in ("landscape", "world"):
                dev.back()
                _nap(stop, 1.0, 1.3)
            release(slots=nomarch, hold_it=True)
            hunt_note(serial, tgt, "Waiting", "wait", "No rally window (marches busy or no stamina) · held, tries again")
            log(f"[*]  Monster rally: {label} - no rally window (all marches busy?), held - back to the list")
            return "busy"
        dev.tap(*MR_TIMES.get(rtime, MR_TIMES["5"]))         # fixed spot of the 5/10/30/60 min button
        _nap(stop, 1.0, 1.2)
        for _ in range(12):                                  # the troop page can take several seconds to open (owner 23 Oct)
            shot = dev.screenshot()
            if rd_seen(shot, ["Select a Preset"], region=(0, 0, 540, 180)) and not rd_seen(shot, ["rally time"], region=(0, 380, 540, 80)):
                break
            _nap(stop, 0.6, 0.8)
        rd_snap(shot, "mrally_preset_page")
        if not rd_seen(shot, ["Select a Preset", "Alliance War"], region=(0, 0, 540, 180)) or rd_seen(shot, ["rally time"], region=(0, 380, 540, 80)):
            rd_snap(shot, "mrally_nomarch")
            dev.tap(504, 352)                                # X of the rally time popup
            _nap(stop, 1.0, 1.3)
            release(slots=nomarch, hold_it=True)
            hunt_note(serial, tgt, "Waiting", "wait", "No free march yet · held, tries again")
            log(f"[*]  Monster rally: {label} - no free march yet, held - back to the list")
            return "busy"
    # Owner 25 Oct: never March on an empty preset. Try this pair's preset, then the other FREE presets of the same mode
    # that have this monster (box place, then preset number). A preset found empty is marked out, not waited on.
    free_now = mr_free_presets(cfg, serial, {e["preset"] for e in tgt.get("pairs") or []}) | {preset}
    _last = mr_last_used(serial)
    cands = [preset] + [e["preset"] for e in sorted(tgt.get("pairs") or [], key=lambda x: mr_pair_order(x, _last))
                        if e["mode"] == pair["mode"] and e["preset"] != preset and e["preset"] in free_now]
    used, empty = None, []
    for p_ in cands:
        n = RT_PRESETS.index(p_) if p_ in RT_PRESETS else 0
        for _ in range(2):                                   # the first tap on a preset is sometimes lost
            dev.tap(62 + n * 61, 115)
            _nap(stop, 0.6, 0.8)
        shot = dev.screenshot()
        rd_snap(shot, "mrally_troops")
        if mr_preset_loaded(shot):
            used = p_
            break
        empty.append(p_)
        log(f"[*]  Monster rally: {label} - preset {mr_pnum(p_)} is empty (its general is still out)")
    if empty:                                                # Dida 29 Oct: presets found empty 5-10 min after their rally
        try:                                                 # started (the bot counted 6 min) - learn this instance's real
            row_ = mr_row(serial)                            # time home, so a preset still out is not tapped again
            back = float(row_.get("back_min") or MR_MARCH_BACK_MIN)
            for p_ in empty:
                b_ = float((row_.get("busy") or {}).get(p_) or 0)
                if b_ and time.time() - b_ < 1800:
                    rt_ = next((int(r["time"]) for r in mr_rules(cfg) if r["preset"] == p_), 5)
                    back = max(back, min(MR_BACK_MAX_MIN, (time.time() - b_) / 60 - rt_ + 1.5))
            if back != float(row_.get("back_min") or MR_MARCH_BACK_MIN):
                log(f"[i]  Monster hunts: marches take longer to come home here - a preset now counts as back {back:.1f} min after its rally time ends")
            mr_save(serial, back_min=round(back, 2))
        except Exception as _e:
            quiet_err("mr_back_learn", _e)
    elif used:                                               # first preset was home: let the learned time come down slowly
        try:                                                 # (one far monster must not keep every preset waiting)
            back = float(mr_row(serial).get("back_min") or MR_MARCH_BACK_MIN)
            if back > MR_MARCH_BACK_MIN:
                mr_save(serial, back_min=round(max(MR_MARCH_BACK_MIN, back - 0.2), 2))
        except Exception as _e:
            quiet_err("mr_back_decay", _e)
    if used and empty:                                       # Dida 29 Oct: the empty ones were tried again on the next monster
        try:
            po = dict(mr_row(serial).get("pout") or {})
            for p_ in empty:
                po[p_] = time.time() + MR_STILL_OUT_S
            mr_save(serial, pout=po)
        except Exception as _e:
            quiet_err("mr_still_out", _e)
    if not used:
        rd_snap(shot, "mrally_empty_preset")
        mr_to_map(dev, cfg, stop)
        secs = mr_return_secs(dev, cfg, stop, log)           # one March-panel read: the soonest return
        u = time.time() + (max(20, secs + 5) if secs else HUNT_OUT_DEFAULT_S)
        release(out={p: u for p in empty}, hold_it=not solo)
        names = ", ".join(str(mr_pnum(p)) for p in empty)
        hunt_note(serial, tgt, "Waiting", "wait", f"Preset {names} out · other presets keep hunting")
        log(f"[*]  Monster hunts: {label} - preset {names} out (back ~{time.strftime('%H:%M', time.localtime(u))}), "
            f"other presets / targets go meanwhile")
        return "busy"
    if empty:                                                # the ones tried before were empty: mark them out too
        po = {p: u for p, u in (mr_row(serial).get("pout") or {}).items() if float(u) > time.time()}
        po.update({p: time.time() + HUNT_OUT_DEFAULT_S for p in empty})
        mr_save(serial, pout=po)
    first, preset = preset, used
    if not rd_seen(shot, ["Select a Preset", "Alliance War"], region=(0, 0, 540, 180)):
        dev.back()
        raise RuntimeError("no March button (the troop page is gone)")
    st_ = read_stamina(shot)
    if st_ and st_[0] < st_[1]:                              # not enough stamina: use stamina items like the joiner (owner 23 / 28 Oct)
        if not refill:
            dev.back()
            hunt_status(serial, "blocked", "Out of stamina", "Turn on Refill stamina, or wait for stamina to come back")
            hunt_note(serial, tgt, "Waiting", "wait", "Out of stamina · Refill stamina is off")
            later(30, "not enough stamina (Refill stamina is off)")
            return "later"
        log(f"[!]  Monster hunts: not enough stamina ({st_[0]:,} of {st_[1]:,}) - using stamina items")
        if not refill_stamina(dev, cfg, log, stop, st_[1]):
            dev.back()
            hunt_status(serial, "blocked", "No stamina items left", "Monster hunts go on when stamina comes back")
            hunt_note(serial, tgt, "Waiting", "wait", "Out of stamina · no stamina items left")
            later(30, "not enough stamina (and no stamina items)")
            return "later"
        shot = dev.screenshot()
    dev.tap(*MR_MARCH)                                       # fixed spot (the gold label is rarely read, PC 23 Oct); checked below
    _nap(stop, 1.5, 1.8)
    went = False
    for i_ in range(4):                                      # started = back on the map; a warning window = it did not go
        shot = dev.screenshot()
        if rd_seen(shot, ["Select a Preset"], region=(0, 120, 540, 60)) and i_ < 3:
            _nap(stop, 0.8, 1.0)                             # the troop page can stay a moment after March
            continue
        if rd_seen(shot, ["Select a Preset"], region=(0, 120, 540, 60)):
            rd_snap(shot, "mrally_stuck")
            dev.back()
            tried.pop(key, None)
            mr_save(serial, hold=key)
            later(0.5, f"{label} - the march did not leave (no troops?), trying this monster again first")
            return "later"
        if view_of(shot, cfg) in ("landscape", "world"):
            went = True
            break
        _nap(stop, 0.8, 1.0)
    if not went:                                             # owner 25 Oct 20:59: a warning came up, it was logged as started
        rd_snap(shot, "mrally_march_window")
        log(f"[!]  Monster rally: {label} - March did not go (a window came up) - closing it")
        clear_popups(dev, cfg, log, stop, rounds=3, want_city=False)
        tried.pop(key, None)
        mr_save(serial, hold=key)
        later(0.5, f"{label} - not started, trying this monster again first")
        return "later"
    row = mr_row(serial)
    busy = dict(row.get("busy") or {})
    busy[preset] = time.time()
    po = {p: u for p, u in (row.get("pout") or {}).items() if p != preset and float(u) > time.time()}
    kw = {"busy": busy, "pout": po}
    if row.get("hold") == key:
        kw["hold"] = None                                    # the held target is hunted: let go
    mr_save(serial, **kw)
    mr_block(key, serial, "rallied")
    why = (f"Preset {mr_pnum(preset)} · Preset {mr_pnum(first)} also has it but was busy" if preset != first
           else f"Preset {mr_pnum(preset)} · " + ("after the hunt order" if pair.get("after") else mr_why_rank(pair.get('rank') or 0)))
    if solo:
        n_ = mr_solo_done(serial)
        n_[preset] = int(n_.get(preset, 0)) + 1
        mr_save(serial, solo_day=_game_day(), solo_n=n_)
        hunt_note(serial, tgt, "Solo attack", "solo", why)
        hunt_status(serial, "running", f"Attacked {short} with Preset {mr_pnum(preset)}", f"Solo attack sent{far} · looking for the next monster")
        log(f"[+]  Monster hunts: solo attack on {label} - preset {mr_pnum(preset)}")
        return "started"
    hunt_note(serial, tgt, "Rallied", "go", why)
    hunt_status(serial, "running", f"Rallying {short} with Preset {mr_pnum(preset)}", f"{rtime} min rally started{far} · looking for the next monster")
    log(f"[+]  Monster rally: started on {label} - {rtime} min, preset {mr_pnum(preset)}")
    return "started"

# --- Event duties (tester recordings 22-26 Oct: Legion Hunting, Garuda, Windmill, Eagle, Star Trail, Duel, Taotie,
# Great Expedition, Valuable Event, Super Value Return). Events come and go: when the event row / icon is not there the
# duty logs it and is done for the day (rd_nothing), never a failure. Only Claim / Free buttons are pressed; a green
# Claim is checked by its colour, prices / gems / Buy / packages are never pressed (RD_DANGER).
EV_BACK = (46, 40)                                       # round Back arrow, top-left of every event page
EV_CLOSE_SPOT = (110, 250)                               # empty spot above a "Congratulations!" panel on event pages


def ev_greenish(shot, x, y, w=30, h=10):
    """The button under (x, y) is green (Claim / Free), not grey (Claimed) or gold (a price)."""
    try:
        p = shot[max(0, y - h):y + h, max(0, x - w):x + w].reshape(-1, 3).astype(int)
        b, g, r = p[:, 0].mean(), p[:, 1].mean(), p[:, 2].mean()
        return g > r + 15 and g > b + 15
    except Exception:
        return False


def ev_find_btn(shot, words, region, green=True):
    """-> (x, y) of a button whose whole text is one of `words` ('Claim' never matches 'Claimed'), or None."""
    import difflib
    want = [w.lower() for w in words]
    for text, ws in rd_lines(shot, region):
        low = text.lower().strip(".,:;!() ")
        if "claimed" in low or any(d in low for d in RD_DANGER):
            continue
        if any(low == w or difflib.SequenceMatcher(None, low, w).ratio() >= 0.8 for w in want):
            x = int(sum(s[1] for s in ws) / len(ws))
            y = int(sum(s[2] for s in ws) / len(ws))
            if not green or ev_greenish(shot, x, y):
                return x, y
    return None


def ev_close(dev, stop):
    """Close 'Congratulations!' panels on an event page (tap above the panel, never below it: Buy buttons sit there)."""
    for _ in range(4):
        if stop.is_set() or not wheel_reward_panel(dev.screenshot()):
            return
        dev.tap(*EV_CLOSE_SPOT)
        _nap(stop, 0.9, 1.2)


def ev_claims(dev, stop, region=(260, 170, 280, 780), words=("Claim",), scrolls=2, limit=40):
    """Press every green Claim in a quest list (the claimed rows drop to the bottom), scrolling when none is in view.
    -> number pressed."""
    n = miss = 0
    while n < limit and not stop.is_set():
        shot = dev.screenshot()
        p = ev_find_btn(shot, list(words), region)
        if p:
            dev.tap(*p)
            n += 1
            miss = 0
            _nap(stop, 1.2, 1.6)
            ev_close(dev, stop)
            continue
        if miss >= scrolls:
            break
        miss += 1
        x, y, w, h = region
        dev.swipe(270, y + h - 60, 270, y + 120, 600)
        _nap(stop, 1.0, 1.3)
    return n


def ev_red_spots(shot, region, lo=25, hi=400):
    """Small bright-red dots (the game's 'something to claim' badge / red X) in region -> [(x, y)] screen pixels."""
    x0, y0, w, h = region
    hsv = cv2.cvtColor(shot[y0:y0 + h, x0:x0 + w], cv2.COLOR_BGR2HSV)
    m = cv2.inRange(hsv, (0, 150, 150), (8, 255, 255)) | cv2.inRange(hsv, (172, 150, 150), (180, 255, 255))
    n, _, st, cen = cv2.connectedComponentsWithStats(m)
    return [(int(cen[i][0]) + x0, int(cen[i][1]) + y0) for i in range(1, n) if lo <= st[i][4] <= hi]


def ev_close_x(dev, stop, region=(420, 110, 120, 140)):
    """Close a quest window by its red X (top-right, ~496,148 on the recordings); Back when no X is seen."""
    spots = ev_red_spots(dev.screenshot(), region, 40, 1500)
    if spots:
        dev.tap(*spots[0])
    else:
        dev.back()
    _nap(stop, 1.0, 1.3)


def ev_level_rewards(dev, stop, region=(0, 190, 150, 190), limit=12):
    """Battle-pass pages (Wind Power Storage, Expedition Trial, Hall of Historic Generals...): the level icon left of
    the points bar carries a red badge while a free level reward waits. Tap it, close the reward, repeat."""
    n = 0
    for _ in range(limit):
        if stop.is_set():
            break
        dots = ev_red_spots(dev.screenshot(), region)
        if not dots:
            break
        x, y = dots[0]
        dev.tap(x, y + 4)                                # the badge sits on the icon (recordings: 55,213 / 66,294)
        _nap(stop, 1.3, 1.7)
        ev_close(dev, stop)
        n += 1
    return n


def ev_challenge(dev, stop, log, what, tabs=()):
    """Open 'Challenge Quest' on a battle-pass page, claim every quest (in each of `tabs`), close it. -> claims."""
    if not rd_tap(dev, stop, ["Challenge Quest", "Challenge"], region=(330, 150, 210, 300), cutoff=0.7, wait=(1.6, 2.0)):
        rd_snap(dev.screenshot(), "ev_challenge_" + what.replace(" ", "_"))
        return 0
    n = 0
    for t in (tabs or ("",)):
        if t and not rd_tap(dev, stop, [t], region=(0, 250, 540, 140), cutoff=0.75):
            continue
        n += ev_claims(dev, stop, region=(300, 330, 240, 560))
    ev_close_x(dev, stop)
    return n


def ev_center(dev, cfg, log, stop):
    """From the city: open the Event Center (icon picture, else its caption). -> True when its list shows."""
    if not city_task_target(dev, cfg, log, stop, {"name": "Event Center", "target": "tpl:event_center_icon|Center"}, None):
        return False
    _nap(stop, 1.8, 2.3)
    return rd_seen(dev.screenshot(), ["Event Center"], region=(100, 0, 340, 70))


def ev_open(dev, cfg, log, stop, tab, names, title):
    """Event Center > tab > the row of this event (scrolls the list). -> True when opened; False = event not running."""
    if not ev_center(dev, cfg, log, stop):
        raise RuntimeError("the Event Center did not open")
    rd_tap(dev, stop, [tab], region=(0, 55, 540, 80))
    dev.swipe(270, 300, 270, 800, 500)                  # back to the top of the list
    _nap(stop, 0.9, 1.2)
    for i in range(7):
        shot = dev.screenshot()
        p = rd_find(shot, names, region=(0, 150, 540, 780), cutoff=0.75)
        if p:
            dev.tap(p[0], p[1])
            _nap(stop, 2.2, 2.8)
            return True
        if stop.is_set():
            break
        dev.swipe(270, 800, 270, 420, 600)
        _nap(stop, 1.0, 1.3)
    rd_snap(dev.screenshot(), "ev_missing_" + title.replace(" ", "_"))
    log(f"[i]   {title}: not in the Event Center now (event not running) - done for today")
    rd_nothing()
    return False


def ev_tab(dev, stop, words):
    return rd_tap(dev, stop, words, region=(0, 55, 540, 190), cutoff=0.72)


